# ── C27R9 — DESTINOS DO FRONT POR ENV (substitui a injecao da c27r8) ──────────
# Defeitos corrigidos da c27r8 (auditoria do dono): (1) CONFIGURACAO PARCIAL —
# com 1 ou 2 das 3 envs o app saia MISTO (destino real + .invalid), um front
# meio-apontado; agora e TUDO-OU-NADA: 0 envs = arquivo cru com .invalid
# (fail-closed, nada conecta), 3 envs validas = injeta, qualquer outro estado
# = 503 nomeando SO os NOMES das envs com defeito (nunca valores). (2) INSERCAO
# INSEGURA — a c27r8 trocava texto cru dentro de aspas simples do JS: valor com
# ' ou </script> quebrava/injetava script. Agora: cada valor e VALIDADO por
# construcao (URL: urlsplit com identidade explicita, https — http so para
# host de loopback literal —, sem userinfo/query/fragmento/path; chave anon:
# charset [A-Za-z0-9._-], e se for JWT o payload NAO pode ter role
# service_role, e nunca igual a SUPABASE_SERVICE_KEY) E serializado como
# literal JS por json.dumps com escape de < > & U+2028 U+2029 (nao ha como
# fechar a string nem a tag). A troca e ANCORADA na declaracao completa de
# cada constante e exige EXATAMENTE 1 ocorrencia (0 ou 2+ = 500 fail-closed).
_APP_ANCORAS = (
    ("BT_APP_SUPABASE_URL", "const SUPABASE_URL = 'https://CONFIGURAR-SUPABASE-ISOLADO.invalid';", "const SUPABASE_URL = {};"),
    ("BT_APP_SUPABASE_ANON", "const SUPABASE_ANON = 'CONFIGURAR-CHAVE-PUBLICA-ISOLADA';", "const SUPABASE_ANON = {};"),
    ("BT_APP_API_BASE", "const API = 'https://CONFIGURAR-API-ISOLADA.invalid';", "const API = {};"),
)
_APP_LOOPBACK = {"localhost", "127.0.0.1", "::1"}
_APP_CACHE = {}


def _app_url_valida(v):
    from urllib.parse import urlsplit as _us
    import re as _re_app
    if not isinstance(v, str) or v != v.strip() or not v or len(v) > 255:
        return None
    try:
        u = _us(v)
        host = (u.hostname or "")
        porta = u.port
    except Exception:
        return None
    if u.username is not None or u.password is not None or "@" in u.netloc:
        return None
    if u.query or u.fragment or u.path not in ("", "/"):
        return None
    if u.scheme == "https":
        pass
    elif u.scheme == "http" and host in _APP_LOOPBACK:
        pass
    else:
        return None
    if host not in _APP_LOOPBACK:
        rot = host.split(".")
        if len(rot) < 2 or not all(_re_app.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", r) for r in rot):
            return None
    base = f"{u.scheme}://{host}" + (f":{porta}" if porta else "")
    if base != v.rstrip("/"):
        return None          # forma canonica apenas (sem maiusculas/ambiguidades)
    return base


def _app_anon_valida(v):
    import re as _re_app, base64 as _b64, json as _js
    if not isinstance(v, str) or not _re_app.fullmatch(r"[A-Za-z0-9._-]{20,2048}", v):
        return None
    svc = (os.getenv("SUPABASE_SERVICE_KEY") or "").strip()
    if svc and _hmac.compare_digest(svc, v):
        return None          # service key NUNCA vai pro navegador
    partes = v.split(".")
    if len(partes) == 3:
        try:
            pl = partes[1] + "=" * (-len(partes[1]) % 4)
            role = str(_js.loads(_b64.urlsafe_b64decode(pl)).get("role") or "")
        except Exception:
            return None
        if role != "anon":
            return None
    elif v.startswith("sb_secret_"):
        return None
    return v


def _app_literal_js(v):
    return (json.dumps(v, ensure_ascii=True).replace("<", "\\u003c")
            .replace(">", "\\u003e").replace("&", "\\u0026"))


def _app_destinos():
    """(estado, valores|nomes_com_defeito). estado: 'cru' | 'ok' | 'invalido'."""
    brutos = {n: os.getenv(n) for n, _a, _t in _APP_ANCORAS}
    presentes = [n for n, v in brutos.items() if v not in (None, "")]
    if not presentes:
        return "cru", None
    val = {
        "BT_APP_SUPABASE_URL": _app_url_valida(brutos["BT_APP_SUPABASE_URL"]),
        "BT_APP_SUPABASE_ANON": _app_anon_valida(brutos["BT_APP_SUPABASE_ANON"]),
        "BT_APP_API_BASE": _app_url_valida(brutos["BT_APP_API_BASE"]),
    }
    ruins = sorted(n for n, v in val.items() if v is None)
    if ruins:
        return "invalido", ruins
    return "ok", val


@app.get("/app")
def serve_app():
    # Serve o app de backtest (antigo index.html, renomeado para app.html)
    if not os.path.exists("app.html"):
        raise HTTPException(404, "app.html nao encontrado")
    estado, dados = _app_destinos()
    if estado == "cru":
        return FileResponse("app.html", media_type="text/html", headers=_app_cabecalhos())
    if estado == "invalido":
        return JSONResponse(status_code=503, content={
            "erro": "app_destinos_invalidos",
            "detalhe": "configuracao BT_APP_* parcial ou invalida (tudo-ou-nada)",
            "envs_com_defeito": dados})
    chave = (os.path.getmtime("app.html"), tuple(dados[n] for n, _a, _t in _APP_ANCORAS))
    html = _APP_CACHE.get(chave)
    if html is None:
        with open("app.html", encoding="utf-8") as fh:
            html = fh.read()
        for nome, ancora, tpl in _APP_ANCORAS:
            if html.count(ancora) != 1:
                return JSONResponse(status_code=500, content={
                    "erro": "app_ancora_ausente_ou_duplicada", "env": nome})
            html = html.replace(ancora, tpl.format(_app_literal_js(dados[nome])))
        _APP_CACHE.clear()
        _APP_CACHE[chave] = html
    return HTMLResponse(html, headers=_app_cabecalhos())


# C27R20 — a aba do navegador podia ficar dias rodando um app antigo (restauracao de sessao /
# aba nunca recarregada) sem ninguem perceber. "no-store" impede o navegador de guardar o /app;
# /app/versao diz o que o servidor serve AGORA, para o proprio app avisar quando esta defasado.
_APP_CACHE_CONTROL = "no-store, max-age=0, must-revalidate"
_APP_IDENT = {}


def _app_identidade():
    """versao (APP_VERSAO do arquivo), sha256 e tamanho do app.html em disco. Sem segredo."""
    try:
        mt = os.path.getmtime("app.html")
    except Exception:
        return {"existe": False}
    c = _APP_IDENT.get(mt)
    if c is None:
        import hashlib as _hl
        import re
        with open("app.html", "rb") as fh:
            bruto = fh.read()
        m = re.search(rb"const APP_VERSAO = '([^']{1,80})'", bruto)
        c = {"existe": True, "app_versao": m.group(1).decode("ascii", "replace") if m else None,
             "sha256_arquivo": _hl.sha256(bruto).hexdigest(), "bytes_arquivo": len(bruto)}
        _APP_IDENT.clear()
        _APP_IDENT[mt] = c
    return c


def _app_cabecalhos():
    i = _app_identidade()
    h = {"Cache-Control": _APP_CACHE_CONTROL, "Pragma": "no-cache", "Expires": "0"}
    if i.get("app_versao"):
        h["X-BT-App-Versao"] = i["app_versao"]
    c = (os.getenv("RAILWAY_GIT_COMMIT_SHA") or "")[:40]
    if c:
        h["X-BT-Commit"] = c
    return h


@app.get("/app/versao")
def app_versao_servida():
    """O que o /app serve agora. Publico e sem segredo: versao, hash do arquivo e commit."""
    i = _app_identidade()
    estado, _d = _app_destinos()
    return JSONResponse(headers={"Cache-Control": "no-store"}, content={
        "app_versao": i.get("app_versao"), "sha256_arquivo": i.get("sha256_arquivo"),
        "bytes_arquivo": i.get("bytes_arquivo"), "api": API_VERSAO.split(" - ")[0],
        "commit": (os.getenv("RAILWAY_GIT_COMMIT_SHA") or "")[:40] or None,
        "destinos": estado, "cache_control_do_app": _APP_CACHE_CONTROL,
        "nota": "sha256 do app.html em disco; com destinos 'ok' o corpo servido troca 3 constantes de destino"})

