@app.post("/babymachine/contador")
def babymachine_contador(params: BabyMachineContadorParams, authorization: str = Header(default="")):
    """Endpoint leve: retorna só o total de backtests do usuário (p/ contador
    no topo). B09.2: logado conta pela sessão; anônimo segue pelo sessao_id."""
    # B09.2: logado = identidade da sessão; anônimo segue permitido sem
    # identidade — o corpo NUNCA é autoridade (forjar user_id de outro morria
    # aqui como leitura/plano/crédito alheio).
    if (authorization or "").strip():
        _uid_b092 = _sessao_user_id(authorization)
        if (params.user_id or "").strip() and params.user_id.strip() != _uid_b092:
            raise HTTPException(status_code=403, detail="user_id divergente da sessao")
        params.user_id = _uid_b092
    else:
        params.user_id = ""
    try:
        sb = _sb_admin()
        if sb is None:
            return {"total": 0}
        # busca os ids do usuário e conta (sem count=exact, p/ compatibilidade de versão)
        if params.user_id:
            dados = _sb_ler_paginado(lambda a, b: sb.table("backtests_historico").select("id").eq("user_id", params.user_id).range(a, b))
        elif params.sessao_id:
            dados = _sb_ler_paginado(lambda a, b: sb.table("backtests_historico").select("id").eq("sessao_id", params.sessao_id).range(a, b))
        else:
            return {"total": 0}
        total = len(dados)
        return {"total": total}
    except Exception:
        return {"total": 0}


