for _c, _its in CATALOGO_ATIVOS.items():
    for _a in _its:
        _NIVEL_POR_TICKER[_a["ticker"]] = _a.get("nivel", 0)

def _nivel_do_ativo(ativo: str) -> int:
    tk = ATIVOS_MAP.get(ativo, ativo)           # nome -> ticker
    return _NIVEL_POR_TICKER.get(tk, 0)         # desconhecido = liberado (fail-open)

def _sb_credencial_tipo():
    """C27R12 — CLASSE da credencial SUPABASE_SERVICE_KEY, sem expor valor/prefixo.
    'service_role' (JWT role=service_role) | 'secret' (chave secreta nova) |
    'publica' (anon/authenticated/publishable: sob RLS, NAO serve pro servidor) |
    'ausente' | 'desconhecida'. Usada no diagnostico (/versao) e no log de erro."""
    import base64 as _b64, json as _js
    k = (os.getenv("SUPABASE_SERVICE_KEY") or "").strip()
    if not k:
        return "ausente"
    if k.startswith("sb_secret_"):
        return "secret"
    if k.startswith("sb_publishable_"):
        return "publica"
    partes = k.split(".")
    if len(partes) == 3:
        try:
            pl = partes[1] + "=" * (-len(partes[1]) % 4)
            role = str(_js.loads(_b64.urlsafe_b64decode(pl)).get("role") or "")
        except Exception:
            return "desconhecida"
        if role == "service_role":
            return "service_role"
        if role in ("anon", "authenticated"):
            return "publica"
    return "desconhecida"


def _perfil_indisponivel(motivo: str):
    """C27R12 — falha ao CONSULTAR o plano NAO e conta Free. Erro observavel
    (503 perfil_indisponivel + log com motivo e classe da credencial), sem
    expor dados sensiveis. Antes, qualquer falha virava 'free' em silencio e
    o XAU era negado como 'ativo_bloqueado' a uma conta PRO."""
    import sys as _sys
    print(f"[GATING] perfil_indisponivel motivo={motivo} "
          f"credencial={_sb_credencial_tipo()}", file=_sys.stderr)
    return HTTPException(status_code=503, detail={
        "code": "perfil_indisponivel",
        "msg": "Nao foi possivel confirmar seu plano agora. Tente de novo em instantes; "
               "se persistir, avise o suporte (codigo BT-P01)."})


def _perfil_plano_e_creditos(user_id: str):
    """Retorna (plano, free_tests_usados, sb).
    C27R12: a consulta do PLANO e estrita — sem cliente de servidor, credencial
    publica, erro de consulta ou perfil inexistente = 503 perfil_indisponivel
    (nunca 'free' por omissao). So o contador free_tests_usados segue tolerante
    (coluna pode nao existir no schema; ausente = 0)."""
    sb = _sb_admin()
    if sb is None:
        raise _perfil_indisponivel("servidor_sem_credencial")
    if _sb_credencial_tipo() == "publica":
        # sob RLS a linha do perfil e invisivel ao servidor: nao adianta consultar
        raise _perfil_indisponivel("credencial_publica_no_servidor")
    try:
        r = (sb.table("perfis").select("plano,plano_valido_ate")
             .eq("id", user_id).limit(1).execute())
        rows = r.data or []
    except Exception as _e:
        raise _perfil_indisponivel(f"erro_consulta({type(_e).__name__})")
    if not rows:
        raise _perfil_indisponivel("perfil_nao_encontrado")
    d = rows[0]
    plano_ef = _plano_vigente(d.get("plano") or "free", d.get("plano_valido_ate"))
    usados = 0
    try:
        r2 = (sb.table("perfis").select("free_tests_usados")
              .eq("id", user_id).limit(1).execute())
        usados = int(((r2.data or [{}])[0]).get("free_tests_usados") or 0)
    except Exception:
        usados = 0     # coluna opcional: contador tolerante, plano NAO
    return (plano_ef, usados, sb)

def _email_confirmado(user_id):
    """True se o email do usuário está confirmado. Anti multi-conta no Free.
       FALHA ABERTA de propósito: se a checagem der erro, NÃO trava o usuário
       legítimo (preferimos deixar passar a bloquear quem tem direito)."""
    try:
        sb = _sb_admin()
        if sb is None:
            return True
        resp = sb.auth.admin.get_user_by_id(user_id)
        user = getattr(resp, "user", None)
        if user is None and isinstance(resp, dict):
            user = resp.get("user")
        ts = getattr(user, "email_confirmed_at", None) if user is not None else None
        if ts is None and isinstance(user, dict):
            ts = user.get("email_confirmed_at")
        return bool(ts)
    except Exception as _e:
        import sys as _sys
        print(f"[GATING] checagem email_confirmado falhou (deixando passar): {_e}", file=_sys.stderr)
        return True


def _consumir_credito_backtest(user_id, ativo: str):
    """Porteiro chamado no topo dos endpoints de backtest.
       Levanta HTTPException com detail ESTRUTURADO pro front reagir."""
    if not user_id:
        raise HTTPException(status_code=401, detail={
            "code": "login_necessario",
            "msg": "Crie uma conta grátis pra rodar seu backtest."})
    plano, usados, sb = _perfil_plano_e_creditos(user_id)
    nivel_user = _PLANO_NIVEL.get(plano, 0)
    # ativo bloqueado pro plano (ex.: Free tentando XAU)
    if _nivel_do_ativo(ativo) > nivel_user:
        raise HTTPException(status_code=403, detail={
            "code": "ativo_bloqueado", "plano": plano, "ativo": ativo,
            "msg": "Esse ativo faz parte de um plano superior."})
    # pago = ilimitado
    if nivel_user >= 1:
        return {"plano": plano, "ilimitado": True}
    # free precisa de email confirmado (anti multi-conta com emails descartáveis)
    if not _email_confirmado(user_id):
        raise HTTPException(status_code=403, detail={
            "code": "email_nao_confirmado",
            "msg": "Confirme seu email para liberar seus 3 backtests gratuitos."})
    # free = consome 1 dos 3
    if usados >= LIMITE_FREE_TESTS:
        raise HTTPException(status_code=402, detail={
            "code": "free_esgotado", "usados": usados, "limite": LIMITE_FREE_TESTS,
            "msg": "Você usou seus 3 backtests gratuitos."})
    novos = usados + 1
    if sb is not None:
        try:
            sb.table("perfis").update({"free_tests_usados": novos}).eq("id", user_id).execute()
        except Exception as _e:
            import sys as _sys
            print(f"[GATING] não consegui gravar free_tests_usados (coluna existe?): {_e}", file=_sys.stderr)
    return {"plano": plano, "ilimitado": False, "usados": novos,
            "restantes": max(0, LIMITE_FREE_TESTS - novos)}

@app.get("/free/status")
def free_status(authorization: str = Header(default="")):
    """Front consulta pra mostrar 'X de 3' e saber se congelou — sem rodar teste.
    B09 (AUT-007): deslogado segue com a resposta anônima; LOGADO é a sessão que
    diz quem é — user_id de query morreu."""
    user_id = _sessao_user_id(authorization) if (authorization or "").strip() else ""
    if not user_id:
        return {"logado": False, "plano": "free", "usados": 0,
                "limite": LIMITE_FREE_TESTS, "restantes": LIMITE_FREE_TESTS, "congelado": False}
    plano, usados, _ = _perfil_plano_e_creditos(user_id)
    if _PLANO_NIVEL.get(plano, 0) >= 1:
        return {"logado": True, "plano": plano, "ilimitado": True, "congelado": False}
    return {"logado": True, "plano": plano, "ilimitado": False,
            "usados": usados, "limite": LIMITE_FREE_TESTS,
            "restantes": max(0, LIMITE_FREE_TESTS - usados),
            "congelado": usados >= LIMITE_FREE_TESTS}


