            if recente and mesmo_nivel and i2 != self.usado_baixa:
                pescoco = max(h[m] for m in range(i1, i2 + 1))
                if c[-1] > pescoco:
                    altura = pescoco - (p1 + p2) / 2
                    self.stop = min(p1, p2)
                    self.alvo = pescoco + altura
                    self.usado_baixa = i2
                    self.buy()
