class ConectorRegistrar(BaseModel):
    # R2 P1: user_id do corpo NAO e autoridade — a identidade vem da sessao
    # (Authorization: Bearer). Campo mantido opcional so pra compat: se vier
    # preenchido e divergir da sessao, o endpoint responde 403.
    user_id: str = ""
    nome: str = "Meu Bot"
    simbolo: str = ""
    magic_number: Optional[int] = None

class ConectorSnapshot(BaseModel):
    bot_token: str
    conta_login: Optional[str] = None
    corretora: Optional[str] = None
    simbolo: Optional[str] = None
    magic_number: Optional[int] = None
    equity: Optional[float] = None
    balance: Optional[float] = None
    margem_livre: Optional[float] = None
    posicoes_abertas: int = 0
    lucro_flutuante: Optional[float] = None
    drawdown_atual: Optional[float] = None   # em % (ex: 4.2)
    direcao_d1: Optional[str] = None         # compra | venda | lateral
    padrao_ativo: Optional[str] = None
    detalhe: Optional[dict] = None

class ConectorEvento(BaseModel):
    bot_token: str
    tipo: str                                 # trade_aberto | trade_fechado | reversao | piramide | erro
    detalhe: Optional[dict] = None

class ConectorExcluir(BaseModel):
    user_id: Optional[str] = None    # caminho plataforma (front já manda user_id)
    bot_id: int
    bot_token: Optional[str] = None  # caminho conector (deleta via token do bot)

class SugestaoLida(BaseModel):
    user_id: str = ""   # B09: identidade vem da sessao; campo so por compatibilidade
    sugestao_id: int


# ════════════════════════════════════════════════════════════════════════════
#  v6.67 — COCKPIT DE ANÁLISE CRUZADA (BOT + IA)
#
#  Não é chat: são dois pareceres independentes sobre o MESMO momento
#  (A leitura do BOT vem do EA no MT5; a análise da IA vem daqui com o
#  snapshot como base) + uma SÍNTESE do cruzamento (VEREDITO).
#
#  Uma única chamada de IA por rodada devolve JSON com {analise_ia, veredito,
#  sinal}. O front renderiza cada campo no seu bloco.
#
#  Estado em memória (por worker). Sem tabela — se Railway reinicia, começa
#  do zero: análise cruzada é INTERPRETAÇÃO viva, não dado regulatório.
# ════════════════════════════════════════════════════════════════════════════
import time as _time_anl
from collections import deque as _deque_anl

_ANL_HIST = {}          # bot_id (int) -> deque[dict]
_ANL_LAST = {}          # bot_id -> {assinatura, ts_ultima_analise}
_ANL_FALHA = {}         # v6.93 — bot_id -> {ts, motivo}: por que a última geração morreu
_ANL_ERRO_ULT = {}      # v6.93 — {ts, motivo} do último erro do _analisar_ia (por worker)
_ANL_HIST_MAX = 30      # 30 análises = ~30-90 min de cockpit aberto
_ANL_COOLDOWN_SEG = 30  # entre análises de status (eventos ignoram)
_ANL_SILENCIO_SEG = 300  # v7.00: cadência de 5 MIN (decisão do dono) — padrão se forma no FECHAMENTO da vela; ler a cada 90s = ler 3x a mesma vela de 5m pela metade


def _anl_hist(bot_id):
    if bot_id not in _ANL_HIST:
        _ANL_HIST[bot_id] = _deque_anl(maxlen=_ANL_HIST_MAX)
    return _ANL_HIST[bot_id]


def _anl_push(bot_id, entrada):
    """Empilha análise cruzada no histórico com timestamp ISO."""
    if not entrada:
        return
    entrada = dict(entrada)
    entrada["ts"] = _dt.now(_tz.utc).isoformat()
    _anl_hist(bot_id).append(entrada)


def _anl_assinatura(bot_leitura):
    """Assinatura curta do que o bot vê AGORA. Muda entre ticks =
    algo novo aconteceu (regime, padrões, posições)."""
    if not bot_leitura:
        return ""
    reg = ((bot_leitura.get("regime") or {}).get("estado") or "").lower()
    pads = [(p.get("nome") or p.get("padrao") or "") + ":" + str(p.get("tf") or "")
            for p in (bot_leitura.get("padroes") or [])]
    pos = bot_leitura.get("posicoes") or 0
    return f"{reg}|{pos}|{','.join(sorted(pads))}"


def _anl_idioma_do_user(sb, user_id):
    try:
        p = sb.table("perfis").select("idioma").eq("id", user_id).limit(1).execute()
        return (p.data[0].get("idioma") if p.data else None) or "pt"
    except Exception:
        return "pt"


def _analisar_ia(ctx, gatilho="status"):
    """Chama Anthropic Haiku e devolve {analise_ia, veredito, sinal}. Uma
    chamada, três outputs. Any falha -> None (caller não empurra ao histórico)."""
    import sys
    chave = os.environ.get("ANTHROPIC_API_KEY", "").strip()
    if not chave:
        _ANL_ERRO_ULT.update({"ts": _time_anl.time(), "motivo": "ANTHROPIC_API_KEY ausente no ambiente"})
        return None
    idioma = ctx.get("idioma", "pt")
    idioma_nome = _IDIOMA_NOME.get(idioma, "português brasileiro")
    try:
        import httpx
        sistema = (
            "Você é a inteligência analítica de uma plataforma de trading que assiste um bot "
            "rodando ao vivo no MetaTrader 5 do usuário. Sua função: fazer análise TÉCNICA "
            "CONTEXTUAL do momento atual do mercado deste bot, cruzando o que o EA está vendo "
            "(narração mecânica) com o QUE VOCÊ SABE sobre esse ativo neste timeframe.\n\n"
            "PRINCÍPIO CENTRAL — VOCÊ ABSORVE, NÃO CONSULTA. Quando o contexto trouxer estatística "
            "de padrão medido neste ativo (campo 'confirmacao': ex. veredito 'Engolfo no 5m: medido "
            "42x, 68% confirmou'), você INCORPORA isso como CONHECIMENTO PRÓPRIO. Fale como analista "
            "experiente que SABE, nunca como sistema que consultou tabela. NUNCA diga 'no banco de "
            "dados', 'na tabela', 'na nossa base', 'consultei'. DIGA: 'no histórico deste ativo, esse "
            "padrão tende a converter em torno de 70%', 'já vi esse cenário antes: quando o 4h está "
            "lateral e o 5m rompe, a taxa cai bastante', 'esse tipo de rompimento após consolidação "
            "assim historicamente favorece o lado da tendência maior'.\n\n"
            "REGRAS INVIOLÁVEIS:\n"
            "(1) NUNCA prometa lucro, NUNCA preveja o mercado. Use 'pode', 'tende', 'historicamente "
            "favorece', 'aumenta/reduz a probabilidade'. Proibido: 'vai', 'garante', 'certamente', "
            "'100%';\n"
            "(2) escreva NO IDIOMA: " + idioma_nome + "; tom de mentor experiente, direto, sem "
            "enfeite; sem markdown; sem crases;\n"
            "(3) VAREIE aberturas e estrutura — nunca comece 2 análises seguidas do mesmo jeito;\n"
            "(4) NUNCA mencione outros usuários, comunidade, base coletiva, dados de outras pessoas. "
            "'no histórico deste ativo' é ok, 'outros traders' não é;\n"
            "(5) se um dado vier null/ausente, simplesmente não fale dele.\n\n"
            "COMO CRUZAR AS DUAS LEITURAS:\n"
            "Você recebe narracao_mecanica (o que o EA reportou — texto curto factual do MT5) "
            "e os dados crus do momento (preço, EMAs, regime por TF, padrões, estrutura, confirmação). "
            "Sua ANÁLISE deve dialogar com o que o BOT vê, acrescentando contexto que ele SOZINHO não "
            "teria (histórico, outros TFs, níveis, força estatística).\n\n"
            "MOMENTUM POR TIMEFRAME — SEU TRUNFO DE MENTOR HUMANO:\n"
            "O campo momentum_tfs traz descrições curtas do momentum recente de cada TF principal "
            "(5m, 15m, 60m, 4h). Ex.: 5m=3 velas de alta consecutivas, corpos crescentes / 4h=alternancia "
            "(2 de alta / 2 de baixa), corpos encolhendo. USE isso pra SOAR COMO MENTOR EXPERIENTE, "
            "descrevendo NATURALMENTE — o 15m ganhou força nas últimas velas mas o 4h ainda está lateral, "
            "os TFs curtos aceleraram enquanto o 4h continua indeciso, divergência entre TFs: 5m puxando "
            "pra cima, 60m estagnou. NUNCA liste como relatório técnico (5m: alta / 15m: neutro / ...) "
            "— isso é frio. VARIE quais TFs você menciona, use os que fazem sentido pro momento — não é "
            "obrigatório citar todos.\n\n"
            "SCANNER MULTI-TF DO BOT — MAIS OLHOS PRA VOCÊ:\n"
            "O campo scanner traz o pente-fino mecânico do BOT por timeframe a partir do 1m: "
            "comportamento de cada TF (tendência/lateral/reversão se formando), cascata_reversao "
            "(reversão detectada no 1m -> confirmando no 5m -> aguardando o 15m) e alinhamento "
            "(quantos TFs puxam pro mesmo lado). USE isso pra ANTECIPAR padrões EM CONSTRUÇÃO — "
            "especialmente reversões (a cascata) e tendências (o alinhamento) — cruzando com o "
            "histórico medido deste ativo. Se a cascata contradiz o alinhamento, esse conflito É a "
            "análise. Cite os TFs na ordem do menor pro maior.\n\n"
            "VISÃO DO OPERADOR — QUANDO PRESENTE NO CONTEXTO:\n"
            "O campo visao_operador traz a leitura que o PRÓPRIO usuário enviou (texto e/ou "
            "resumo do print que ele marcou; enviada_ha_min diz há quanto tempo). REGRA "
            "INEGOCIÁVEL: você CRUZA essa leitura com os dados — nunca obedece cegamente, "
            "nunca ignora. Se os dados sustentam a visão dele, REFORCE citando os números que "
            "confirmam (você apontou o topo em 4020 — de fato, 3 toques no 15m seguram ali). "
            "Se contradizem, DISCORDE com respeito e com números (preços, toques, TFs). Se não "
            "dá pra confirmar nem negar, diga o que precisaria acontecer pra validar. Converse "
            "como dois analistas: você apontou X — os dados mostram Y. A visão do operador "
            "NUNCA vira ordem de execução, recomendação de entrada imediata nem promessa. "
            "Quando houver visao_operador, o VEREDITO também deve dizer se está ALINHADO ou "
            "DIVERGENTE com a leitura do operador.\n\n"
            "E o VEREDITO conclui se as duas visões:\n"
            "  - 'alinhado' -> BOT e contexto histórico apontam pra mesma direção;\n"
            "  - 'divergente' -> BOT vê uma coisa, contexto sugere outra;\n"
            "  - 'adicao' -> BOT está neutro/esperando, IA acrescenta info relevante que ele não "
            "citou (nível próximo, virada em outro TF);\n"
            "  - 'neutro' -> sem sinal forte pra nenhum lado, momento morno.\n\n"
            "FORMATO DA RESPOSTA — SOMENTE um objeto JSON com EXATAMENTE 3 chaves:\n"
            "{\"analise_ia\": \"...\", \"veredito\": \"...\", \"sinal\": \"...\"}\n"
            "- analise_ia: 2 a 4 frases, máx ~360 caracteres, sem markdown;\n"
            "- veredito: 1 linha citável, máx ~130 caracteres, começa com palavra-chave em MAIÚSCULAS "
            "(ex.: ALINHADOS, DIVERGÊNCIA, ATENÇÃO, OBSERVAÇÃO), depois travessão e o resumo;\n"
            "- sinal: exatamente uma de: alinhado, divergente, adicao, neutro.\n"
            "Nada fora do JSON. Nada de crases. Nada de markdown."
        )
        r = httpx.post(
            "https://api.anthropic.com/v1/messages",
            headers={
                "x-api-key": chave,
                "anthropic-version": "2023-06-01",
                "content-type": "application/json",
            },
            json={
                "model": os.environ.get("RADAR_IA_MODELO", "claude-haiku-4-5-20251001"),
                "max_tokens": 600,
                "temperature": 0.95,
                "system": sistema,
                "messages": [{"role": "user", "content":
                    "Gatilho: " + gatilho + "\n"
                    "Contexto ao vivo do bot (JSON):\n" + json.dumps(ctx, ensure_ascii=False)}],
            },
            timeout=25.0,   # v6.92 — o contexto cresceu (scanner/momentum/estrutura); 10s estourava
        )
        if r.status_code != 200:
            print(f"ANALISE IA status {r.status_code}: {r.text[:200]}", file=sys.stderr)
            _mot = f"IA respondeu status {r.status_code}"
            if r.status_code == 429: _mot += " (limite de requisições — normaliza sozinho)"
            elif r.status_code == 404: _mot += " (modelo não encontrado — conferir RADAR_IA_MODELO)"
            elif r.status_code in (500, 502, 503, 529): _mot += " (instabilidade do provedor)"
            _ANL_ERRO_ULT.update({"ts": _time_anl.time(), "motivo": _mot})
            return None
        texto = "".join(b.get("text", "") for b in r.json().get("content", []))
        texto = (texto or "").strip()
        if not texto:
            _ANL_ERRO_ULT.update({"ts": _time_anl.time(), "motivo": "resposta vazia da IA"})
            return None
        # v6.92 — PARSE RESILIENTE EM CAMADAS: a análise NUNCA morre por formato.
        # Camada 1: primeiro bloco {...} do texto (ignora prefixo/sufixo/fences).
        obj = None
        try:
            _i = texto.find("{")
            _f = texto.rfind("}")
            if _i >= 0 and _f > _i:
                obj = json.loads(texto[_i:_f + 1])
        except Exception:
            obj = None
        # Camada 2: regex campo a campo (JSON truncado no meio ainda rende os
        # campos que chegaram inteiros).
        if not isinstance(obj, dict):
            import re as _re_anl
            obj = {}
            for _campo in ("analise_ia", "veredito", "sinal"):
                _m = _re_anl.search('"' + _campo + '"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"', texto)
                if _m:
                    try:
                        obj[_campo] = json.loads('"' + _m.group(1) + '"')
                    except Exception:
                        obj[_campo] = _m.group(1)
        an = str((obj or {}).get("analise_ia") or "").strip()
        vr = str((obj or {}).get("veredito") or "").strip()
        sn = str((obj or {}).get("sinal") or "").strip().lower()
        # Camada 3: degrada com honestidade — entrega o texto bruto limpo em
        # vez de sumir da tela (melhor uma análise sem moldura que tela vazia).
        if not an:
            _limpo = texto.replace("```json", " ").replace("```", " ").strip()
            if len(_limpo) < 30:
                print("ANALISE IA vazia demais pra degradar", file=sys.stderr)
                _ANL_ERRO_ULT.update({"ts": _time_anl.time(), "motivo": "resposta curta demais pra aproveitar"})
                return None
            an = _limpo
        if not vr:
            vr = "OBSERVAÇÃO — " + an.split(".")[0][:110]
        if sn not in ("alinhado", "divergente", "adicao", "neutro"):
            sn = "neutro"
        return {"analise_ia": an[:600], "veredito": vr[:200], "sinal": sn}
    except Exception as e:
        import traceback
        print(f"ANALISE IA erro: {e}\n{traceback.format_exc()}", file=sys.stderr)
        _mot = type(e).__name__
        if "Timeout" in _mot: _mot = "sem resposta da IA dentro do tempo (timeout)"
        _ANL_ERRO_ULT.update({"ts": _time_anl.time(), "motivo": _mot})
        return None


def _analisar_por_gatilho(sb, bot_id, user_id, gatilho,
                          leitura_atual=None, ctx_extra=None):
    """Gera análise cruzada, grava no histórico, atualiza assinatura/cooldown.
    Silencioso em erro — cockpit nunca deve quebrar fluxo real."""
    try:
        # v7.00 — CADÊNCIA DE 5 MIN (decisão do dono): o mercado que os bots
        # operam fecha vela em 1m/5m/15m — padrão se forma no FECHAMENTO, não
        # no meio da vela. UMA análise de IA por janela de 5 min lê o que
        # fechou no 1m/5m e o que está formando no 15m; mais que isso é a
        # mesma informação repetida com custo triplo. PISO GLOBAL por bot:
        # qualquer gatilho (evento, assinatura, silêncio) respeita 300s desde
        # a última análise. Exceção única: visão do operador (ação humana
        # explícita merece resposta na hora). O determinístico (scanner,
        # range, cascata, narração-cache) segue a cada snapshot, custo zero.
        if gatilho != "visao_operador":
            _piso = globals().setdefault("_ANL_PISO_ULT", {})
            _ag_p = _time_anl.time()
            if (_ag_p - float(_piso.get(bot_id) or 0)) < 300:
                return
            _piso[bot_id] = _ag_p
        ctx = {
            "idioma": _anl_idioma_do_user(sb, user_id),
            "gatilho": gatilho,
        }
        if leitura_atual:
            ctx["momento"] = {
                "simbolo": leitura_atual.get("simbolo"),
                "tf_op": leitura_atual.get("tf_op"),
                "preco": leitura_atual.get("preco"),
                "ema_h": leitura_atual.get("ema_h"),
                "ema_l": leitura_atual.get("ema_l"),
                "posicoes": leitura_atual.get("posicoes"),
                "flutuante": leitura_atual.get("flutuante"),
                "regime": leitura_atual.get("regime"),
                "padroes": leitura_atual.get("padroes"),
                "estrutura": leitura_atual.get("estrutura"),
                "zonas": leitura_atual.get("zonas"),
                "confirmacao": leitura_atual.get("confirmacao"),
                # v6.68 — resumo semantico por TF (mentor humano descritivo)
                "momentum_tfs": leitura_atual.get("momentum_tfs"),
                # A leitura mecanica do bot e o "BOT falou X" que a IA vai cruzar
                "narracao_mecanica": leitura_atual.get("narracao_bot"),
                # v6.82 — pente-fino multi-TF do BOT (scanner + cascata + alinhamento)
                "scanner": leitura_atual.get("scanner"),
            }
        if ctx_extra:
            ctx["evento"] = ctx_extra
        # v6.81 — VISÃO DO OPERADOR: se o usuário enviou a leitura dele (texto
        # e/ou print resumido), entra em TODA análise até expirar (TTL 2h).
        _vis = _visao_op_ativa(bot_id)
        if _vis:
            ctx["visao_operador"] = {
                "texto": _vis.get("texto"),
                "print_resumo": _vis.get("resumo_img"),
                "enviada_ha_min": int((_time_anl.time() - _vis.get("ts", 0)) / 60),
            }
        # últimas análises (contexto de continuidade — variar aberturas)
        hist = list(_anl_hist(bot_id))[-3:]
        if hist:
            ctx["analises_recentes"] = [{"veredito": h.get("veredito"),
                                         "sinal": h.get("sinal")} for h in hist]
        result = _analisar_ia(ctx, gatilho=gatilho)
        if not result:
            # v6.92 — BACKOFF DE FALHA: sem análise (API fora/timeout), marca o
            # momento mesmo assim — a próxima tentativa vem pelo ciclo de
            # silêncio (90s), não a cada tick de 6s. Fim do loop de queima.
            _ANL_LAST[bot_id] = {
                "assinatura": _anl_assinatura(leitura_atual) if leitura_atual else "",
                "ts": _time_anl.time(),
            }
            # v6.93 — a falha vira INFORMAÇÃO na tela (motivo exato no Bloco B)
            _mot = (_ANL_ERRO_ULT.get("motivo") or "geração sem retorno") \
                if (_time_anl.time() - float(_ANL_ERRO_ULT.get("ts") or 0)) < 60 else "geração sem retorno"
            _ANL_FALHA[bot_id] = {"ts": _time_anl.time(), "motivo": _mot}
            return
        entrada = {
            "gatilho": gatilho,
            "leitura_bot": (leitura_atual or {}).get("narracao_bot"),
            "analise_ia": result["analise_ia"],
            "veredito": result["veredito"],
            "sinal": result["sinal"],
        }
        _anl_push(bot_id, entrada)
        _ANL_FALHA.pop(bot_id, None)   # v6.93 — sucesso limpa a falha da tela
        _ANL_LAST[bot_id] = {
            "assinatura": _anl_assinatura(leitura_atual) if leitura_atual else "",
            "ts": _time_anl.time(),
        }
    except Exception as _e:
        try: print(f"[analise] gatilho={gatilho} erro: {_e}")
        except Exception: pass


# ════════════════════════════════════════════════════════════════════════════
#  v6.81 — VISÃO DO OPERADOR (Sessão C do diferencial de informação)
#
#  O usuário passa a ter voz DENTRO da análise cruzada: texto curto e/ou um
#  print do gráfico dele. A visão fica ativa por 2h (ou até limpar/substituir)
#  e é injetada em toda análise como bloco visao_operador. A IA cruza com
#  honestidade (concorda/discorda com números) — nunca obedece cegamente e
#  NUNCA vira execução: ordem continua só pelos botões do Copiloto/Automático.
#
#  Print: UMA chamada de visão (Haiku) extrai um resumo estruturado; a imagem
#  é lida uma vez e DESCARTADA — as análises seguintes usam só o resumo.
#  Estado em memória por worker (mesma classe do _ANL_HIST): interpretação
#  viva, não dado regulatório. Zero SQL.
# ════════════════════════════════════════════════════════════════════════════

_VISAO_OP = {}                 # bot_id (int) -> {texto, resumo_img, ts, expira}
_VISAO_OP_TTL_SEG = 2 * 3600   # 2 horas de validade


def _visao_op_ativa(bot_id):
    v = _VISAO_OP.get(bot_id)
    if not v:
        return None
    if _time_anl.time() > v.get("expira", 0):
        _VISAO_OP.pop(bot_id, None)
        return None
    return v


def _visao_op_publica(bot_id):
    """Shape seguro pro front (chip 👁 no cockpit)."""
    v = _visao_op_ativa(bot_id)
    if not v:
        return None
    resta = max(0, int((v.get("expira", 0) - _time_anl.time()) / 60))
    return {"texto": v.get("texto") or None,
            "tem_print": bool(v.get("resumo_img")),
            "resta_min": resta}


def _visao_op_extrair_print(img_b64, img_tipo, idioma="pt"):
    """UMA chamada de visão: lê o print que o operador marcou e devolve um
    resumo curto e factual (níveis, linhas, padrões apontados). A imagem não
    é guardada. Falha -> None (a visão segue só com o texto)."""
    import sys
    chave = os.environ.get("ANTHROPIC_API_KEY", "").strip()
    if not chave or not img_b64:
        return None
    idioma_nome = _IDIOMA_NOME.get(idioma, "português brasileiro")
    try:
        import httpx
        r = httpx.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": chave, "anthropic-version": "2023-06-01",
                     "content-type": "application/json"},
            json={
                "model": os.environ.get("RADAR_IA_MODELO", "claude-haiku-4-5-20251001"),
                "max_tokens": 300,
                "temperature": 0.2,
                "system": (
                    "Você lê PRINTS de gráficos de trading que o usuário marcou e devolve um "
                    "resumo FACTUAL do que ele está apontando: ativo e timeframe se visíveis, "
                    "linhas e níveis desenhados (com preços quando legíveis), padrões marcados, "
                    "anotações escritas. Máximo ~400 caracteres, texto corrido, no idioma: "
                    + idioma_nome + ". Sem opinião, sem previsão, sem promessa — só o que está "
                    "marcado na imagem."
                ),
                "messages": [{"role": "user", "content": [
                    {"type": "image", "source": {"type": "base64",
                     "media_type": img_tipo or "image/png", "data": img_b64}},
                    {"type": "text", "text": "Resuma o que o operador marcou neste gráfico."},
                ]}],
            },
            timeout=25.0,
        )
        if r.status_code != 200:
            print(f"VISAO print status {r.status_code}: {r.text[:200]}", file=sys.stderr)
            return None
        txt = "".join(b.get("text", "") for b in r.json().get("content", [])).strip()
        return txt[:500] or None
    except Exception as e:
        print(f"VISAO print erro: {e}", file=sys.stderr)
        return None


# ════════════════════════════════════════════════════════════════════════════
#  v6.76 — BABYMACHINE: OPERAÇÕES REAIS (Sessão 6A — coleta)
#
#  Estende a BabyMachine (que hoje coleta backtests em backtests_historico)
#  pra registrar operações REAIS ao vivo do MT5 na tabela nova
#  babymachine_operacoes. Alimentada por 3 fontes:
#    (1) detector automático — cria linha 'pendente' quando decide entrar
#    (2) EA da estratégia compilada — cria linha 'aberta' via /conector/evento
#    (3) fechamento (qualquer fonte) — /conector/evento tipo=fechado
#
#  Non-blocking em TUDO: falha na coleta nunca quebra detector, comando ou
#  evento. Logs sempre.
# ════════════════════════════════════════════════════════════════════════════

_BM_LIMPAR_THROTTLE = {"ultimo": 0.0}


def _bm_limpar_throttled(sb):
    """Chama _bm_operacoes_limpar_antigas() no máximo 1x por 6h."""
    import time
    agora = time.time()
    if agora - _BM_LIMPAR_THROTTLE["ultimo"] < 21600:  # 6h
        return
    _BM_LIMPAR_THROTTLE["ultimo"] = agora
    try:
        sb.rpc("_bm_operacoes_limpar_antigas").execute()
    except Exception as _e:
        try: print(f"[bm limpar] {_e}")
        except Exception: pass


def _bm_projecao_medida(entrada, stop, alvo, direcao=None):
    """v6.96 — FASE 1 da BabyMachine completa (pedido do dono: gravar na ENTRADA
    o que foi PROJETADO, pra o post-mortem comparar 'projetei X, andou Y').
    A partir de entrada/stop/alvo já capturados, calcula em PONTOS:
      - risco_pts  = |entrada - stop|      (quanto se perde se bater o stop)
      - ganho_pts  = |alvo - entrada|      (quanto foi analisado que ia andar)
      - rr         = ganho_pts / risco_pts (o R:R planejado ANTES de entrar)
    Determinístico, custo zero. Retorna dict só com o que dá pra calcular —
    campos faltando ficam de fora (nunca inventa número)."""
    out = {}
    def _n(v):
        try:
            f = float(v)
            return f if f != 0 else None
        except Exception:
            return None
    e, s, a = _n(entrada), _n(stop), _n(alvo)
    if e is not None and s is not None:
        out["risco_pts"] = round(abs(e - s), 2)
    if e is not None and a is not None:
        out["ganho_pts"] = round(abs(a - e), 2)
    if out.get("risco_pts") and out.get("ganho_pts"):
        try:
            out["rr"] = round(out["ganho_pts"] / out["risco_pts"], 2)
        except Exception:
            pass
    return out


def _bm_extrair_contexto(bot, leitura, veredito):
    """Captura o contexto do momento da entrada. Sempre parcial — pega o que
    tiver disponível. Serve como 'foto' do cenário pra a BabyMachine aprender."""
    ctx = {}
    if leitura and isinstance(leitura, dict):
        reg = leitura.get("regime") or {}
        ctx["regime"] = str(reg.get("estado") or reg.get("regime") or "").upper()
        ctx["preco"] = leitura.get("preco")
        ctx["tfop"] = leitura.get("tf_op")
        # padrões formais + estrutura do offmind
        ctx["padroes_formais"] = leitura.get("padroes") or []
        # confirmação histórica (banco existente)
        conf = leitura.get("confirmacao") or {}
        if isinstance(conf, dict):
            ctx["confirmacao_score"] = conf.get("score")
            ctx["confirmacao_veredito"] = conf.get("veredito")
        # momentum semântico por TF
        ctx["momentum_tfs"] = leitura.get("momentum_tfs") or {}
    if veredito and isinstance(veredito, dict):
        ctx["veredito_ia"] = {
            "sinal": veredito.get("sinal"),
            "veredito": veredito.get("veredito"),
        }
    # v6.90 — O PORQUÊ DA ENTRADA: scanner + narração do BOT + sinais legíveis
    if leitura and isinstance(leitura, dict):
        try:
            sc = leitura.get("scanner") or {}
            if sc:
                ctx["scanner"] = {
                    "alinhamento": (sc.get("alinhamento") or {}).get("resumo"),
                    "cascata": (sc.get("cascata_reversao") or {}).get("resumo") or sc.get("cascata_reversao"),
                }
                # v7.34 — cada operacao nasce sabendo EM QUE FASE entrou: e a
                # chave que deixa a Learning Machine responder "entradas em
                # RETOMADA pagam X por cento; em RESPIRO contra, Y" por celula
                _fz = sc.get("fase") or {}
                if _fz:
                    ctx["fase"] = {"fase": _fz.get("fase"), "transicao": _fz.get("transicao"),
                                   "detalhe": _fz.get("detalhe")}
        except Exception:
            pass
        try:
            nb = leitura.get("narracao_bot")
            if nb:
                ctx["leitura_bot"] = str(nb)[:450]
        except Exception:
            pass
    ctx["sinais"] = _bm_sinais_legiveis(ctx, leitura)
    return ctx


def _bm_sinais_legiveis(ctx, leitura):
    """v6.90 — traduz o contexto do momento em FRASES prontas (o material de
    trabalho que o dono pediu: por que essa entrada, quais sinais no gráfico).
    Determinístico, custo zero. Até 8 sinais."""
    sinais = []
    try:
        if ctx.get("regime"):
            sinais.append(f"Regime {ctx['regime']}")
        for p in (ctx.get("padroes_formais") or [])[:3]:
            try:
                nome = p.get("nome") or p.get("padrao") or "?"
                tf = p.get("tf") or "?"
                d = str(p.get("direcao") or "").lower()
                sinais.append(f"{nome} no {tf}" + (f" ({d})" if d else ""))
            except Exception:
                pass
        scn = ctx.get("scanner") or {}
        if scn.get("alinhamento"):
            sinais.append(str(scn["alinhamento"]))
        casc = scn.get("cascata")
        if casc:
            sinais.append("Reversão em cascata: " + str(casc)[:90])
        if ctx.get("confirmacao_score") is not None:
            sinais.append(f"Confirmação histórica {ctx['confirmacao_score']}/100")
        if leitura and isinstance(leitura, dict):
            try:
                ex = leitura.get("extras") or {}
                rg = ex.get("range") or {}
                if rg.get("fundo") is not None and rg.get("topo") is not None:
                    est = str(rg.get("estado") or "")
                    marca = " (rompeu ▲)" if "cima" in est else (" (rompeu ▼)" if "baixa" in est or "baixo" in est else "")
                    sinais.append(f"Range {rg['fundo']}–{rg['topo']}{marca}")
            except Exception:
                pass
            try:
                for e in (leitura.get("estrutura") or [])[:2]:
                    if e.get("preco") is not None:
                        sinais.append(f"Nível {e['preco']} sendo testado ({e.get('toques', '?')} toques, {e.get('tf', '?')})")
            except Exception:
                pass
    except Exception:
        pass
    return sinais[:8]


def _bm_registrar_do_detector(sb, bot, oportunidade, leitura, veredito, comando_id, fonte):
    """Chamada quando o detector cria um comando via /mt5/comando.
    fonte: 'detector_auto' | 'detector_copiloto'.
    Cria linha status='pendente'. Vira 'aberta' quando o EA confirma
    execução (via _bm_marcar_aberta_por_comando)."""
    if not sb or not bot or not oportunidade: return
    try:
        contexto = _bm_extrair_contexto(bot, leitura, veredito)
        decisao = {
            "direcao":       oportunidade.get("direcao"),
            "cenario":       oportunidade.get("cenario"),
            "entrada":       oportunidade.get("entrada"),
            "stop":          oportunidade.get("stop"),
            "alvo1":         oportunidade.get("alvo1"),
            "alvo2":         oportunidade.get("alvo2"),
            "score":         oportunidade.get("score"),
            "estrelas":      oportunidade.get("estrelas"),
            "confluencias":  oportunidade.get("confluencias"),
            "explicacao":    oportunidade.get("explicacao"),
        }
        # v6.96 — PROJEÇÃO MEDIDA na entrada (o planejado, pro post-mortem):
        # risco/ganho em pts + R:R calculados de entrada/stop/alvo1.
        try:
            _proj = _bm_projecao_medida(oportunidade.get("entrada"),
                                        oportunidade.get("stop"),
                                        oportunidade.get("alvo1"),
                                        oportunidade.get("direcao"))
            if _proj:
                decisao["projecao"] = _proj
        except Exception:
            pass
        linha = {
            "user_id":          bot.get("user_id"),
            "bot_id":           bot.get("id"),
            "bot_nome":         bot.get("nome") or "",
            "ativo":            bot.get("simbolo") or "",
            "timeframe":        bot.get("timeframe") or "",
            "fonte":            fonte,
            "status":           "pendente",
            "oportunidade_id":  oportunidade.get("id"),
            "comando_id":       comando_id,
            "contexto_entrada": contexto,
            "decisao":          decisao,
        }
        sb.table("babymachine_operacoes").insert(linha).execute()
        _bm_limpar_throttled(sb)
    except Exception as _e:
        try: print(f"[bm registrar detector] {_e}")
        except Exception: pass


def _bm_marcar_aberta_por_comando(sb, comando_id, resultado_conf):
    """Chamada em /mt5/comando/confirmar. Se havia linha pendente pro
    comando, atualiza pra status='aberta' com ticket_mt5 e ts_entrada."""
    if not sb or not comando_id: return
    try:
        ticket = None
        preco_real = None
        if isinstance(resultado_conf, dict):
            ticket = resultado_conf.get("ticket") or resultado_conf.get("order")
            preco_real = resultado_conf.get("preco_real") or resultado_conf.get("price")
        upd = {
            "status":     "aberta",
            "ts_entrada": _dt.now(_tz.utc).isoformat(),
        }
        if ticket:      upd["ticket_mt5"] = int(ticket)
        # anexa preço real na decisão sem sobrescrever
        try:
            atual = (sb.table("babymachine_operacoes").select("decisao")
                     .eq("comando_id", comando_id).limit(1).execute().data or [])
            if atual:
                dec = dict(atual[0].get("decisao") or {})
                if preco_real:
                    dec["preco_real_entrada"] = preco_real
                upd["decisao"] = dec
        except Exception:
            pass
        sb.table("babymachine_operacoes").update(upd).eq("comando_id", comando_id).execute()
    except Exception as _e:
        try: print(f"[bm marcar aberta] {_e}")
        except Exception: pass


_BM_RECON_TS = {}
_BM_RECON_ZEROS = {}    # v6.91 — bot_id -> leituras consecutivas com 0 posições
_BM_ULT_ABERTURA = {}   # v6.90 — bot_id -> (direcao, ts) trava anti-corrida do dedup


def _bm_eh_orfa_reconciliada(res):
    """Órfã criada pela reconciliação (não pelo fluxo normal de fechamento)."""
    try:
        if not isinstance(res, dict):
            return False
        if res.get("reconciliada") is True:
            return True
        return "pré-eventos-confirmados" in str(res.get("motivo") or "")
    except Exception:
        return False


def _bm_reverter_orfas(sb, bot_id):
    """v6.91 — AUTO-RECUPERAÇÃO: o MT5 mostra posição aberta mas o bot não tem
    'aberta' na BabyMachine e tem órfã de RECONCILIAÇÃO recente (<2h) — a
    reconciliação cortou registro válido (snapshot mentiu posições=0). Reverte
    a órfã mais recente pra 'aberta'. Caso real: as 4 entradas das 18:38."""
    try:
        tem_aberta = (sb.table("babymachine_operacoes")
                      .select("id").eq("bot_id", bot_id).eq("status", "aberta")
                      .limit(1).execute().data or [])
        if tem_aberta:
            return
        corte = (_dt.now(_tz.utc) - timedelta(hours=2)).isoformat()
        orfas = (sb.table("babymachine_operacoes")
                 .select("id,resultado,ts_saida").eq("bot_id", bot_id)
                 .eq("status", "orfa").gte("ts_saida", corte)
                 .order("ts_saida", desc=True).limit(10).execute().data or [])
        alvo = next((o for o in orfas if _bm_eh_orfa_reconciliada(o.get("resultado"))), None)
        if not alvo:
            return
        sb.table("babymachine_operacoes").update({
            "status": "aberta", "ts_saida": None, "resultado": None,
        }).eq("id", alvo["id"]).execute()
        print(f"[bm-reverter] bot {bot_id}: órfã {alvo['id']} restaurada pra 'aberta' (posição existe no MT5)")
    except Exception as _e:
        try: print(f"[bm-reverter] {_e}")
        except Exception: pass


def _bm_reconciliar_abertas(sb, bot_id, posicoes_abertas, flutuante=None):
    """v6.91 — RECONCILIAÇÃO DEFENSIVA: o snapshot pode reportar posições=0
    MESMO com posição aberta (parser do conector; o template BTvPosSimb conta
    certo). Uma leitura mentirosa não pode apagar histórico: só marca órfã com
    3 LEITURAS CONSECUTIVAS zeradas + idade >10min + flutuante zerado/nulo.
    Se posições>0, tenta REVERTER órfãs cortadas por engano. Throttle 120s/bot."""
    try:
        if bot_id is None or posicoes_abertas is None:
            return
        if int(posicoes_abertas) != 0:
            _BM_RECON_ZEROS[bot_id] = 0
            _bm_reverter_orfas(sb, bot_id)
            return
        # flutuante diferente de zero = HÁ posição, o campo posições mentiu
        try:
            if flutuante is not None and abs(float(flutuante)) > 0.0001:
                _BM_RECON_ZEROS[bot_id] = 0
                return
        except Exception:
            pass
        _BM_RECON_ZEROS[bot_id] = _BM_RECON_ZEROS.get(bot_id, 0) + 1
        if _BM_RECON_ZEROS[bot_id] < 3:
            return
        agora = _time_anl.time()
        if agora - _BM_RECON_TS.get(bot_id, 0) < 120:
            return
        _BM_RECON_TS[bot_id] = agora
        corte = (_dt.now(_tz.utc) - timedelta(minutes=10)).isoformat()
        abertas = (sb.table("babymachine_operacoes")
                   .select("id").eq("bot_id", bot_id).eq("status", "aberta")
                   .lt("ts_entrada", corte).limit(50).execute().data or [])
        if not abertas:
            return
        ids = [a["id"] for a in abertas]
        sb.table("babymachine_operacoes").update({
            "status": "orfa",
            "ts_saida": _dt.now(_tz.utc).isoformat(),
            "resultado": {"reconciliada": True,
                          "motivo": "aberta sem posição correspondente no MT5 "
                                    "(provável ordem rejeitada — era pré-eventos-confirmados)"},
        }).in_("id", ids).execute()
        print(f"[bm-reconciliar] bot {bot_id}: {len(ids)} aberta(s) fantasma(s) viraram órfãs (3 leituras zeradas)")
    except Exception as _e:
        try: print(f"[bm-reconciliar] {_e}")
        except Exception: pass


def _bm_registrar_estrategia_compilada(sb, bot, det, evento_id):
    """Chamada em /conector/evento tipo=aberto quando NÃO há operação
    pendente pra casar (EA da estratégia compilada abriu por conta).
    Cria linha status='aberta' com fonte='estrategia_compilada'."""
    if not sb or not bot: return
    try:
        # tenta puxar leitura recente pra ter contexto
        leitura = None
        try:
            leitura = _anl_ler_leitura(sb, bot.get("user_id"), bot.get("id"))
        except Exception:
            pass
        contexto = _bm_extrair_contexto(bot, leitura, None)
        lado = str((det or {}).get("lado") or "").upper()
        direcao = "long" if lado == "BUY" else ("short" if lado == "SELL" else "desconhecida")
        # v6.98 — símbolo VIVO do gráfico (o evento carimba simbolo=_Symbol);
        # o de conector_bots é a intenção do envio e pode divergir do MT5 real.
        _dl_ab = {str(k).lower(): v for k, v in (det or {}).items()}
        _simb_vivo = str(_dl_ab.get("simbolo") or _dl_ab.get("symbol") or "").strip().upper()
        # v6.90 — DEDUP v2 ANTI-CORRIDA: trava em memória (por worker) pega as
        # duplicatas do MESMO segundo que a janela via banco perdia (o insert da
        # 1ª ainda não tinha commitado quando a 2ª consultava).
        # v7.46 — DEDUP POR TICKET: a reentrada REAL de 20s do BTC (stop-out +
        # reentrada no mesmo sinal, 10/ago 21:36) foi engolida pelo dedup por
        # direcao+janela. Ticket diferente = operacao NOVA, nunca duplicata.
        _tk46 = str(_dl_ab.get("ticket") or "").strip()
        try:
            _ag = _time_anl.time()
            _ult = _BM_ULT_ABERTURA.get(bot.get("id"))
            if _ult and _ult[0] == direcao and (_ag - _ult[1]) < 30:
                _tk_ant = _ult[2] if len(_ult) > 2 else ""
                if _tk46 and _tk_ant and _tk46 != _tk_ant:
                    pass  # tickets distintos = reentrada legitima, registra
                else:
                    print(f"[bm dedup-mem] abertura duplicada ignorada (bot {bot.get('id')} {direcao})")
                    return
            _BM_ULT_ABERTURA[bot.get("id")] = (direcao, _ag, _tk46)
        except Exception:
            pass
        # v6.89 — DEDUP: mesma direção aberta há <30s no mesmo bot = duplicata
        # (EA/conector emitindo em dobro). Ignora antes de inserir.
        try:
            corte = (_dt.now(_tz.utc) - timedelta(seconds=30)).isoformat()
            rec = (sb.table("babymachine_operacoes")
                   .select("id,decisao").eq("bot_id", bot.get("id"))
                   .eq("status", "aberta").gte("ts_entrada", corte)
                   .limit(3).execute().data or [])
            for r0 in rec:
                _d0 = (r0.get("decisao") or {})
                if str(_d0.get("direcao") or "") == direcao:
                    # v7.46 — ticket diferente = reentrada real, NAO e duplicata
                    _tk0 = str(_d0.get("ticket") or "").strip()
                    if _tk46 and _tk0 and _tk46 != _tk0:
                        continue
                    print(f"[bm dedup] abertura duplicada ignorada (bot {bot.get('id')} {direcao} <30s)")
                    return
        except Exception:
            pass
        decisao = {
            "direcao":  direcao,
            "cenario":  "estrategia_compilada",
            "detalhe_ea": det or {},
        }
        if _simb_vivo:
            decisao["simbolo_vivo"] = _simb_vivo
        # v6.90 — LINHAGEM: qual estratégia gerou este bot (config_operacional)
        try:
            _en = (bot.get("config_operacional") or {}).get("estrategia_nome")
            if _en:
                decisao["estrategia"] = _en
        except Exception:
            pass
        # v6.89 — EA v2 (BT_EVT_V2) manda preço real de execução + sl/tp/ticket/lote
        for _k_ev, _k_dec in (("preco", "entrada"), ("price", "entrada"),
                              ("sl", "stop"), ("tp", "alvo"),
                              ("ticket", "ticket"), ("lote", "lote")):
            _v = (det or {}).get(_k_ev)
            if _v is not None and _k_dec not in decisao:
                try:
                    decisao[_k_dec] = float(_v) if _k_dec != "ticket" else _v
                except Exception:
                    pass
        # v6.96 — PROJEÇÃO MEDIDA na entrada (pedido do dono). Duas fontes, em
        # ordem: (a) o CAÇADOR já calculou alvo/risco/rr quando localizou o
        # gatilho (leitura.scanner.gatilho) — a projeção ANALISADA antes de
        # entrar; (b) fallback: calcula de entrada/stop/alvo reais da ordem.
        try:
            _proj = {}
            _gat = ((leitura or {}).get("scanner") or {}).get("gatilho") or {}
            if isinstance(_gat, dict):
                for _kg, _kp in (("alvo_pts", "ganho_pts"), ("ganho_pts", "ganho_pts"),
                                 ("risco_pts", "risco_pts"), ("rr", "rr"),
                                 ("r_r", "rr"), ("estrelas", "estrelas"),
                                 ("confluencia", "confluencia")):
                    _vg = _gat.get(_kg)
                    if _vg is not None and _kp not in _proj:
                        _proj[_kp] = _vg
                if _gat.get("alvo") and "alvo" not in decisao:
                    decisao["alvo_projetado"] = _gat.get("alvo")
            # fallback / complemento: calcula dos valores reais da ordem
            _calc = _bm_projecao_medida(decisao.get("entrada"),
                                        decisao.get("stop"),
                                        decisao.get("alvo") or (_gat.get("alvo") if isinstance(_gat, dict) else None),
                                        direcao)
            for _k, _v in (_calc or {}).items():
                _proj.setdefault(_k, _v)
            # confirmação histórica do banco (o "medido" do momento)
            _cf = decisao.get("confluencia")
            if _cf is None:
                _cf = (contexto or {}).get("confirmacao_score")
                if _cf is not None:
                    _proj.setdefault("confirmacao_score", _cf)
            if _proj:
                decisao["projecao"] = _proj
        except Exception:
            pass
        linha = {
            "user_id":          bot.get("user_id"),
            "bot_id":           bot.get("id"),
            "bot_nome":         bot.get("nome") or "",
            "ativo":            (_simb_vivo or bot.get("simbolo") or ""),
            "timeframe":        bot.get("timeframe") or "",
            "fonte":            "estrategia_compilada",
            "status":           "aberta",
            "evento_id_abriu":  evento_id,
            "contexto_entrada": contexto,
            "decisao":          decisao,
            "ts_entrada":       _dt.now(_tz.utc).isoformat(),
        }
        sb.table("babymachine_operacoes").insert(linha).execute()
        _bm_limpar_throttled(sb)
    except Exception as _e:
        try: print(f"[bm registrar EA] {_e}")
        except Exception: pass


def _bm_processar_abertura(sb, bot, det, evento_id):
    """Roteador de /conector/evento tipo=aberto:
      - Se há linha pendente do detector pra este bot, marca como aberta
      - Senão, cria linha nova com fonte='estrategia_compilada'
    FIFO por bot pra casamento (o mais antigo pendente ganha)."""
    if not sb or not bot: return
    try:
        pendentes = (sb.table("babymachine_operacoes")
                     .select("id, comando_id")
                     .eq("bot_id", bot.get("id"))
                     .eq("status", "pendente")
                     .order("ts_criada")
                     .limit(1)
                     .execute().data or [])
        if pendentes:
            # casou — atualiza pra aberta
            upd = {
                "status":          "aberta",
                "ts_entrada":      _dt.now(_tz.utc).isoformat(),
                "evento_id_abriu": evento_id,
            }
            sb.table("babymachine_operacoes").update(upd).eq("id", pendentes[0]["id"]).execute()
        else:
            # estratégia compilada abriu sozinha
            _bm_registrar_estrategia_compilada(sb, bot, det, evento_id)
    except Exception as _e:
        try: print(f"[bm abertura] {_e}")
        except Exception: pass


def _bm_processar_fechamento(sb, bot, det, evento_id):
    """/conector/evento tipo=fechado. Fecha a operação ABERTA mais antiga
    desse bot (FIFO). Calcula pnl se der (detalhe geralmente traz preço)."""
    if not sb or not bot: return
    try:
        # v6.98 — CASAMENTO v2 (medição íntegra): o FIFO cego cruzava
        # instrumentos. Ordem nova: TICKET do evento -> SÍMBOLO do evento
        # (o EA carimba simbolo=_Symbol) -> FIFO puro só p/ evento antigo
        # sem símbolo. Aberta de outro símbolo NUNCA fecha por engano.
        _dl0 = {str(k).lower(): v for k, v in (det or {}).items()}
        _ev_simb = str(_dl0.get("simbolo") or _dl0.get("symbol") or "").strip().upper()
        _ev_tick = str(_dl0.get("ticket") or "").strip()
        _cands = (sb.table("babymachine_operacoes")
                  .select("id, decisao, ts_entrada, ativo")
                  .eq("bot_id", bot.get("id"))
                  .eq("status", "aberta")
                  .order("ts_entrada")
                  .limit(10)
                  .execute().data or [])
        def _op_simb(o):
            _d0 = o.get("decisao") or {}
            return str(_d0.get("simbolo_vivo") or o.get("ativo") or "").strip().upper()
        abertas = []
        if _ev_tick:
            abertas = [o for o in _cands
                       if str(((o.get("decisao") or {}).get("ticket")) or "").strip() == _ev_tick]
        if not abertas and _ev_simb:
            abertas = [o for o in _cands if _op_simb(o) in ("", _ev_simb)]
        if not abertas and not _ev_simb:
            abertas = _cands
        abertas = abertas[:1]
        if not abertas:
            # v6.91 — AUTO-RECUPERAÇÃO na saída: antes de criar órfã nova,
            # procura órfã de RECONCILIAÇÃO recente (<2h) — se a reconciliação
            # cortou o registro por engano, o fechamento real devolve ele pro
            # histórico COM medição (preço/pnl), em vez de duplicar lixo.
            try:
                corte_r = (_dt.now(_tz.utc) - timedelta(hours=2)).isoformat()
                orfas_r = (sb.table("babymachine_operacoes")
                           .select("id,decisao,ts_entrada,resultado,ativo").eq("bot_id", bot.get("id"))
                           .eq("status", "orfa").gte("ts_saida", corte_r)
                           .order("ts_saida", desc=True).limit(10).execute().data or [])
                alvo_r = next((o for o in orfas_r
                               if _bm_eh_orfa_reconciliada(o.get("resultado"))
                               and (not _ev_simb or _op_simb(o) in ("", _ev_simb))), None)
                if alvo_r:
                    abertas = [alvo_r]
                    print(f"[bm-recuperar] bot {bot.get('id')}: fechamento recuperou órfã {alvo_r['id']} pro histórico")
            except Exception:
                pass
        if not abertas:
            # órfã — fechou sem entrada registrada (perdemos o hook)
            try:
                sb.table("babymachine_operacoes").insert({
                    "user_id":         bot.get("user_id"),
                    "bot_id":          bot.get("id"),
                    "bot_nome":        bot.get("nome") or "",
                    "ativo":           (_ev_simb or bot.get("simbolo") or ""),
                    "fonte":           "estrategia_compilada",
                    "status":          "orfa",
                    "evento_id_fechou": evento_id,
                    "resultado":       {"detalhe_ea": det or {}, "motivo": "fechou sem abertura registrada"},
                    "ts_saida":        _dt.now(_tz.utc).isoformat(),
                }).execute()
            except Exception:
                pass
            return
        op = abertas[0]
        ts_saida = _dt.now(_tz.utc)
        # calcula tempo ativo se possível
        tempo_seg = None
        try:
            ts_ent = _dt.fromisoformat(str(op.get("ts_entrada") or "").replace("Z", "+00:00"))
            tempo_seg = int((ts_saida - ts_ent).total_seconds())
        except Exception:
            pass
        # tenta extrair preço/pnl do detalhe (o EA pode ou não mandar)
        preco_saida = None
        pnl_pts = None
        pnl_pct = None
        try:
            det_low = {str(k).lower(): v for k, v in (det or {}).items()}
            for chave in ("preco_saida", "preco", "price", "close_price"):
                if chave in det_low and det_low[chave] is not None:
                    preco_saida = float(det_low[chave])
                    break
            for chave in ("pnl", "profit", "lucro"):
                if chave in det_low and det_low[chave] is not None:
                    pnl_pts = float(det_low[chave])
                    break
            # se tem entrada + saída, calcula pnl_pts se ainda não veio
            if preco_saida is not None:
                dec = op.get("decisao") or {}
                entrada = dec.get("preco_real_entrada") or dec.get("entrada")
                if entrada is not None:
                    dir_op = str(dec.get("direcao") or "").lower()
                    delta = (preco_saida - float(entrada)) if dir_op == "long" else (float(entrada) - preco_saida)
                    if pnl_pts is None:
                        pnl_pts = round(delta, 4)
                    if float(entrada) != 0:
                        pnl_pct = round(delta / float(entrada) * 100, 4)
        except Exception:
            pass
        resultado = {
            "preco_saida":     preco_saida,
            "pnl_pts":         pnl_pts,
            "pnl_pct":         pnl_pct,
            "tempo_ativo_seg": tempo_seg,
            "detalhe_ea":      det or {},
        }
        upd = {
            "status":           "fechada",
            "ts_saida":         ts_saida.isoformat(),
            "evento_id_fechou": evento_id,
            "resultado":        resultado,
        }
        sb.table("babymachine_operacoes").update(upd).eq("id", op["id"]).execute()
    except Exception as _e:
        try: print(f"[bm fechamento] {_e}")
        except Exception: pass


# ════════════════════════════════════════════════════════════════════════════
#  v6.74 — DETECTOR AUTOMATICO DE OPORTUNIDADE (Sessao 3 do loop fechado)
#
#  Roda 24/7 no /conector/snapshot (a cada 15s enquanto o EA emite). Analisa
#  o cenario do bot combinando os fatos que ja produzimos:
#    - offmind (padroes formais + niveis S/R com toques)
#    - regime sintetizado das zonas
#    - momentum semantico por TF
#    - confirmacao estatistica (banco historico)
#    - veredito da analise cruzada (BOT + IA)
#
#  Determina direcao, calcula entrada/stop/alvos com niveis reais do offmind,
#  soma confluencias (0-100), traduz em ESTRELAS (1-5). Cada modo do usuario
#  tem um LIMIAR de estrelas pra disparar:
#    - observar: NUNCA dispara (so registra passivo)
#    - copiloto: dispara oportunidade pra UI mostrar; usuario clica pra executar
#    - automatico: dispara + cria comando via /mt5/comando direto
#
#  Estado em memoria por bot (config, historico, circuit state). Tabela vem
#  na Sessao 6 quando construirmos dashboard historico — por enquanto se
#  Railway reinicia, tudo volta pra "observar" (fail-safe).
# ════════════════════════════════════════════════════════════════════════════

_BOT_CONFIG = {}          # bot_id (int) -> config dict
_OPORTUNIDADES_HIST = {}  # bot_id -> deque de oportunidades (mais recente por ultimo)
_CIRCUIT_STATE = {}       # bot_id -> {equity_inicio_dia, ops_hoje, data_ref}


def _dd_dia_pct(bot_id, equity):
    """v6.88 — drawdown DO DIA: equity atual vs equity de início do dia
    registrado pelo circuit breaker do detector (_CIRCUIT_STATE, memória por
    worker). None quando o estado ainda não existe — o front mostra traço
    honesto em vez de número inventado."""
    try:
        st = _CIRCUIT_STATE.get(bot_id) or {}
        ini = float(st.get("equity_inicio_dia") or 0)
        eq = float(equity or 0)
        if ini > 0 and eq > 0:
            return round(max(0.0, (ini - eq) / ini * 100), 2)
    except Exception:
        pass
    return None
_OPORT_MAX_HIST = 30
_OPORT_COOLDOWN_SEG = 60  # nao dispara nova oportunidade do mesmo bot em <60s

_DETECTOR_DEFAULT_CONFIG = {
    "modo_operacional":   "observar",    # observar | copiloto | automatico
    "modo_sensibilidade": "conservador", # conservador | moderado | agressivo
    "drawdown_max_dia":   5.0,           # % maximo de perda no dia
    "max_operacoes_dia":  10,            # circuit breaker
    "estrelas_min_auto":  4,             # so executa auto se >= X estrelas
    "pausado":            False,         # kill switch manual
    "lote_padrao":        0.01,          # lote default das ordens auto
}

_ESTRELAS_LIMIAR_POR_MODO = {
    "conservador": 4,
    "moderado":    3,
    "agressivo":   2,
}


def _bot_config_get(bot_id):
    """Retorna config do bot ou defaults conservadores. Nunca retorna None."""
    if bot_id not in _BOT_CONFIG:
        _BOT_CONFIG[bot_id] = dict(_DETECTOR_DEFAULT_CONFIG)
    return _BOT_CONFIG[bot_id]


def _bot_config_set(bot_id, novo):
    """Atualiza campos validos da config do bot. Ignora chaves nao permitidas."""
    cfg = _bot_config_get(bot_id)
    for k in _DETECTOR_DEFAULT_CONFIG.keys():
        if k in novo:
            cfg[k] = novo[k]
    return cfg


def _oportunidade_hist(bot_id):
    if bot_id not in _OPORTUNIDADES_HIST:
        from collections import deque
        _OPORTUNIDADES_HIST[bot_id] = deque(maxlen=_OPORT_MAX_HIST)
    return _OPORTUNIDADES_HIST[bot_id]


def _oport_push(bot_id, oportunidade):
    o = dict(oportunidade)
    o["ts"] = _dt.now(_tz.utc).isoformat()
    o["id"] = f"{bot_id}-{int(_time_anl.time() * 1000)}"
    _oportunidade_hist(bot_id).append(o)
    return o


# ──────────────────────────────────────────────────────────────────────────
#  DETECTORES DETERMINISTICOS (sem IA, custo zero)
# ──────────────────────────────────────────────────────────────────────────

def _detectar_direcao_potencial(fatos, leitura):
    """Analisa o cenario e determina se ha direcao potencial (long/short).
    Prioriza: (1) pullback em tendencia; (2) padrao de reversao em nivel;
    (3) rompimento. Retorna None se nao ha setup claro."""
    if not fatos: return None
    regime_str = str(fatos.get("regime") or "").upper()
    testando = fatos.get("niveis_sendo_testados") or []
    padroes = fatos.get("padroes_formais") or []
    # Caso 0 (v6.79): ROMPIMENTO DE RANGE/LATERALIZACAO — o gatilho mais
    # classico. Acumulacao rompe pra qualquer lado; entrada no rompimento,
    # stop de volta pro nivel rompido, alvo = projecao da altura (measured move).
    rng = fatos.get("range_lateral") or {}
    if rng.get("estado") == "rompeu_cima" and rng.get("topo"):
        return {"direcao": "long", "cenario": "rompimento_range_alta",
                "gatilho_ref": {"tipo": "resistencia", "nivel": rng.get("topo"),
                                "toques": rng.get("toques_topo")},
                "range": rng}
    if rng.get("estado") == "rompeu_baixo" and rng.get("fundo"):
        return {"direcao": "short", "cenario": "rompimento_range_baixa",
                "gatilho_ref": {"tipo": "suporte", "nivel": rng.get("fundo"),
                                "toques": rng.get("toques_fundo")},
                "range": rng}
    # Caso 0c (v7.18): CANAL EMA 20 H/L + BOLLINGER — metodologia do dono.
    # Entra ANTES do range/estrutura porque e a estrategia da casa e ela ja
    # traz entrada e stop calculados pela propria geometria (exaustao ->
    # confirmacao -> rompimento do extremo da barra B). Sem alvo de proposito:
    # a saida e a volta pro canal, nao um numero.
    ce = fatos.get("canal_ema_setup") or {}
    if ce.get("gatilho") == "G1" and ce.get("direcao") and not ce.get("veto"):
        return {"direcao": ce["direcao"],
                "cenario": ("canal_ema_reversao_alta" if ce["direcao"] == "long"
                            else "canal_ema_reversao_baixa"),
                "gatilho_ref": {"tipo": "exaustao_bollinger",
                                "nivel": ce.get("entrada_em"),
                                "stop": ce.get("stop"),
                                "volume_ok": ce.get("volume_ok"),
                                "armado": ce.get("armado")},
                "canal_ema": ce}
    # Caso 0b (v6.80): REVERSAO POR ESTRUTURA (pivo 1-2-3) — 2o extremo mais
    # fraco + neckline rompida. Entrada no rompimento, stop de volta pra
    # dentro, alvo = projecao da altura da estrutura.
    sw = fatos.get("estrutura_swing") or {}
    if sw.get("estado") == "rompeu" and sw.get("neckline"):
        if sw.get("direcao") == "baixa":
            return {"direcao": "short", "cenario": "reversao_estrutura_baixa",
                    "gatilho_ref": {"tipo": "suporte", "nivel": sw.get("neckline")},
                    "swing": sw}
        if sw.get("direcao") == "alta":
            return {"direcao": "long", "cenario": "reversao_estrutura_alta",
                    "gatilho_ref": {"tipo": "resistencia", "nivel": sw.get("neckline")},
                    "swing": sw}
    # Caso 1: pullback em tendencia
    if "ALTA" in regime_str and testando:
        for nv in testando:
            if nv.get("tipo") == "suporte" and (nv.get("toques") or 0) >= 2:
                return {
                    "direcao": "long",
                    "cenario": "pullback_em_tendencia_alta",
                    "gatilho_ref": nv,
                }
    if "BAIXA" in regime_str and testando:
        for nv in testando:
            if nv.get("tipo") == "resistencia" and (nv.get("toques") or 0) >= 2:
                return {
                    "direcao": "short",
                    "cenario": "pullback_em_tendencia_baixa",
                    "gatilho_ref": nv,
                }
    # Caso 2: padrao de reversao em nivel
    if padroes and testando:
        for pad in padroes:
            direc = str(pad.get("direcao") or "").lower()
            if "alta" in direc:
                for nv in testando:
                    if nv.get("tipo") == "suporte":
                        return {
                            "direcao": "long",
                            "cenario": "padrao_reversao_em_suporte",
                            "gatilho_ref": nv,
                            "padrao_confirmando": pad,
                        }
            if "baixa" in direc:
                for nv in testando:
                    if nv.get("tipo") == "resistencia":
                        return {
                            "direcao": "short",
                            "cenario": "padrao_reversao_em_resistencia",
                            "gatilho_ref": nv,
                            "padrao_confirmando": pad,
                        }
    return None


def _calcular_niveis_operacao(direcao_info, fatos):
    """A partir da direcao potencial, calcula entrada/stop/alvos usando
    niveis REAIS do offmind. R:R minimo 1:1 (senao retorna None)."""
    preco = fatos.get("preco")
    if preco is None: return None
    try:
        preco = float(preco)
    except Exception:
        return None
    direcao = direcao_info["direcao"]
    gatilho_ref = direcao_info.get("gatilho_ref") or {}
    proximos = fatos.get("niveis_proximos") or []
    if direcao == "long":
        entrada = preco
        # stop: abaixo do suporte de referencia com pequena margem (0.1%)
        nivel_ref = gatilho_ref.get("nivel")
        if nivel_ref:
            stop = float(nivel_ref) * 0.999
        else:
            ema_l = fatos.get("distancia_ema_l")
            stop = preco - (preco * 0.005)
        # alvos
        resistencias = [n for n in proximos
                        if n.get("tipo") == "resistencia" and n.get("nivel", 0) > preco]
        resistencias.sort(key=lambda n: n.get("nivel"))
        risco = entrada - stop
        if risco <= 0: return None
        if resistencias:
            alvo1 = float(resistencias[0]["nivel"])
        else:
            alvo1 = entrada + risco * 1.5
        alvo2 = entrada + risco * 2.0
    else:  # short
        entrada = preco
        nivel_ref = gatilho_ref.get("nivel")
        if nivel_ref:
            stop = float(nivel_ref) * 1.001
        else:
            stop = preco + (preco * 0.005)
        suportes = [n for n in proximos
                    if n.get("tipo") == "suporte" and n.get("nivel", 0) < preco]
        suportes.sort(key=lambda n: -n.get("nivel"))
        risco = stop - entrada
        if risco <= 0: return None
        if suportes:
            alvo1 = float(suportes[0]["nivel"])
        else:
            alvo1 = entrada - risco * 1.5
        alvo2 = entrada - risco * 2.0
    # v6.79 — ROMPIMENTO DE RANGE: alvo1 = projecao da altura (measured move);
    # alvo2 estende +50%% da altura. Sobrepoe os alvos genericos acima.
    _rng_mm = direcao_info.get("range") or {}
    if str(direcao_info.get("cenario") or "").startswith("rompimento_range") and _rng_mm:
        _alt = float(_rng_mm.get("altura_pts") or 0)
        if direcao == "long" and _rng_mm.get("proj_alta"):
            alvo1 = float(_rng_mm["proj_alta"]); alvo2 = alvo1 + _alt * 0.5
        elif direcao == "short" and _rng_mm.get("proj_baixa"):
            alvo1 = float(_rng_mm["proj_baixa"]); alvo2 = alvo1 - _alt * 0.5
    # v6.80 — REVERSAO POR ESTRUTURA: alvo1 = projecao da altura do pivo.
    _sw_mm = direcao_info.get("swing") or {}
    if str(direcao_info.get("cenario") or "").startswith("reversao_estrutura") and _sw_mm.get("proj") is not None:
        _alt_sw = float(_sw_mm.get("altura_pts") or 0)
        if direcao == "long":
            alvo1 = float(_sw_mm["proj"]); alvo2 = alvo1 + _alt_sw * 0.5
        else:
            alvo1 = float(_sw_mm["proj"]); alvo2 = alvo1 - _alt_sw * 0.5
    # v7.09 — REGUA DA ESCADA (caso real do dono, 25/jul BTCUSD: range de 64.9
    # pts rompido a favor de 4/4 TFs; a projecao miuda dava alvo 35 pts e
    # R:R 1.03 — trade limpo barrado pela regua curta, enquanto o proprio BOT
    # narrava os suportes de 60m/4h como alvos tecnicos a 60-118 pts).
    # Em cenario de ROMPIMENTO, o measured move e PISO, nao teto: o alvo do
    # plano e a escada de niveis medidos na direcao — alvo1 = primeiro nivel
    # alem do risco (take parcial), alvo2 = segundo nivel quando existe, e o
    # R:R do plano e medido contra o alvo FINAL da cascata. So promove
    # (nunca encurta o que ja foi calculado) e so usa nivel que EXISTE.
    _alvo_rr = None
    if str(direcao_info.get("cenario") or "").startswith(("rompimento_range", "reversao_estrutura")):
        try:
            _escada_rr = suportes if direcao == "short" else resistencias
            _alem = []
            for _nv in (_escada_rr or [])[:4]:
                try:
                    _pnv = float(_nv.get("nivel"))
                    _dnv = (entrada - _pnv) if direcao == "short" else (_pnv - entrada)
                    if _dnv > risco:
                        _alem.append(_pnv)
                except Exception:
                    pass
            if _alem:
                if abs(_alem[0] - entrada) > abs(alvo1 - entrada):
                    alvo1 = _alem[0]
                if len(_alem) > 1 and abs(_alem[1] - entrada) > abs(alvo1 - entrada):
                    alvo2 = _alem[1]
                    _alvo_rr = alvo2   # plano em cascata: parcial no 1o, final no 2o
                else:
                    _alvo_rr = alvo1
        except Exception:
            _alvo_rr = None
    rr = abs((_alvo_rr if _alvo_rr is not None else alvo1) - entrada) / risco if risco > 0 else 0
    if rr < 1.0:
        return None  # R:R menor que 1:1 nao vale
    return {
        "entrada":       round(entrada, 4),
        "stop":          round(stop, 4),
        "alvo1":         round(alvo1, 4),
        "alvo2":         round(alvo2, 4),
        "risco_pts":     round(abs(entrada - stop), 4),
        "potencial_pts": round(abs(alvo1 - entrada), 4),
        "rr":            round(rr, 2),
    }


def _calcular_confluencias(direcao_info, fatos, leitura, veredito=None):
    """Soma pontos de confluencia (0-100) e lista os fatores. Determina a
    QUALIDADE do setup — quanto mais alinhado, mais estrelas."""
    if not direcao_info or not fatos: return {"score": 0, "confluencias": []}
    score = 0
    lista = []
    dir_pt = "alta" if direcao_info["direcao"] == "long" else "baixa"
    # +20 regime do TF de operacao alinhado
    regime_str = str(fatos.get("regime") or "").upper()
    if (dir_pt == "alta" and "ALTA" in regime_str) or (dir_pt == "baixa" and "BAIXA" in regime_str):
        score += 20
        lista.append({"peso": 20, "titulo": "Regime alinhado", "detalhe": f"TF de operacao em {regime_str}"})
    # +15 (v6.79) rompimento de lateralizacao: range medido com toques nos dois extremos
    if str(direcao_info.get("cenario") or "").startswith("rompimento_range"):
        _rng_cf = direcao_info.get("range") or {}
        score += 15
        lista.append({"peso": 15, "titulo": "Rompimento de lateralizacao",
                      "detalhe": (f"Range de {_rng_cf.get('altura_pts')} pts rompido "
                                  f"(fundo {_rng_cf.get('toques_fundo')}x · teto {_rng_cf.get('toques_topo')}x toques"
                                  + (", confirmado" if _rng_cf.get("confirmado") else "") + ")")})
    # +15 (v6.80) reversao por estrutura (pivo 1-2-3): 2o extremo mais fraco + neckline rompida
    if str(direcao_info.get("cenario") or "").startswith("reversao_estrutura"):
        _sw_cf = direcao_info.get("swing") or {}
        score += 15
        lista.append({"peso": 15, "titulo": "Reversao por estrutura (pivo 1-2-3)",
                      "detalhe": (f"Extremos {_sw_cf.get('p1')} -> {_sw_cf.get('p2')}, "
                                  f"neckline {_sw_cf.get('neckline')} rompida"
                                  + (", confirmado" if _sw_cf.get("confirmado") else ""))})
    # +15 TF maior (4h) alinhado via momentum semantico
    momentum_tfs = (leitura or {}).get("momentum_tfs") or {}
    m4h = momentum_tfs.get("4h") or {}
    rec4h = str(m4h.get("recentes") or "").lower()
    if dir_pt == "alta" and "alta" in rec4h and "baixa" not in rec4h:
        score += 15
        lista.append({"peso": 15, "titulo": "4h a favor", "detalhe": m4h.get("recentes")})
    elif dir_pt == "baixa" and "baixa" in rec4h and "alta" not in rec4h:
        score += 15
        lista.append({"peso": 15, "titulo": "4h a favor", "detalhe": m4h.get("recentes")})
    # +15 padrao formal na direcao
    for pad in (fatos.get("padroes_formais") or []):
        direc = str(pad.get("direcao") or "").lower()
        if dir_pt in direc:
            score += 15
            lista.append({"peso": 15, "titulo": f"Padrao {pad.get('nome')}",
                          "detalhe": f"formando no {pad.get('tf')}"})
            break
    # +15 (3+ toques) ou +10 (2 toques) do nivel testado
    testando = fatos.get("niveis_sendo_testados") or []
    if testando:
        toques_max = max((nv.get("toques") or 0) for nv in testando)
        if toques_max >= 3:
            score += 15
            lista.append({"peso": 15, "titulo": f"Nivel forte ({toques_max} toques)",
                          "detalhe": f"{testando[0].get('tipo')} em {testando[0].get('nivel')}"})
        elif toques_max >= 2:
            score += 10
            lista.append({"peso": 10, "titulo": f"Duplo {testando[0].get('tipo')}",
                          "detalhe": f"em {testando[0].get('nivel')}"})
    # +15 banco historico (confirmacao) forte
    conf = (leitura or {}).get("confirmacao") or {}
    if isinstance(conf, dict):
        sc = conf.get("score") or 0
        if sc >= 65:
            score += 15
            lista.append({"peso": 15, "titulo": f"Historico forte ({sc}%)",
                          "detalhe": conf.get("veredito") or "confirmado"})
        elif sc >= 50:
            score += 8
            lista.append({"peso": 8, "titulo": f"Historico neutro ({sc}%)",
                          "detalhe": conf.get("veredito") or "misto"})
    # +10 momentum das ultimas 3 velas do TF de operacao
    tf_op = str((leitura or {}).get("tf_op") or "").lower()
    mtf_op = momentum_tfs.get(tf_op) if tf_op else None
    if mtf_op:
        rec = str(mtf_op.get("recentes") or "").lower()
        if dir_pt in rec and "consecut" in rec:
            score += 10
            lista.append({"peso": 10, "titulo": "Momentum recente",
                          "detalhe": mtf_op.get("recentes")})
    # +10 veredito da analise cruzada alinhado
    if veredito and str(veredito.get("sinal") or "").lower() == "alinhado":
        score += 10
        lista.append({"peso": 10, "titulo": "Analise cruzada ALINHADA",
                      "detalhe": veredito.get("veredito") or ""})
    return {"score": min(100, score), "confluencias": lista}


def _score_para_estrelas(score):
    if score >= 85: return 5
    if score >= 70: return 4
    if score >= 55: return 3
    if score >= 40: return 2
    return 1


# ──────────────────────────────────────────────────────────────────────────
#  CIRCUIT BREAKERS (protegem o dinheiro do usuario)
# ──────────────────────────────────────────────────────────────────────────

def _circuit_state_do_dia(bot_id, equity_atual):
    """Mantem estado do dia por bot: equity de inicio, contagem de operacoes.
    Reseta automaticamente quando a data muda."""
    from datetime import date
    hoje = date.today().isoformat()
    st = _CIRCUIT_STATE.get(bot_id)
    if not st or st.get("data_ref") != hoje:
        st = {
            "data_ref": hoje,
            "equity_inicio_dia": equity_atual if equity_atual else 0,
            "ops_hoje": 0,
            "ultima_op_ts": 0,
        }
        _CIRCUIT_STATE[bot_id] = st
    # se ainda nao tinha equity e agora tem, seta
    if not st["equity_inicio_dia"] and equity_atual:
        st["equity_inicio_dia"] = equity_atual
    return st


def _chk_ia_ultima(bot_id):
    """v7.06 — a ultima analise cruzada do cockpit (_ANL_HIST) vira voto no
    checklist: sinal alinhado/divergente/neutro + idade. Custo zero."""
    try:
        import time as _t
        hist = (_ANL_HIST.get(bot_id) or [])
        if not hist:
            return None
        h = hist[-1] or {}
        ts = h.get("ts")
        ha = (_t.time() - float(ts)) if ts else None
        return {"sinal": h.get("sinal"), "ha_s": ha}
    except Exception:
        return None


def _chk_leitura(det, s, b, c_op=None):
    """v7.04 — monta o checklist do card com os formatos REAIS da leitura
    (fix do print do dono: 4/4 baixa na tela e o LED de tendencia vermelho).
    Direcao: alinhamento -> cascata -> range rompido -> regime. R:R: derivado
    da projecao do range (proj_alta/proj_baixa vs nivel rompido) quando ha
    rompimento — o gate de EXECUCAO no detector segue usando o rr dos niveis."""
    try:
        pac = _scanner_pacote(det) or {}
        ex = _extras_cockpit(det, s) or {}
        _alp = pac.get("alinhamento")
        ali = str((_alp.get("resumo") or _alp.get("lado")) if isinstance(_alp, dict) else (_alp or "")).lower()
        casc = str(pac.get("cascata_reversao") or "").lower()
        regj = det.get("regime")
        reg = str((regj.get("estado") if isinstance(regj, dict) else regj) or "").upper()
        rng = ex.get("range") or {}
        est_r = str(rng.get("estado") or "")
        direcao = None
        if "baixa" in ali: direcao = "short"
        elif "alta" in ali: direcao = "long"
        elif "baixa" in casc: direcao = "short"
        elif "alta" in casc: direcao = "long"
        elif est_r == "rompeu_baixo" or "BAIXA" in reg: direcao = "short"
        elif est_r == "rompeu_cima" or "ALTA" in reg: direcao = "long"
        # R:R do rompimento do range: entrada=preco agora, alvo=projecao,
        # invalidacao=voltar pro nivel rompido. So calcula com dado real.
        rr = None
        try:
            preco = float(det.get("preco"))
            alvo = inval = None
            if est_r == "rompeu_baixo":
                alvo, inval = rng.get("proj_baixa"), rng.get("fundo")
            elif est_r == "rompeu_cima":
                alvo, inval = rng.get("proj_alta"), rng.get("teto")
            if alvo is not None and inval is not None:
                risco = abs(preco - float(inval))
                ganho = abs(float(alvo) - preco)
                # v7.09 — REGUA DA ESCADA no card: o alvo do rompimento e o
                # melhor entre a projecao e os 2 primeiros niveis da escada
                # na direcao (dist_pts alem do risco). Mesma regua do detector.
                try:
                    _esc_c = ex.get("niveis_abaixo") if est_r == "rompeu_baixo" else ex.get("niveis_acima")
                    for _nvc in (_esc_c or [])[:2]:
                        _dc = abs(float(_nvc.get("dist_pts")))
                        if _dc > risco and _dc > ganho:
                            ganho = _dc
                except Exception:
                    pass
                if risco > 0:
                    rr = round(ganho / risco, 2)
        except Exception:
            pass
        # v7.20 — R:R CONDICIONAL DO PLANO EM FORMACAO: sem rompimento de
        # range, deriva o R:R da ESTRUTURA DE SWING (o BOT ja narra o plano;
        # o card ignorava). formando: entrada=neckline, risco=|neck-P2|,
        # alvo=projecao. rompeu: entrada=preco, invalidacao=neckline,
        # alvo=projecao. Mesma regua da escada v7.09 (promove alvo pros
        # niveis medidos alem do risco). Rotulado como plano condicional.
        rr_nota = None
        try:
            if rr is None:
                sw = ex.get("swing") or {}
                sw_est = str(sw.get("estado") or "")
                sw_dir = str(sw.get("direcao") or "").lower()
                neck = sw.get("neckline")
                proj = sw.get("projecao")
                inv = sw.get("invalidacao")
                preco2 = float(det.get("preco"))
                if sw_est in ("formando", "rompeu") and neck is not None and proj is not None:
                    if sw_est == "formando" and inv is not None:
                        ent2 = float(neck)
                        risco2 = abs(ent2 - float(inv))
                        rr_nota = f"plano condicional — no rompimento da neckline {float(neck):g}"
                    else:
                        ent2 = preco2
                        risco2 = abs(ent2 - float(neck))
                        rr_nota = "plano do rompimento da estrutura"
                    ganho2 = abs(float(proj) - ent2)
                    try:
                        _esc2 = ex.get("niveis_abaixo") if sw_dir == "baixa" else ex.get("niveis_acima")
                        for _nv2 in (_esc2 or [])[:2]:
                            _d2 = abs(float(_nv2.get("dist_pts")))
                            if _d2 > risco2 and _d2 > ganho2:
                                ganho2 = _d2
                    except Exception:
                        pass
                    if risco2 > 0 and ganho2 > 0:
                        rr = round(ganho2 / risco2, 2)
                    else:
                        rr_nota = None
                if direcao is None and sw_dir in ("alta", "baixa"):
                    direcao = "long" if sw_dir == "alta" else "short"
        except Exception:
            rr_nota = None
        candles = c_op if c_op is not None else []
        return _checklist_entrada(direcao=direcao, scanner=pac, extras=ex,
                                  candles_op=candles, rr=rr, rr_nota=rr_nota,
                                  atr_pts=ex.get("atr_pts"),
                                  simbolo=det.get("simbolo") or (s or {}).get("simbolo") or "",
                                  bot=b,
                                  sensibilidade=((b or {}).get("config_operacional") or {}).get("modo_sensibilidade"),
                                  ia=_chk_ia_ultima((b or {}).get("id")))
    except Exception:
        return None


_CHK_CAL_CACHE = {}   # v7.03: simbolo -> (ts, evento_quente|None) — cache 120s

def _chk_moedas_do_simbolo(simbolo):
    """Moedas relevantes pro checklist de noticia. Deterministico e defensivo."""
    sim = str(simbolo or "").upper()
    ms = set()
    for m in ("USD", "EUR", "GBP", "JPY", "AUD", "CAD", "CHF", "NZD"):
        if m in sim:
            ms.add(m)
    if any(k in sim for k in ("XAU", "BTC", "US500", "NAS", "US30", "SPX")):
        ms.add("USD")
    return ms or {"USD"}


def _chk_noticia_quente(simbolo):
    """Item 1 do checklist: evento de ALTO impacto na janela (-15min..+45min)
    pras moedas do simbolo, lendo calendario_economico. Cache 120s por simbolo.
    Retorna (ok, detalhe): True=sem evento quente; False=evento quente;
    None=sem dado (tabela vazia/erro) — nunca inventa."""
    import time as _t
    from datetime import datetime as _dt2, timedelta as _td2, timezone as _tz2
    sim = str(simbolo or "").upper()
    hit = _CHK_CAL_CACHE.get(sim)
    if hit and (_t.time() - hit[0]) < 120:
        return hit[1]
    res = (None, "calendario sem dado — verificacao manual")
    try:
        sb = _sb_admin()
        if sb is not None:
            agora = _dt2.now(_tz2.utc)
            ini = (agora - _td2(minutes=15)).isoformat()
            fim = (agora + _td2(minutes=45)).isoformat()
            r = (sb.table("calendario_economico").select("*")
                 .gte("data_evento", ini).lte("data_evento", fim)
                 .limit(60).execute())
            linhas = r.data or []
            moedas = _chk_moedas_do_simbolo(sim)
            quente = None
            for ev in linhas:
                if str(ev.get("impacto") or "").lower() != "alto":
                    continue
                if str(ev.get("moeda") or "").upper() in moedas:
                    quente = ev
                    break
            if quente is not None:
                res = (False, f"noticia de alto impacto na janela: {str(quente.get('titulo') or quente.get('evento') or '?')[:60]}")
            else:
                res = (True, "sem noticia de alto impacto na janela (-15/+45min)")
    except Exception:
        res = (None, "calendario indisponivel — verificacao manual")
    _CHK_CAL_CACHE[sim] = (_t.time(), res)
    return res


def _checklist_entrada(direcao=None, scanner=None, extras=None, candles_op=None,
                       rr=None, atr_pts=None, simbolo="", bot=None,
                       sensibilidade=None, ia=None, rr_nota=None):
    """v7.03 — CHECKLIST DE ENTRADA (desenho do dono, LEDs verde/vermelho):
    o portao deterministico que a IA e o BOT checam ANTES de qualquer execucao
    da plataforma. So dados que a casa JA mede — custo zero de IA, nunca inventa:
      1 noticia     — calendario_economico (alto impacto na janela)
      2 tendencia   — regime/alinhamento do scanner a favor da direcao
      3 volume      — ultima vela do TF de operacao vs media das 10 anteriores
      4 sr          — corredor livre na escada de niveis (>=0.8 ATR sem nivel contrario)
      5 rr          — projecao medida: risco:retorno >= 1:2
      6 estrategia  — linhagem registrada (config_operacional.estrategia_nome)
    ok True=verde, False=vermelho, None=sem dado (cinza; nao bloqueia, e dito).
    pode_entrar = TODOS os itens com dado em verde E ha direcao definida."""
    itens = []
    d = str(direcao or "").lower()
    alvo = "alta" if d in ("long", "buy", "alta") else ("baixa" if d in ("short", "sell", "baixa") else "")

    # 1) NOTICIA
    ok1, det1 = _chk_noticia_quente(simbolo)
    itens.append({"id": "noticia", "nome": "Noticia verificada", "ok": ok1, "detalhe": det1,
                  "pct": (100 if ok1 is True else (0 if ok1 is False else None))})

    # 2) TENDENCIA CONFIRMADA
    ok2, det2 = None, "sem dado do scanner"
    try:
        sc = scanner or {}
        _al = sc.get("alinhamento")
        # v7.08: alinhamento real e um dict {lado, resumo} — extrai o texto
        alin = str((_al.get("resumo") or _al.get("lado")) if isinstance(_al, dict) else (_al or ""))
        regime = ""
        try:
            regime = str((sc.get("regime") or {}).get("estado") or sc.get("regime") or "").upper()
        except Exception:
            regime = str(sc.get("regime") or "").upper()
        if not alvo:
            ok2, det2 = False, "sem direcao definida — aguardando gatilho de entrada"
        elif alin or regime:
            a_favor = (alvo in alin.lower()) or (alvo.upper() in regime)
            contra = (("baixa" if alvo == "alta" else "alta") in alin.lower()) and not a_favor
            if a_favor and "divid" not in alin.lower():
                ok2, det2 = True, (alin or regime)[:80]
            elif contra or "divid" in alin.lower():
                ok2, det2 = False, (alin or regime)[:80] or "TFs divididos/contra"
            else:
                ok2, det2 = False, "tendencia nao confirma a direcao"
    except Exception:
        pass
    # v7.32 — CICLO CIRCULAR no portao de tendencia (decisao do dono 04/ago,
    # caso do Brent: barra gigante de reversao bloqueada como contra-tendencia
    # enquanto 30 barras de M1 contavam a historia). CONTRA A TENDENCIA e
    # rotulo falso quando o sistema distingue reversao de pullback: se os
    # criterios estruturais dizem REVERSAO_EM_CURSO na direcao proposta, a
    # entrada contra e a PRIMEIRA da tendencia nova — item 2 vira verde com a
    # marca contra_tendencia na ficha (telemetria: a BabyMachine mede se paga).
    # PULLBACK ou INDEFINIDO = bloqueio original mantido.
    ciclo = None
    item2_contra = False
    try:
        if alvo and candles_op:
            ciclo = _ciclo_reversao_pullback(candles_op, scanner=scanner,
                                             alvo=alvo, atr_pts=atr_pts)
        if (ok2 is False and ciclo and "sem direcao" not in str(det2)
                and ciclo.get("veredicto") == "REVERSAO_EM_CURSO"):
            ok2 = True
            item2_contra = True
            det2 = ("reversao confirmada (" + str(ciclo.get("n_ok")) +
                    "/5 criterios) — primeira entrada da tendencia nova")
        elif (ok2 is False and ciclo and "sem direcao" not in str(det2)
                and ciclo.get("veredicto") == "INDEFINIDO"):
            det2 = (str(det2)[:60] + " · ciclo " + str(ciclo.get("n_ok")) +
                    "/5 criterios de reversao — aguardando")
    except Exception:
        pass
    pct2 = None
    try:
        if item2_contra and ciclo:
            pct2 = round(100 * float(ciclo.get("n_ok") or 0) / 5.0)
            raise Exception("pct2 do ciclo")
        _m2 = re.search(r"(\d+)\s*de\s*(\d+)", alin)
        if _m2 and int(_m2.group(2)) > 0:
            pct2 = round(100 * int(_m2.group(1)) / int(_m2.group(2)))
        elif ok2 is not None:
            pct2 = 100 if ok2 else 0
    except Exception:
        pct2 = 100 if ok2 else (0 if ok2 is False else None)
    _it2 = {"id": "tendencia", "nome": "Tendencia confirmada", "ok": ok2, "detalhe": det2,
            "pct": pct2}
    if item2_contra:
        _it2["contra_tendencia"] = True   # v7.32 — telemetria: reversao liberou o portao
    itens.append(_it2)

    # 3) VOLUME CONFIRMADO
    ok3, det3 = None, "EA sem volume nos candles (reenvie pra atualizar)"
    try:
        cs = candles_op or []
        # v7.05: candles chegam como LISTA [o,h,l,c,v] (_parse_c) ou dict {v}
        vols = []
        for c in cs:
            try:
                if isinstance(c, dict):
                    vols.append(float(c.get("v") or 0))
                elif isinstance(c, (list, tuple)) and len(c) >= 5:
                    vols.append(float(c[4] or 0))
            except Exception:
                pass
        # v7.08: a ULTIMA vela esta EM FORMACAO (volume parcial) — medir ela
        # contra a media deixava o LED vermelho injustamente. Compara a ultima
        # vela FECHADA com a media das 10 fechadas anteriores a ela.
        if len(vols) >= 7 and any(v > 0 for v in vols):
            ult = vols[-2]
            base = [v for v in vols[-12:-2] if v > 0]
            med = (sum(base) / len(base)) if base else 0
            if med > 0:
                pct3 = min(100, round(100 * ult / med))
                if ult >= med:
                    ok3, det3 = True, f"volume da ultima vela fechada {ult:.0f} >= media {med:.0f}"
                else:
                    ok3, det3 = False, f"volume fraco na ultima fechada: {ult:.0f} < media {med:.0f}"
    except Exception:
        pass
    itens.append({"id": "volume", "nome": "Volume confirmado", "ok": ok3, "detalhe": det3,
                  "pct": locals().get("pct3")})

    # 4) SUPORTE/RESISTENCIA ANALISADO
    ok4, det4 = None, "escada de niveis sem dado"
    try:
        esc = extras or {}   # v7.05: niveis_acima/niveis_abaixo vivem na RAIZ do extras
        atr = float(atr_pts or (extras or {}).get("atr_pts") or 0)
        if not alvo:
            ok4, det4 = False, "sem direcao definida — aguardando gatilho"
        else:
            contra = esc.get("niveis_acima") if alvo == "alta" else esc.get("niveis_abaixo")
            if isinstance(contra, list) and atr > 0:
                dists = []
                for n in contra:
                    try:
                        dv = n.get("dist_pts", n.get("dist", n.get("distancia")))
                        if dv is not None:
                            dists.append(abs(float(dv)))
                    except Exception:
                        pass
                if dists:
                    prox = min(dists)
                    pct4 = min(100, round(100 * prox / (0.8 * atr)))
                    if prox >= 0.8 * atr:
                        ok4, det4 = True, f"corredor livre: nivel contrario a {prox:.0f} pts (>= {0.8*atr:.0f})"
                    else:
                        ok4, det4 = False, f"nivel contrario COLADO a {prox:.0f} pts (< 0.8 ATR) — entrada do lado errado da barreira"
                else:
                    ok4, det4, pct4 = True, "sem nivel contrario mapeado no caminho", 100
            elif isinstance(contra, list):
                ok4, det4 = (True, "sem nivel contrario mapeado") if not contra else (None, "sem ATR pra medir o corredor")
    except Exception:
        pass
    itens.append({"id": "sr", "nome": "Suporte/Resistencia analisado", "ok": ok4, "detalhe": det4,
                  "pct": locals().get("pct4")})

    # 5) RELACAO RISCO:RETORNO 1:2+
    ok5, det5 = False, "sem projecao (stop/alvo) — entrada sem plano nao entra"
    try:
        if rr is not None and str(rr) != "":
            rrf = float(rr)
            if rrf >= 2.0:
                ok5, det5 = True, f"R:R {rrf:.2f} (>= 1:2)"
            else:
                ok5, det5 = False, f"R:R {rrf:.2f} abaixo de 1:2 — aguardar"
    except Exception:
        pass
    # v7.20 — rotulo do plano condicional (honestidade: R:R do plano que so
    # vale se o gatilho disparar, nao de posicao aberta)
    try:
        if rr_nota and rr is not None and str(rr) != "":
            det5 = f"{det5} · {rr_nota}"
    except Exception:
        pass
    pct5 = 0
    try:
        if rr is not None and str(rr) != "":
            pct5 = min(100, round(100 * float(rr) / 2.0))
    except Exception:
        pass
    itens.append({"id": "rr", "nome": "Risco:Retorno 1:2+", "ok": ok5, "detalhe": det5, "pct": pct5})

    # 6) ESTRATEGIA AJUSTADA
    ok6, det6 = False, "estrategia nao registrada — reenvie pelo Editor"
    try:
        en = ((bot or {}).get("config_operacional") or {}).get("estrategia_nome")
        if en:
            ok6, det6 = True, f"estrategia: {str(en)[:60]}"
    except Exception:
        pass
    itens.append({"id": "estrategia", "nome": "Estrategia ajustada", "ok": ok6, "detalhe": det6,
                  "pct": (100 if ok6 else 0)})

    # 7) LEITURA DA IA FAVORAVEL (pedido do dono: a IA tambem vota no portao —
    #    custo ZERO novo: le a ultima analise cruzada que o cockpit ja gerou)
    ok7, det7 = None, "sem analise recente da IA (nao bloqueia)"
    try:
        if ia and ia.get("sinal"):
            sn = str(ia.get("sinal")).lower()
            hs = ia.get("ha_s")
            fresca = (hs is None) or (float(hs) <= 900)
            sufixo = (f" (ha {int(float(hs))}s)" if hs is not None else "")
            if fresca and sn == "alinhado":
                ok7, det7 = True, "IA ALINHADA com a leitura do BOT" + sufixo
            elif fresca and sn == "divergente":
                ok7, det7 = False, "IA DIVERGENTE da leitura do BOT" + sufixo
            elif fresca:
                ok7, det7 = None, f"IA neutra/observacao ({sn}) — nao vota"
    except Exception:
        pass
    pct7 = None
    if ok7 is True: pct7 = 100
    elif ok7 is False: pct7 = 0
    elif "neutra" in str(det7): pct7 = 50
    itens.append({"id": "ia", "nome": "Leitura da IA favoravel", "ok": ok7, "detalhe": det7, "pct": pct7})

    avaliados = [i for i in itens if i["ok"] is not None]
    vermelhos = [i for i in itens if i["ok"] is False]
    # v7.06 — TOLERANCIA POR SENSIBILIDADE (decisao do dono: exigir 100% de tudo
    # recusa o trade limpo; o meio-termo e graduado e usa o dial que JA existe):
    #   conservador = todos os itens com dado verdes (comportamento original)
    #   moderado    = tolera 1 vermelho NAO-critico
    #   agressivo   = tolera 2 vermelhos NAO-criticos
    # CRITICOS (nunca flexibilizam): Noticia quente e R:R < 1:2 — noticia de
    # alto impacto e entrada sem plano nao se negociam em nenhum modo.
    sens = str(sensibilidade or "conservador").lower()
    tol = {"conservador": 0, "moderado": 1, "agressivo": 2}.get(sens, 0)
    criticos = [i for i in vermelhos if i["id"] in ("noticia", "rr")]
    pode = (bool(alvo) and bool(avaliados) and not criticos
            and len(vermelhos) <= tol)
    faltando = [i["nome"] for i in itens if i["ok"] is False]
    # v7.10 — PRONTIDAO DA ENTRADA (desenho do dono, com nome honesto: e o %
    # de condicoes satisfeitas em tempo real, NAO probabilidade de lucro —
    # a casa nao promete retorno). Media simples dos itens com dado.
    _pcts = [i.get("pct") for i in itens if i.get("pct") is not None]
    prontidao = round(sum(_pcts) / len(_pcts)) if _pcts else None
    # v7.11 — PROBABILIDADE DE EXECUCAO (definicao do dono): a chance de a
    # PROXIMA ENTRADA disparar, dado o cenario em construcao diante do Bot e
    # da IA — nada a ver com lucro. Formula deterministica coerente com o
    # comportamento real do portao: parte da media das condicoes, e travada
    # pelos itens CRITICOS (reprovado = portao nao abre, teto 10%) e pela
    # existencia de gatilho (sem direcao localizada = entrada nao e iminente,
    # teto 25%), e sobe pro topo quando o portao JA esta aberto (>= 90%).
    prob = prontidao if prontidao is not None else 0
    if not alvo:
        prob = min(prob, 25)
    if criticos:
        prob = min(prob, 10)
    if pode:
        prob = max(prob, 90)
    return {"itens": itens, "pode_entrar": pode, "faltando": faltando,
            "direcao": alvo or None, "sensibilidade": sens, "tolerancia": tol,
            "vermelhos": len(vermelhos), "prontidao": prontidao,
            "prob_execucao": prob,
            "ciclo": ciclo,   # v7.32 — veredicto reversao x pullback (ficha)
            "contra_tendencia": item2_contra,
            "criticos_reprovados": [i["nome"] for i in criticos]}


def _check_pode_operar(bot, config, snap):
    """Retorna (pode_bool, motivo). Se pode=False, motivo explica o que barrou."""
    if config.get("pausado"):
        return False, "bot pausado manualmente"
    if bot.get("posicoes_abertas") and int(bot.get("posicoes_abertas") or 0) > 0:
        return False, "ja tem posicao aberta"
    bot_id = bot.get("id")
    equity = float(snap.get("equity") or 0) if snap else 0
    st = _circuit_state_do_dia(bot_id, equity)
    # cooldown entre operacoes do mesmo bot
    import time
    if time.time() - float(st.get("ultima_op_ts") or 0) < _OPORT_COOLDOWN_SEG:
        return False, "cooldown entre operacoes"
    # max operacoes no dia
    max_dia = int(config.get("max_operacoes_dia") or 10)
    if st["ops_hoje"] >= max_dia:
        return False, f"limite diario de {max_dia} operacoes atingido"
    # drawdown maximo diario
    dd_max = float(config.get("drawdown_max_dia") or 5.0)
    if st["equity_inicio_dia"] and equity:
        dd_atual = (st["equity_inicio_dia"] - equity) / st["equity_inicio_dia"] * 100
        if dd_atual >= dd_max:
            return False, f"drawdown ({dd_atual:.1f}%) atingiu limite ({dd_max}%)"
    return True, "ok"


# ──────────────────────────────────────────────────────────────────────────
#  NARRADOR IA (custo baixo — so quando ha oportunidade real)
# ──────────────────────────────────────────────────────────────────────────

def _narrar_oportunidade_ia(direcao_info, niveis, confluencias_info, leitura):
    """Chama Haiku pra formatar a oportunidade em texto de trader profissional.
    Custo ~$0.0005 por chamada. So chamado quando ja passou pelo filtro de
    estrelas — evita gastar tokens em setup fraco."""
    import sys
    chave = os.environ.get("ANTHROPIC_API_KEY", "").strip()
    if not chave:
        # fallback determinístico se nao ha IA
        return (f"{direcao_info['direcao'].upper()} em {niveis['entrada']} — "
                f"stop {niveis['stop']}, alvo {niveis['alvo1']} (R:R {niveis['rr']}). "
                f"{len(confluencias_info['confluencias'])} confluencias somam {confluencias_info['score']} pontos.")
    idioma = (leitura or {}).get("idioma") or "pt"
    idioma_nome = _IDIOMA_NOME.get(idioma, "portugues brasileiro")
    try:
        import httpx
        confs = "; ".join(f"{c['titulo']} ({c['peso']}pts): {c.get('detalhe','')}"
                          for c in (confluencias_info.get("confluencias") or [])[:5])
        sistema = (
            "Voce e um analista de trading escrevendo o plano de entrada de uma OPORTUNIDADE detectada. "
            "Escreva EM " + idioma_nome + ", 2 a 3 frases curtas (max ~280 caracteres), sem markdown. "
            "Tom: pratico, direto, tecnico. Comece afirmando A DIRECAO e O CENARIO. Depois cite a "
            "confluencia MAIS FORTE. Encerre com o gatilho concreto (entrada, stop, alvo). "
            "PROIBIDO: promessas de lucro, previsoes, palavras como 'vai', 'garante', 'certamente'. "
            "PERMITIDO: 'pode', 'tende', 'favorece', 'aumenta a probabilidade'."
        )
        contexto = {
            "direcao": direcao_info["direcao"],
            "cenario": direcao_info.get("cenario"),
            "entrada": niveis["entrada"],
            "stop": niveis["stop"],
            "alvo1": niveis["alvo1"],
            "rr": niveis["rr"],
            "risco_pts": niveis["risco_pts"],
            "score_confluencia": confluencias_info["score"],
            "confluencias": confs,
        }
        r = httpx.post(
            "https://api.anthropic.com/v1/messages",
            headers={"x-api-key": chave, "anthropic-version": "2023-06-01",
                     "content-type": "application/json"},
            json={
                "model": os.environ.get("RADAR_IA_MODELO", "claude-haiku-4-5-20251001"),
                "max_tokens": 200,
                "temperature": 0.6,
                "system": sistema,
                "messages": [{"role": "user", "content":
                    "Oportunidade detectada:\n" + json.dumps(contexto, ensure_ascii=False)}],
            },
            timeout=8.0,
        )
        if r.status_code != 200:
            print(f"NARRAR OPORT status {r.status_code}: {r.text[:200]}", file=sys.stderr)
            return None
        texto = "".join(b.get("text", "") for b in r.json().get("content", [])).strip()
        return texto[:400] if texto else None
    except Exception as e:
        print(f"NARRAR OPORT erro: {e}", file=sys.stderr)
        return None


# ──────────────────────────────────────────────────────────────────────────
#  ORQUESTRADOR — junta tudo, retorna oportunidade OU None
# ──────────────────────────────────────────────────────────────────────────

def _cooldown_oport_ativo(bot_id):
    """Ha uma oportunidade recente pro mesmo bot? Evita spam de setups."""
    import time
    hist = _oportunidade_hist(bot_id)
    if not hist: return False
    ultima = hist[-1]
    try:
        ts = _dt.fromisoformat(str(ultima.get("ts") or "").replace("Z", "+00:00"))
        return (_dt.now(_tz.utc) - ts).total_seconds() < _OPORT_COOLDOWN_SEG
    except Exception:
        return False


def _detectar_oportunidade(sb, bot, fatos, leitura, veredito=None, snap_dict=None):
    """Orquestra: config -> circuit -> direcao -> niveis -> confluencias ->
    estrelas -> limiar do modo -> IA narra -> registra. Silencioso e barato:
    detectores rodam sempre, IA so quando merece."""
    if not bot or not fatos: return None
    bot_id = bot.get("id")
    if not bot_id: return None
    config = _bot_config_get(bot_id)
    # v7.07 — a linha do bot (config_operacional) e a verdade entre workers e
    # restarts: sobrescreve a memoria pros campos do detector que o usuario setou.
    try:
        _co = bot.get("config_operacional") or {}
        for _k in _DETECTOR_DEFAULT_CONFIG:
            if _k in _co:
                config[_k] = _co[_k]
    except Exception:
        pass
    # v7.02 — LIGA/DESLIGA cross-worker: o pausado persistido no
    # config_operacional (Supabase) e a VERDADE — a memoria do worker que nao
    # recebeu o POST /config nao pode deixar o detector operar um bot que o
    # usuario DESLIGOU na tela (a linha `bot` ja veio carregada do banco, custo zero).
    try:
        _pz = (bot.get("config_operacional") or {}).get("pausado")
        if _pz is not None:
            config = {**config, "pausado": bool(_pz)}
    except Exception:
        pass
    if config["modo_operacional"] == "observar":
        return None  # observar nao dispara nada
    # cooldown pra nao spamar oportunidades identicas
    if _cooldown_oport_ativo(bot_id):
        return None
    # circuit breakers
    pode, motivo = _check_pode_operar(bot, config, snap_dict or {})
    if not pode:
        return None
    # direcao
    direcao_info = _detectar_direcao_potencial(fatos, leitura)
    if not direcao_info: return None
    # niveis
    niveis = _calcular_niveis_operacao(direcao_info, fatos)
    if not niveis: return None
    # confluencias
    confl = _calcular_confluencias(direcao_info, fatos, leitura, veredito)
    estrelas = _score_para_estrelas(confl["score"])
    # limiar do modo
    limiar = _ESTRELAS_LIMIAR_POR_MODO.get(config["modo_sensibilidade"], 4)
    if estrelas < limiar:
        return None
    # v7.03 — CHECKLIST DE ENTRADA (portao do dono): TODOS os LEDs com dado em
    # VERDE, senao a oportunidade NAO nasce — nem UI copiloto, nem automatico.
    try:
        chk = _checklist_entrada(
            direcao=direcao_info.get("direcao"),
            scanner=(leitura or {}).get("scanner"),
            extras=(leitura or {}).get("extras"),
            candles_op=(leitura or {}).get("candles_op"),
            rr=niveis.get("rr"),
            atr_pts=(fatos or {}).get("atr_pts"),
            simbolo=(leitura or {}).get("simbolo") or bot.get("simbolo") or "",
            bot=bot,
            sensibilidade=(config or {}).get("modo_sensibilidade"),
            ia=_chk_ia_ultima(bot_id))
        if not chk.get("pode_entrar"):
            try:
                print(f"[checklist] bot {bot_id} BARRADO: {', '.join(chk.get('faltando') or ['sem dado'])}")
            except Exception:
                pass
            # v7.32 — ESPERA CARIMBADA (fecha a pendencia (b) da v7.12): toda
            # recusa da PLATAFORMA vira evento auditavel com o motivo exato e o
            # veredicto do ciclo — acaba a autopsia por print. Throttle de 1
            # evento por bot+motivo por barra do TF (anti-flood, mesma filosofia
            # do debounce v7.19 do EA). Non-blocking: falha aqui nunca trava.
            try:
                import time as _t_rec
                _mot_lst = chk.get("faltando") or ["sem dado"]
                _mot_key = ",".join(sorted(_mot_lst))[:180]
                _tfop_rec = str((leitura or {}).get("tf_op") or (leitura or {}).get("timeframe") or "").lower()
                _seg_rec = _CICLO_TF_SEG.get(_tfop_rec, 300)
                _k_rec = (str(bot_id), _mot_key)
                if _t_rec.time() - float(_REC_PLAT_STATE.get(_k_rec) or 0) >= _seg_rec:
                    _REC_PLAT_STATE[_k_rec] = _t_rec.time()
                    if len(_REC_PLAT_STATE) > 4000:
                        _REC_PLAT_STATE.clear()
                        _REC_PLAT_STATE[_k_rec] = _t_rec.time()
                    _ciclo_rec = (chk.get("ciclo") or {})
                    sb.table("agente_eventos").insert({
                        "user_id": bot.get("user_id"),
                        "tipo": "bot_recusada_plataforma", "regra": None,
                        "detalhe_json": {
                            "bot_nome": bot.get("nome") or "",
                            "bot_token": bot.get("bot_token") or "",
                            "simbolo": (leitura or {}).get("simbolo") or bot.get("simbolo") or "",
                            "direcao": direcao_info.get("direcao"),
                            "motivo": _mot_lst,
                            "ciclo_veredicto": _ciclo_rec.get("veredicto"),
                            "ciclo_n_ok": _ciclo_rec.get("n_ok"),
                            "prontidao": chk.get("prontidao"),
                            "estrelas": estrelas,
                        },
                    }).execute()
            except Exception:
                pass
            return None
    except Exception as _e_chk:
        try: print(f"[checklist] erro (nao barra por falha propria): {_e_chk}")
        except Exception: pass
        chk = None
    # passou! narra e registra
    explicacao = _narrar_oportunidade_ia(direcao_info, niveis, confl, leitura)
    oport = {
        "bot_id":         bot_id,
        "user_id":        bot.get("user_id"),
        "direcao":        direcao_info["direcao"],
        "cenario":        direcao_info.get("cenario"),
        "entrada":        niveis["entrada"],
        "stop":           niveis["stop"],
        "alvo1":          niveis["alvo1"],
        "alvo2":          niveis["alvo2"],
        "risco_pts":      niveis["risco_pts"],
        "potencial_pts":  niveis["potencial_pts"],
        "rr":             niveis["rr"],
        "score":          confl["score"],
        "estrelas":       estrelas,
        "confluencias":   confl["confluencias"],
        "explicacao":     explicacao,
        "modo_gerado":    config["modo_operacional"],
        "status":         "detectada",
        "checklist":      chk,   # v7.03 — o portao que a entrada passou (auditoria)
    }
    oport = _oport_push(bot_id, oport)
    # MODO AUTOMATICO: cria comando via /mt5/comando internamente
    if (config["modo_operacional"] == "automatico"
            and estrelas >= int(config.get("estrelas_min_auto") or 4)):
        try:
            _executar_oportunidade_auto(sb, bot, oport, config)
        except Exception as _e:
            try: print(f"[oport auto] {_e}")
            except Exception: pass
    return oport


def _executar_oportunidade_auto(sb, bot, oport, config):
    """Cria um comando MT5 partindo direto da oportunidade detectada em modo
    automatico. Chamado internamente — nao expoe via UI."""
    if not sb: return
    lote = float(config.get("lote_padrao") or 0.01)
    tipo = "buy" if oport["direcao"] == "long" else "sell"
    params = {"lote": lote, "sl": oport["stop"], "tp": oport["alvo1"]}
    _did = oport.get("decisao_id")           # c27r2: o servidor EMITE aqui
    if not _did:
        _okE, _rE = _r01_emitir_decisao(sb, bot, tipo)
        if not _okE:
            oport["status"] = "recusada_r_ciclo01"
            oport["recusa_motivo"] = _rE
            try: print(f"[r-ciclo-01] auto: emissao recusada — {_rE}")
            except Exception: pass
            return
        _did = _rE["id"]
    params["decisao_id"] = _did
    _okI, cmd = _r01_abrir_via_rpc(sb, bot, tipo, params, "auto_detector")
    if not _okI:                          # c27r4: recusa nomeada da RPC/leitura
        oport["status"] = "recusada_r_ciclo01"
        oport["recusa_motivo"] = cmd
        try: print(f"[r-ciclo-01] auto recusado: {cmd}")
        except Exception: pass
        return
    try:
        oport["comando_id"] = cmd.get("id")
        oport["status"] = "auto_executada"
        # atualiza circuit state (contagem de op)
        import time
        st = _CIRCUIT_STATE.get(bot.get("id")) or {}
        st["ops_hoje"] = int(st.get("ops_hoje") or 0) + 1
        st["ultima_op_ts"] = time.time()
        _CIRCUIT_STATE[bot.get("id")] = st
        # v6.76 — BabyMachine registra a decisao com contexto (non-blocking)
        try:
            _leit_bm = _anl_ler_leitura(sb, bot.get("user_id"), bot.get("id"))
            _bm_registrar_do_detector(sb, bot, oport, _leit_bm, None,
                                      cmd.get("id"), "detector_auto")
        except Exception as _e2:
            try: print(f"[bm auto] {_e2}")
            except Exception: pass
    except Exception as _e:
        try: print(f"[auto comando] {_e}")
        except Exception: pass


def _bot_por_token(sb, bot_token: str):
    try:
        r = sb.table("conector_bots").select("*").eq("bot_token", bot_token).limit(1).execute()
        return r.data[0] if r.data else None
    except Exception:
        return None


def _agente_em_cooldown(sb, user_id: str, regra: str) -> bool:
    """True se a regra já disparou dentro da janela de cooldown."""
    try:
        minutos = _AGENTE_COOLDOWN_MIN.get(regra, 60)
        corte = (_dt.now(_tz.utc) - _td(minutes=minutos)).isoformat()
        r = (sb.table("agente_sugestoes").select("id")
             .eq("user_id", user_id).eq("regra", regra)
             .gte("criado_em", corte).limit(1).execute())
        return bool(r.data)
    except Exception:
        return True  # na dúvida, não spamma


def _agente_emite(sb, user_id, regra, categoria, mensagem, severidade="info", contexto=None):
    try:
        sb.table("agente_sugestoes").insert({
            "user_id": user_id, "regra": regra, "categoria": categoria,
            "mensagem": mensagem, "severidade": severidade,
            "contexto_json": contexto or {},
        }).execute()
        sb.table("agente_eventos").insert({
            "user_id": user_id, "tipo": "sugestao_emitida", "regra": regra,
            "detalhe_json": {"mensagem": mensagem},
        }).execute()
    except Exception as e:
        print(f"[Agente] falha ao emitir {regra}: {e}")


def _agente_bloco_f(sb, user_id: str, bot: dict, snap: ConectorSnapshot):
    """
    BLOCO F — consistência vivo × backtest (regras puras, custo zero).
    F1: drawdown vivo chegou a 80%+ do max_drawdown testado p/ o ativo  -> alerta (cd 60min)
    F2: pirâmide além do plano (posições abertas > 3)                   -> atenção (cd 30min)
    F3: drawdown vivo SUPEROU o pior drawdown testado                   -> alerta (cd 15min)
    F4: operando símbolo SEM nenhum backtest validado                   -> atenção (cd 24h)
    O agente fala de DISCIPLINA contra o próprio plano. Nunca de mercado.
    """
    if not user_id:
        return 0
    emitidas = 0
    simbolo_mt5 = (snap.simbolo or bot.get("simbolo") or "").upper()
    ativo_catalogo = _MT5_PARA_CATALOGO.get(simbolo_mt5, simbolo_mt5)

    # Busca o pior (maior) drawdown testado pelo usuário nesse ativo
    max_dd_testado = None
    tem_backtest = False
    try:
        r = (sb.table("backtests_historico").select("max_drawdown")
             .eq("user_id", user_id).eq("ativo", ativo_catalogo)
             .order("criado_em", desc=True).limit(50).execute())
        dds = [abs(float(x["max_drawdown"])) for x in (r.data or []) if x.get("max_drawdown") is not None]
        tem_backtest = bool(r.data)
        if dds:
            max_dd_testado = max(dds)
    except Exception as e:
        print(f"[Agente F] consulta historico falhou: {e}")

    dd_vivo = abs(snap.drawdown_atual) if snap.drawdown_atual is not None else None

    # F3 — superou o testado (mais grave, avalia primeiro)
    if dd_vivo is not None and max_dd_testado and dd_vivo > max_dd_testado:
        if not _agente_em_cooldown(sb, user_id, "F3"):
            _agente_emite(sb, user_id, "F3", "posicao",
                f"O drawdown ao vivo em {ativo_catalogo} ({dd_vivo:.1f}%) já SUPEROU o pior cenário "
                f"do seu backtest ({max_dd_testado:.1f}%). O mercado está fora do que você validou. "
                f"Vale revisar a posição contra o seu plano.",
                "alerta", {"dd_vivo": dd_vivo, "dd_testado": max_dd_testado, "simbolo": simbolo_mt5})
            emitidas += 1
    # F1 — aproximando do testado (só se F3 não disparou)
    elif dd_vivo is not None and max_dd_testado and dd_vivo >= 0.8 * max_dd_testado:
        if not _agente_em_cooldown(sb, user_id, "F1"):
            _agente_emite(sb, user_id, "F1", "posicao",
                f"Drawdown ao vivo em {ativo_catalogo} ({dd_vivo:.1f}%) chegou a 80% do pior drawdown "
                f"do seu backtest ({max_dd_testado:.1f}%). Ainda dentro do plano, mas no limite dele.",
                "atencao", {"dd_vivo": dd_vivo, "dd_testado": max_dd_testado, "simbolo": simbolo_mt5})
            emitidas += 1

    # F2 — pirâmide além do plano
    if snap.posicoes_abertas and snap.posicoes_abertas > 3:
        if not _agente_em_cooldown(sb, user_id, "F2"):
            _agente_emite(sb, user_id, "F2", "intraday",
                f"{snap.posicoes_abertas} posições abertas em {ativo_catalogo} — acima das 3 da sua "
                f"pirâmide planejada. Exposição além do que foi testado.",
                "atencao", {"posicoes": snap.posicoes_abertas, "simbolo": simbolo_mt5})
            emitidas += 1

    # F4 — símbolo sem backtest validado
    if not tem_backtest:
        if not _agente_em_cooldown(sb, user_id, "F4"):
            _agente_emite(sb, user_id, "F4", "backtest",
                f"Você está operando {ativo_catalogo} ao vivo, mas não encontrei nenhum backtest seu "
                f"nesse ativo. Estratégia que funciona num ativo pode falhar em outro — vale validar "
                f"antes de seguir automatizado.",
                "atencao", {"simbolo": simbolo_mt5})
            emitidas += 1

    return emitidas


# ── R2: IDENTIDADE PELA SESSAO + PROPRIEDADE DO JOB (P1/P2) ─────────────────
def _sessao_user_id(authorization: str) -> str:
    """R2 P1/P2 — a identidade vem EXCLUSIVAMENTE da sessao Supabase.
    Recebe o cabecalho Authorization; exige a forma 'Bearer <access_token>' e
    valida o token no Supabase Auth (auth.get_user). Sem cabecalho, forma
    errada ou token invalido/expirado = 401. NAO existe variavel de ambiente,
    flag ou modo legado que desative esta checagem (o kill-switch da R1
    reprovada foi banido pela ordem R2)."""
    bruto = (authorization or "").strip()
    tok = ""
    if bruto.lower().startswith("bearer "):
        tok = bruto[7:].strip()
    if not tok:
        raise HTTPException(status_code=401, detail="Sessao obrigatoria (Authorization: Bearer <token>).")
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponivel")
    uid = None
    try:
        u = sb.auth.get_user(tok)
        uid = getattr(getattr(u, "user", None), "id", None)
    except Exception:
        uid = None
    if not uid:
        raise HTTPException(status_code=401, detail="Sessao invalida ou expirada.")
    _rl_registrar_identidade(bruto, "uid:" + str(uid))
    return str(uid)


def _mt5_job_do_usuario(job: dict, uid: str) -> bool:
    """R2 P2 — prova de propriedade do job: mt5_jobs.bot_token ->
    conector_bots.bot_token -> user_id DEVE ser o usuario da sessao.
    Comparacoes de segredo/identidade com hmac.compare_digest (tempo
    constante). Qualquer elo quebrado = False; quem chama responde o MESMO
    {status: desconhecido} de job inexistente — indistinguivel de proposito."""
    bt = str((job or {}).get("bot_token") or "")
    if not bt or not uid:
        return False
    sb = _sb_admin()
    if sb is None:
        return False
    try:
        r = (sb.table("conector_bots").select("bot_token,user_id")
             .eq("bot_token", bt).limit(2).execute())
        rows = r.data or []
    except Exception:
        return False
    for row in rows:
        try:
            tok_ok = _hmac.compare_digest(str(row.get("bot_token") or ""), bt)
            uid_ok = _hmac.compare_digest(str(row.get("user_id") or ""), str(uid))
        except Exception:
            continue
        if tok_ok and uid_ok:
            return True
    return False


# ── ENDPOINTS DO CONECTOR ───────────────────────────────────

@app.post("/conector/registrar")
def conector_registrar(req: ConectorRegistrar, authorization: str = Header(default="")):
    """Gera bot_token p/ o conector. Nunca pede credenciais de corretora.

    R2 P1 — AUTORIZACAO OBRIGATORIA: exige Authorization: Bearer com sessao
    Supabase valida (401 sem/invalida). O user_id usado em TODA leitura e
    gravacao vem da SESSAO; se o corpo trouxer user_id divergente = 403.

    IDENTIDADE ESTÁVEL (multi-bot): se já existe um bot ATIVO com o MESMO nome pra
    este usuário, REUSA o token dele em vez de criar outro. Assim o magic (derivado
    do token) NÃO muda entre reenvios — o EA que já está no gráfico continua batendo
    com o token da sessão, e a trilha/monitor reconhecem o bot mesmo que ele seja de
    um envio anterior. Sem isso, cada 'Enviar' criava um bot/token/magic novo e o
    snapshot do gráfico ia parar num token que a trilha não vigiava."""
    uid = _sessao_user_id(authorization)
    if (req.user_id or "").strip() and req.user_id.strip() != uid:
        raise HTTPException(status_code=403, detail="user_id do corpo diverge da sessao.")
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponível")
    nome = (req.nome or "Meu Bot").strip() or "Meu Bot"
    # C27R9: simbolo canonico do MT5 — o front mandava o rotulo do catalogo
    # ("XAU/USD (Ouro)" -> "XAUUSD (OURO)"), que nunca casa com o simbolo do
    # snapshot/decisao do Ciclo. Poda o parentese, a barra e espacos.
    import re as _re_sim
    req.simbolo = _re_sim.sub(r"\s*\([^)]*\)", "", str(req.simbolo or "")).replace("/", "").replace(" ", "").upper()[:20] or None
    # reusa o bot ATIVO mais recente com o mesmo nome (mesmo usuário)
    try:
        ex = (sb.table("conector_bots").select("*")
              .eq("user_id", uid).eq("nome", nome)
              .order("criado_em", desc=True).limit(10).execute())
        vivo = next((b for b in (ex.data or []) if not b.get("excluido")), None)
    except Exception:
        vivo = None
    if vivo and (vivo.get("bot_token") or "").strip():
        try:
            sb.table("conector_bots").update({
                "simbolo": req.simbolo, "magic_number": req.magic_number,
            }).eq("id", vivo["id"]).execute()
        except Exception:
            pass
        return {"ok": True, "bot_token": vivo["bot_token"], "reusado": True,
                "instrucao": "Bot já existente — mesmo token de antes (identidade estável)."}
    token = _secrets.token_hex(16)
    try:
        sb.table("conector_bots").insert({
            "user_id": uid, "bot_token": token,
            "nome": nome, "simbolo": req.simbolo,
            "magic_number": req.magic_number,
        }).execute()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Erro ao registrar bot: {e}")
    return {"ok": True, "bot_token": token, "reusado": False,
            "instrucao": "Cole este token no conector (config). Ele identifica o bot — nunca compartilhe."}


# ── VISÃO → REGIME: sintetiza o regime a partir do mapa de zonas cruas ──────
# "As duas juntas": o EA manda o CRU (posição do preço no canal EMA H/L por TF),
# a nuvem sintetiza aqui o regime — de graça, sem yfinance, usando o dado VIVO da
# corretora (o que o bot realmente vê). Top-down (regra do Adriano): a TENDÊNCIA
# é ancorada pelos tempos MAIORES (60m/4h/D — lentos, definem o regime), e a
# VIRADA é liderada pelos MENORES (1m/5m/15m — os menores confirmam antes dos
# maiores). Sem sobreposição, pra o sinal de virada não poluir a tendência.
_BT_ZONAS_ANCORA = ("z60", "z240", "zD")   # tendência estabelecida (top-down)
_BT_ZONAS_FAST   = ("z1", "z5", "z15")     # lideram a virada

# ═══ CAPÍTULO 1 DA INTELIGÊNCIA DINÂMICA (v6.48): CONFIRMAÇÃO CONTEXTUAL ═══
# O bot vê o cenário se formando (padrão + regime + zonas + nível); esta camada
# pergunta ao NOSSO banco o que esse cenário significou historicamente e devolve
# um veredito citável + score transparente. Regra da casa: ocorrências MEDIDAS,
# nunca promessa; amostra pequena é dita como amostra pequena.
_CONFIRM_CACHE = {}                 # (ativo_catalogo, tf, padrao) -> {"stats", "ts"}
_CONFIRM_TTL_S = 24 * 3600          # estatística de padrão muda devagar: 1x/dia basta
_CONFIRM_TF_PERIODO = {"5m": "6 meses", "15m": "6 meses", "30m": "6 meses",
                       "1h": "1 ano", "4h": "2 anos", "1d": "2 anos"}


def _confirm_stats_padrao(ativo_catalogo: str, tf: str, padrao: str):
    """Estatística histórica do padrão neste ativo/TF — computada 1x/dia por
    combo (cache) reusando a MESMA engine do OffMind (analisar_padrao, alvo/stop
    por ATR). Devolve {ocorrencias, acerto_5v, acerto_10v} ou None (ex.: 1m não
    tem loader — sem estatística é sem estatística, não se inventa)."""
    if tf not in _CONFIRM_TF_PERIODO or padrao not in PADROES_OFFMIND:
        return None
    chave = (ativo_catalogo, tf, padrao)
    ag = _time_mt5.time()
    hit = _CONFIRM_CACHE.get(chave)
    if hit and (ag - hit["ts"]) < _CONFIRM_TTL_S:
        return hit["stats"]
    try:
        df = baixar_dados(ativo_catalogo, _CONFIRM_TF_PERIODO[tf], tf)
        if df is None or len(df) < 60:
            return None
        r = analisar_padrao(df, PADROES_OFFMIND[padrao]["fn"], [5, 10])
        hz = {h["horizonte"]: h for h in r.get("por_horizonte", [])}
        stats = {"ocorrencias": int(r.get("total_ocorrencias") or 0),
                 "acerto_5v": (hz.get(5) or {}).get("taxa_acerto"),
                 "acerto_10v": (hz.get(10) or {}).get("taxa_acerto"),
                 "medidas_5v": (hz.get(5) or {}).get("ocorrencias_medidas") or 0}
        _CONFIRM_CACHE[chave] = {"stats": stats, "ts": ag}
        return stats
    except Exception as _e:
        print(f"[confirmacao] stats {chave}: {_e}")
        return None


def _confirmacao_contextual(det: dict, simbolo: str):
    """Junta os dois lados: o cenário que o bot está vendo AGORA + o que o banco
    mediu sobre ele. Score 0-100 transparente e explicado no próprio veredito:
    base 50 · alinhamento padrão×regime ±20 · acerto histórico ±18 · estratégia
    mapeada com PF>1 no ativo ±8 · amostra <20 trava o teto em 65."""
    om = det.get("offmind") or {}
    padroes = om.get("padroes") or []
    regime = det.get("regime") or {}
    if not padroes:
        return None                          # sem padrão formando, nada a confirmar
    p = padroes[0]                           # o padrão mais rápido em formação
    ativo_cat = _MT5_PARA_CATALOGO.get((simbolo or "").upper().replace("/", ""))
    estado = str(regime.get("estado") or "").lower()
    dir_p = str(p.get("direcao") or "").lower()
    a_favor = None
    if estado in ("compra", "alta") or estado in ("venda", "baixa"):
        favoravel = ("alta" in dir_p or "compra" in dir_p) if estado in ("compra", "alta") \
                    else ("baixa" in dir_p or "venda" in dir_p)
        a_favor = bool(favoravel)
    stats = _confirm_stats_padrao(ativo_cat, p.get("tf"), p.get("padrao")) if ativo_cat else None
    testando = [e for e in (om.get("estrutura") or []) if e.get("testando")]
    score = 50.0
    partes = []
    if a_favor is True:
        score += 20; partes.append("padrão a favor do regime (+20)")
    elif a_favor is False:
        score -= 20; partes.append("padrão CONTRA o regime (-20)")
    if stats and stats.get("acerto_5v") is not None:
        aj = max(-18.0, min(18.0, (float(stats["acerto_5v"]) - 50.0) * 0.6))
        score += aj
        partes.append(f"acerto histórico 5v {stats['acerto_5v']:.0f}% ({aj:+.0f})")
    if testando:
        partes.append(f"testando nível de {testando[0].get('tf')}")
    amostra_pequena = bool(stats and (stats.get("medidas_5v") or 0) < 20)
    if amostra_pequena:
        score = min(score, 65.0)
        partes.append("amostra pequena (teto 65)")
    score = int(round(max(0.0, min(100.0, score))))
    if stats:
        veredito = (f"{p.get('nome') or p.get('padrao')} no {p.get('tf')}: medido "
                    f"{stats.get('medidas_5v', 0)}x neste ativo/TF, "
                    f"{(stats.get('acerto_5v') or 0):.0f}% confirmou em 5 velas"
                    + (" — amostra pequena" if amostra_pequena else ""))
    else:
        veredito = (f"{p.get('nome') or p.get('padrao')} no {p.get('tf')}: sem estatística "
                    f"histórica disponível pra este ativo/TF — leitura só estrutural")
    return {"score": score, "veredito": veredito, "fatores": partes,
            "contexto": {"padrao": p.get("padrao"), "tf": p.get("tf"),
                         "direcao": p.get("direcao"), "regime": regime.get("estado"),
                         "testando_nivel": bool(testando)}}


def _regime_das_zonas(det: dict) -> Optional[dict]:
    """Recebe o detalhe do snapshot (zonas como strings acima/dentro/abaixo/?).
    Devolve {regime, estado, virada, confianca, ...} ou None se não há âncora
    suficiente. Puro (sem I/O) — roda a cada snapshot sem custo.
    Conservador: só chama tendência com maioria clara da âncora, e só sinaliza
    virada quando há tendência estabelecida E os rápidos viraram contra ela."""
    if not isinstance(det, dict):
        return None
    def _z(k):
        v = det.get(k)
        return v.strip().lower() if isinstance(v, str) else None
    anc = {k: _z(k) for k in _BT_ZONAS_ANCORA}
    validos = [v for v in anc.values() if v in ("acima", "dentro", "abaixo")]
    if len(validos) < 2:
        return None  # âncora não pronta (TF sem histórico) → sem regime
    acima  = sum(1 for v in anc.values() if v == "acima")
    abaixo = sum(1 for v in anc.values() if v == "abaixo")
    n = len(validos)
    # tendência pela âncora (maioria clara; senão lateral)
    regime = "lateral"
    if acima > abaixo and acima >= 2:
        regime = "tendencia_alta"
    elif abaixo > acima and abaixo >= 2:
        regime = "tendencia_baixa"
    # virada: os rápidos (1m/5m/15m) viraram CONTRA a tendência da âncora
    af = sum(1 for k in _BT_ZONAS_FAST if _z(k) == "acima")
    bf = sum(1 for k in _BT_ZONAS_FAST if _z(k) == "abaixo")
    virada = None
    if regime == "tendencia_alta" and bf >= 2 and af == 0:
        virada = "possivel_virada_baixa"
    elif regime == "tendencia_baixa" and af >= 2 and bf == 0:
        virada = "possivel_virada_alta"
    estado = virada or regime
    conf = int(round(100 * max(acima, abaixo) / n)) if regime != "lateral" else 0
    return {"regime": regime, "estado": estado, "virada": bool(virada),
            "confianca": conf, "acima": acima, "abaixo": abaixo, "ancoras_validas": n}


# ── OFFMIND AO VIVO: lê os candles reais que o bot mandou e enxerga o que o bot
# não vê — padrões se FORMANDO na borda (mecânica 1m/5m/15m) e níveis de
# suporte/resistência sendo testados (estrutura 30m/60m/4h). Roda sobre o dado
# da CORRETORA (sintonia: IA e bot no mesmo candle), puro (sem yfinance), só
# quando a leva de candles chega (~1x/min). Reusa os detectores do OffMind.
_BT_TF_MECANICA  = (("c1m", "1m"), ("c5m", "5m"), ("c15m", "15m"))     # gatilho entrada/saida
_BT_TF_ESTRUTURA = (("c30m", "30m"), ("c60m", "60m"), ("c4h", "4h"))   # fundo/topo

def _bt_parse_candles(s):
    """v6.72 — aceita 'o,h,l,c' (bots velhos) OU 'o,h,l,c,v' (bots v6.72+).
    Retorna DataFrame com Open/High/Low/Close (+ Volume se disponível)."""
    if not isinstance(s, str) or not s.strip():
        return None
    linhas4, linhas5 = [], []
    for parte in s.split(";"):
        vs = parte.split(",")
        try:
            if len(vs) == 5:
                linhas5.append([float(x) for x in vs])
            elif len(vs) == 4:
                linhas4.append([float(x) for x in vs])
        except Exception:
            continue
    if linhas5 and len(linhas5) >= 2:
        return pd.DataFrame(linhas5, columns=["Open", "High", "Low", "Close", "Volume"])
    if linhas4 and len(linhas4) >= 2:
        return pd.DataFrame(linhas4, columns=["Open", "High", "Low", "Close"])
    return None

def _bt_niveis_sr(df, tol_frac=0.0015, min_toques=2, max_niveis=3):
    """Níveis horizontais (suporte pelos mínimos, resistência pelos máximos)
    tocados >= min_toques na janela; marca se o preço atual está TESTANDO um.
    Clusterização 1D simples por tolerância relativa ao preço."""
    if df is None or len(df) < 4:
        return []
    preco = float(df["Close"].iloc[-1])
    tol = max(preco * tol_frac, 1e-9)
    def _cluster(vals):
        vals = sorted(float(v) for v in vals)
        cl = []
        for v in vals:
            if cl and abs(v - cl[-1]["soma"] / cl[-1]["n"]) <= tol:
                cl[-1]["soma"] += v; cl[-1]["n"] += 1
            else:
                cl.append({"soma": v, "n": 1})
        return [{"nivel": round(c["soma"] / c["n"], 5), "toques": c["n"]}
                for c in cl if c["n"] >= min_toques]
    out = []
    for s in _cluster(df["Low"].tolist()):
        out.append({"tipo": "suporte", "nivel": s["nivel"], "toques": s["toques"],
                    "testando": abs(preco - s["nivel"]) <= tol})
    for r in _cluster(df["High"].tolist()):
        out.append({"tipo": "resistencia", "nivel": r["nivel"], "toques": r["toques"],
                    "testando": abs(preco - r["nivel"]) <= tol})
    # prioriza os que estão sendo testados agora, depois por nº de toques
    out.sort(key=lambda x: (not x["testando"], -x["toques"]))
    return out[:max_niveis]

def _offmind_ao_vivo(det: dict) -> Optional[dict]:
    """Roda os detectores do OffMind sobre as janelas de candle do bot.
    Devolve {padroes, estrutura} ou None se não há candles. 'padroes' = padrão
    se formando na ÚLTIMA vela dos TFs de mecânica; 'estrutura' = níveis S/R
    testados nos TFs de estrutura. Honesto: reporta o que ESTÁ se formando —
    a estatística histórica é anexada depois (não prevê o futuro aqui)."""
    if not isinstance(det, dict):
        return None
    padroes = []
    for chave, tf in _BT_TF_MECANICA:
        df = _bt_parse_candles(det.get(chave))
        if df is None or len(df) < 4:
            continue
        ult = len(df) - 1
        for pk, meta in PADROES_OFFMIND.items():
            try:
                ocorr = meta["fn"](df)
            except Exception:
                continue
            # padrão fechando na ÚLTIMA vela = formando agora
            if any(idx == ult for (idx, _dir) in ocorr):
                direc = next(d for (i, d) in ocorr if i == ult)
                padroes.append({"tf": tf, "padrao": pk, "nome": meta["nome"], "direcao": direc})
    estrutura = []
    for chave, tf in _BT_TF_ESTRUTURA:
        df = _bt_parse_candles(det.get(chave))
        niveis = _bt_niveis_sr(df)
        for nv in niveis:
            estrutura.append({"tf": tf, **nv})
    if not padroes and not estrutura:
        return None
    testando = [e for e in estrutura if e.get("testando")]
    return {"padroes": padroes, "estrutura": estrutura,
            "resumo": {"padroes_formando": len(padroes),
                       "testando_nivel": len(testando)}}


# ── IA GERENCIADORA (o maestro): junta regime + padrão + estrutura e traduz numa
# LEITURA acionável, propondo entre as estratégias que o usuário JÁ APROVOU.
# Read-only: é uma leitura pro copiloto/monitor — NÃO comanda o bot (o canal
# nuvem→EA continua fora de escopo, por segurança). Dispara por EVENTO (a maioria
# dos snapshots não gera leitura) e tem cooldown — controle de custo e de ruído.
# Determinística e auditável; a IA em linguagem natural pode narrar isto depois.
def _gatilho_leitura(regime: Optional[dict], offmind: Optional[dict]) -> Optional[dict]:
    """Decide se o momento merece leitura. Conservador de propósito."""
    if not offmind:
        if regime and regime.get("virada"):
            return {"tipo": "virada", "motivo": f"Regime sinalizou {regime.get('estado')}"}
        return None
    padroes = offmind.get("padroes") or []
    testando = [e for e in (offmind.get("estrutura") or []) if e.get("testando")]
    if padroes and testando:
        return {"tipo": "reversao_em_nivel",
                "motivo": "Padrão formando com o preço testando um nível de estrutura"}
    if padroes and regime and regime.get("virada"):
        return {"tipo": "virada_confirmada",
                "motivo": "Padrão formando junto de uma virada de regime"}
    if regime and regime.get("virada"):
        return {"tipo": "virada", "motivo": f"Regime {regime.get('estado')}"}
    return None

def _mapear_estrategia(gatilho: dict, offmind: Optional[dict]) -> list:
    """Mapeia a situação ao vivo → estratégia(s) PRÉ-APROVADAS que casam.
    Nunca inventa gatilho: aponta entre as estratégias da galeria (ESTRATEGIAS_PRONTAS)."""
    tipo = gatilho.get("tipo")
    if tipo == "reversao_em_nivel":
        ids = ["topo_fundo_duplo", "sr_dia_anterior", "bollinger_reversao"]
    elif tipo in ("virada_confirmada", "virada"):
        ids = ["engolfo_tendencia", "rsi_reversao"]
    else:
        ids = []
    nome = {e["id"]: e["nome"] for e in ESTRATEGIAS_PRONTAS}
    return [{"id": i, "nome": nome.get(i, i)} for i in ids if i in nome]

def _leitura_ao_vivo(gat: dict, regime: Optional[dict], offmind: Optional[dict],
                     snap) -> dict:
    """Leitura estruturada do gerente: o que está se formando + estratégia
    aprovada que casa + contexto. Regra pura (custo zero, auditável)."""
    padroes = (offmind or {}).get("padroes") or []
    testando = [e for e in ((offmind or {}).get("estrutura") or []) if e.get("testando")]
    ests = _mapear_estrategia(gat, offmind)
    simbolo = getattr(snap, "simbolo", "") or ""
    reg = (regime or {}).get("estado", "?")
    partes = []
    if padroes:
        p = padroes[0]
        partes.append(f"{p['nome']} formando no {p['tf']} (direção {p['direcao']})")
    if testando:
        t = testando[0]
        partes.append(f"preço testando {t['tipo']} em {t['nivel']} no {t['tf']} ({t['toques']} toques)")
    partes.append(f"regime {reg}")
    contexto = "; ".join(partes)
    nomes = ", ".join(e["nome"] for e in ests)
    texto = (f"{simbolo}: {contexto}. "
             + (f"Setup compatível com estratégia(s) que você aprovou: {nomes}. " if ests else "")
             + "Leitura ao vivo — histórico medido, não promessa; a decisão é sua e do bot.")
    return {"gatilho": gat, "simbolo": simbolo, "contexto": contexto,
            "estrategias_sugeridas": ests, "texto": texto}



# ════════════════════════════════════════════════════════════════════════════
#  v7.21 — PROTETOR DE POSICAO
#  O complemento do detector: o detector so nasce ENTRADA e para quando ha
#  posicao ("ja tem posicao" no _check_pode_operar); o protetor SO age quando
#  ha posicao. Deterministico, zero IA, usa o canal de comando v6.73 (o EA
#  ja executa close_all e mover_sl sem reenvio). Regras e freios: ver a nota
#  da v7.21 no API_VERSAO. Toggle: config_operacional.protecao (default ON).
# ════════════════════════════════════════════════════════════════════════════

_PROT_STATE = {}   # bot_id -> {"barra_acao": bucket_m5 da ultima acao}


def _prot_ema(vals, p=20):
    """EMA autocontida (seed = SMA do warmup). Retorna lista alinhada a vals
    ou None se dado insuficiente (< p//2 amostras = sem estimativa honesta)."""
    try:
        vs = [float(v) for v in (vals or [])]
        if len(vs) < max(4, p // 2):
            return None
        k = 2.0 / (p + 1.0)
        seed_n = min(p, len(vs))
        ema = sum(vs[:seed_n]) / seed_n
        out = []
        for i, v in enumerate(vs):
            if i == 0:
                ema = v if seed_n == 1 else ema
            ema = v * k + ema * (1 - k)
            out.append(ema)
        return out
    except Exception:
        return None


def _prot_atr(cs, n=14):
    """ATR simples sobre candles fechados (dicts o/h/l/c). None sem dado."""
    try:
        fechados = (cs or [])[:-1]
        if len(fechados) < 5:
            return None
        trs = []
        for i in range(1, len(fechados)):
            h, l = float(fechados[i]["h"]), float(fechados[i]["l"])
            pc = float(fechados[i - 1]["c"])
            trs.append(max(h - l, abs(h - pc), abs(l - pc)))
        janela = trs[-n:] if len(trs) >= n else trs
        atr = sum(janela) / len(janela)
        return atr if atr > 0 else None
    except Exception:
        return None


def _prot_pin_contra(c, lado_pos):
    """Pin bar CONTRA a posicao na barra dada (dict o/h/l/c).
    long -> estrela cadente/pin de baixa (pavio superior dominante);
    short -> martelo/pin de alta (pavio inferior dominante)."""
    try:
        o, h, l, c_ = float(c["o"]), float(c["h"]), float(c["l"]), float(c["c"])
        rng = h - l
        if rng <= 0:
            return False
        corpo = abs(c_ - o)
        if lado_pos == "long":
            pavio = h - max(o, c_)
            return pavio >= 2 * corpo and pavio >= 0.5 * rng
        else:
            pavio = min(o, c_) - l
            return pavio >= 2 * corpo and pavio >= 0.5 * rng
    except Exception:
        return False



def _prot_fib_local(cs, preco, atr):
    """LOCALIZACAO (doutrina R9c): preco a <=0.2xATR de um nivel de Fibonacci
    38.2/50/61.8 do swing recente dos candles fechados. Nome do nivel ou None."""
    try:
        f = (cs or [])[:-1]
        if len(f) < 10 or preco is None:
            return None
        hi = max(float(c["h"]) for c in f)
        lo = min(float(c["l"]) for c in f)
        rng = hi - lo
        if rng <= 0:
            return None
        tol = 0.2 * (atr if atr else rng * 0.1)
        for nome, k in (("38.2", 0.382), ("50", 0.5), ("61.8", 0.618)):
            for nivel in (hi - rng * k, lo + rng * k):
                if abs(float(preco) - nivel) <= tol:
                    return nome
        return None
    except Exception:
        return None


def _prot_vol_alterado(f1):
    """VOLUME (doutrina R9b): media das 6 ultimas M1 fechadas >= 1.4x a media
    das anteriores. True/False, ou None sem dado de volume utilizavel."""
    try:
        vols = [float(c.get("v") or 0) for c in (f1 or [])]
        if len(vols) < 9:
            return None
        jan, base = vols[-6:], vols[:-6]
        if sum(base) <= 0 or sum(jan) <= 0:
            return None
        return (sum(jan) / len(jan)) >= 1.4 * (sum(base) / len(base))
    except Exception:
        return None


def _prot_reversao_identificada(det, lado_pos, preco, cs5, cs_op):
    """R9 da doutrina (27/jul): janela de 6 barras de M1 confirmando pro M5,
    SEM 15m; identificar nao e esperar 6 minutos — retorna True assim que os
    TRES confirmadores batem contra a posicao. (True/False, quadro legivel)."""
    try:
        cs1 = _parse_candles_para_lista(det.get("c1m"))
        f1 = (cs1 or [])[:-1]
        if len(f1) < 7:
            return False, ""
        jan = f1[-6:]
        # (a) ESTRUTURA: pin no M5 fechado OU cluster de M1 contra
        estrutura, det_est = False, ""
        try:
            if cs5 and len(cs5) >= 2 and _prot_pin_contra(cs5[-2], lado_pos):
                estrutura, det_est = True, "pin M5"
        except Exception:
            pass
        if not estrutura:
            contra = 0
            for i in range(1, len(jan)):
                c0, c1 = float(jan[i - 1]["c"]), float(jan[i]["c"])
                if (lado_pos == "long" and c1 < c0) or (lado_pos == "short" and c1 > c0):
                    contra += 1
            if contra >= 4:
                estrutura, det_est = True, f"cluster {contra}/5 M1 contra"
        if not estrutura:
            return False, ""
        # (b) VOLUME alterado na janela
        if _prot_vol_alterado(f1) is not True:
            return False, ""
        # (c) LOCALIZACAO em Fibonacci do swing do M5
        atr5 = _prot_atr(cs5) or _prot_atr(cs_op)
        loc = _prot_fib_local(cs5, preco, atr5)
        if loc is None:
            return False, ""
        return True, f"{det_est} + volume alterado + fib {loc}"
    except Exception:
        return False, ""


def _prot_sl_ja_enviado(sb, bot_id):
    """Anti-afrouxo cross-restart: mapa ticket -> ultimo SL que o protetor (ou
    qualquer origem) ja mandou via mover_sl pra este bot. 1 query por ACAO
    (nao por snapshot). Best-effort: erro = mapa vazio (os guards de
    breakeven-ou-melhor seguram o pior caso)."""
    mapa = {}
    try:
        r = (sb.table("mt5_comandos").select("params,tipo,criado_em")
             .eq("bot_id", bot_id).eq("tipo", "mover_sl")
             .order("criado_em", desc=True).limit(30).execute())
        for ln in (r.data or []):
            p = ln.get("params") or {}
            t = p.get("ticket")
            if t is None or t in mapa:
                continue   # desc: o primeiro visto e o mais recente
            try:
                mapa[t] = float(p.get("sl"))
            except Exception:
                pass
    except Exception:
        pass
    return mapa


def _prot_cmd(sb, bot, tipo, params, motivo):
    """Cria o comando no canal v6.73 (insert direto, padrao do detector
    automatico). Respeita bot online e o teto diario. Retorna True se criou.
    c27r2: canal de GESTAO apenas — abertura aqui e recusada por construcao."""
    if tipo in _R01_ABERTURAS:            # defesa em profundidade (R-CICLO-01)
        try: print(f"[protetor] tipo de abertura '{tipo}' recusado — canal de gestao")
        except Exception: pass
        return False
    try:
        if not _mt5_bot_online(bot):
            return False
        if _mt5_contar_comandos_dia(sb, bot.get("id")) >= MAX_COMANDOS_DIA_POR_BOT:
            print(f"[protetor] {bot.get('bot_nome')}: teto diario de comandos atingido — {motivo} NAO enviado")
            return False
        pr = dict(params or {})
        pr["motivo"] = str(motivo)[:140]
        linha = {"bot_token": bot.get("bot_token"), "user_id": bot.get("user_id"),
                 "bot_id": bot.get("id"), "tipo": tipo, "params": pr,
                 "status": "pendente", "origem": "auto_detector"}
        sb.table("mt5_comandos").insert(linha).execute()
        print(f"[protetor] {bot.get('bot_nome')}: {tipo} -> {motivo}")
        return True
    except Exception as _e:
        try:
            import sys as _sys
            print(f"[protetor cmd] {_e}", file=_sys.stderr)
        except Exception:
            pass
        return False


def _protetor_posicao(sb, bot, snap, det):
    """v7.21 — roda a cada snapshot, mas SO faz algo com posicao aberta e
    protecao ligada. Prioridade: R2 saida estrutural M5 (close_all) ->
    R3 sinal de reversao (aperta SL) -> R1 breakeven (SL pra entrada)."""
    import time as _t
    try:
        pos = int(snap.posicoes_abertas or 0)
    except Exception:
        pos = 0
    try:
        lucro = float(snap.lucro_flutuante) if snap.lucro_flutuante is not None else None
    except Exception:
        lucro = None
    # posicoes_abertas pode chegar 0 com posicao viva (parser, caso v6.91) —
    # flutuante nao-zero tambem conta como "ha posicao"
    if pos <= 0 and not (lucro is not None and abs(lucro) > 1e-9):
        return
    cfg = (bot or {}).get("config_operacional") or {}
    # v7.33 — o gate de protecao DESCEU: o GUARDIAO DE ADERENCIA roda mesmo com
    # protecao=false (protecao desliga a GESTAO — catraca/breakeven, que no BTC
    # custa spread —, nao a legitimidade da ENTRADA). Toggle proprio: guardiao.
    guardiao_on = cfg.get("guardiao") is not False
    protecao_on = cfg.get("protecao") is not False
    if not guardiao_on and not protecao_on:
        return
    bot_id = bot.get("id")
    bucket = int(_t.time() // 300)   # barra de M5
    st = _PROT_STATE.setdefault(bot_id, {})
    if st.get("barra_acao") == bucket:
        return   # 1 acao por barra de M5 — freio inegociavel

    # ── dados ──
    cs5 = _parse_candles_para_lista(det.get("c5m"))
    tf_op = str(det.get("tfop") or "").lower()
    chave_op = {"1m": "c1m", "5m": "c5m", "15m": "c15m", "30m": "c30m",
                "1h": "c60m", "60m": "c60m", "4h": "c4h"}.get(tf_op, "c15m")
    cs_op = _parse_candles_para_lista(det.get(chave_op)) or cs5
    preco = None
    try:
        preco = float(det.get("preco"))
    except Exception:
        try:
            preco = float(cs5[-1]["c"]) if cs5 else None
        except Exception:
            preco = None

    # ── posicoes registradas (entrada + ticket) da BabyMachine ──
    abertas = []
    try:
        r = (sb.table("babymachine_operacoes").select("id,decisao,fonte,created_at")
             .eq("bot_id", bot_id).eq("status", "aberta").limit(6).execute())
        for ln in (r.data or []):
            d = ln.get("decisao") or {}
            lado = str(d.get("direcao") or d.get("lado") or "").lower()
            lado = "long" if lado in ("long", "buy", "compra") else ("short" if lado in ("short", "sell", "venda") else "")
            ent = None
            try:
                ent = float(d.get("entrada"))
            except Exception:
                pass
            # v7.33 — idade da linha (pro Guardiao julgar so entradas FRESCAS)
            idade_s = None
            try:
                from datetime import datetime, timezone
                _ca = str(ln.get("created_at") or "")
                if _ca:
                    _dt = datetime.fromisoformat(_ca.replace("Z", "+00:00"))
                    idade_s = (datetime.now(timezone.utc) - _dt).total_seconds()
            except Exception:
                idade_s = None
            _slr = None
            try:
                _slr = float(d.get("sl"))
            except Exception:
                _slr = None
            abertas.append({"lado": lado, "entrada": ent, "ticket": d.get("ticket"),
                            "sl": _slr, "id_bm": ln.get("id"),
                            "fonte": str(ln.get("fonte") or ""), "idade_s": idade_s})
    except Exception:
        pass
    lados = {a["lado"] for a in abertas if a["lado"]}
    lado_pos = lados.pop() if len(lados) == 1 else None

    # v7.22 — fechamento da ultima M5 fechada + lucro do SIMBOLO em pontos
    # (o flutuante da conta mistura outros simbolos e abriu o guard indevidamente
    # nas 05:31:49 de 27/jul)
    fech5 = None
    try:
        if cs5 and len(cs5) >= 2:
            fech5 = float(cs5[-2]["c"])
    except Exception:
        fech5 = None
    ref = fech5 if fech5 is not None else preco
    lucro_sym = None
    try:
        _pts = [((ref - a["entrada"]) if a["lado"] == "long" else (a["entrada"] - ref))
                for a in abertas if a["entrada"] is not None and a["lado"] and ref is not None]
        if _pts:
            lucro_sym = sum(_pts)
    except Exception:
        lucro_sym = None
    if lucro_sym is None:
        lucro_sym = lucro   # fallback: sem posicoes registradas, usa o flutuante

    # ════ GUARDIAO DE ADERENCIA (v7.33 — ordem do dono 05/ago, apos o dia dos
    # tres episodios: 11 entradas nativas em lateral no BTC que o proprio cerebro
    # nomeou, giro cego de 16s comprando dentro de cascata de baixa confirmada,
    # e saida atrasada devolvendo 20 pts que o M1/M5 tinham anunciado. A frase:
    # ELIMINE DE UMA VEZ A INTERFERENCIA DO GATILHO NATIVO. O backend nao impede
    # a ordem nativa de NASCER — mas a mata em segundos: posicao FRESCA (<10min)
    # aberta pelo EA compilado (fonte estrategia_compilada) e julgada contra a
    # leitura ATUAL do cerebro; entrada ilegitima = close_all MESMO NEGATIVA
    # (perda de segundos e menor que stop de 60 pts depois). Criterios:
    #   (a) LATERAL — range detector diz "dentro" = entrada em lateralizacao;
    #   (b) CASCATA CONTRA — cascata de reversao confirmando contra o lado;
    #   (c) CONTRA SEM REVERSAO — alinhamento contra o lado E o classificador
    #       do Ciclo NAO diz REVERSAO_EM_CURSO na direcao da posicao (= era
    #       pullback/indefinido; comprar faca caindo sem confirmacao).
    # Entradas da PLATAFORMA (fonte detector_*) passaram no portao — imunes.
    # Carimbo em agente_eventos tipo bot_guardiao_aderencia. Toggle
    # config_operacional.guardiao (default LIGADO). ════
    try:
        if guardiao_on and abertas and preco is not None:
            _frescas = [a for a in abertas
                        if (a.get("idade_s") is not None and a["idade_s"] <= 600
                            and (not a.get("fonte") or "compilada" in str(a.get("fonte"))))]
            _lados_f = {a["lado"] for a in _frescas if a["lado"]}
            _lado_f = _lados_f.pop() if len(_lados_f) == 1 else None
            if _lado_f:
                _dir_pos = "alta" if _lado_f == "long" else "baixa"
                _dir_contra = "baixa" if _lado_f == "long" else "alta"
                _motivo_g = None
                _pac_g = None
                try:
                    _pac_g = _scanner_pacote(det)
                except Exception:
                    _pac_g = None
                # (a) LATERAL
                try:
                    _atr_g = _prot_atr(cs_op) or _prot_atr(cs5)
                    _rng = _detectar_range_lateral(cs_op, _atr_g, preco)
                    if _rng and str(_rng.get("estado") or "") == "dentro":
                        _motivo_g = ("entrada nativa DENTRO de lateralizacao de "
                                     + str(_rng.get("altura_pts") or "?") + " pts — dentro do range nao ha trade")
                except Exception:
                    pass
                # (b) CASCATA CONTRA
                if not _motivo_g:
                    try:
                        _casc = (_pac_g or {}).get("cascata_reversao") or {}
                        if (str(_casc.get("direcao") or "").lower() == _dir_contra
                                and "confirm" in str(_casc.get("estado") or "").lower()):
                            _motivo_g = ("entrada nativa CONTRA cascata de reversao "
                                         + str(_casc.get("estado")) + " (detectada no "
                                         + str(_casc.get("detectada_no")) + ")")
                    except Exception:
                        pass
                # (c) CONTRA A TENDENCIA SEM REVERSAO CONFIRMADA
                # v7.37b — ISENCAO DE FASE (1o mandato da fase, DEFENSIVO — achado
                # pelo smoke: em RESPIRO de tendencia, o alinhamento de janela
                # curta le o pullback como direcao contraria e o criterio (c)
                # condenava entrada LEGITIMA de retomada; a fase le a cena certa):
                # RESPIRO/RETOMADA ou IMPULSO na direcao da posicao = pullback
                # de continuacao, entrada legitima — (c) nao condena. Mandato
                # defensivo apenas: impede fechamento indevido, nao veta entrada.
                _fz_g = str(((_pac_g or {}).get("fase") or {}).get("fase") or "")
                _fase_ok = (_fz_g in ("RESPIRO", "RETOMADA")
                            or _fz_g == ("IMPULSO_ALTA" if _dir_pos == "alta" else "IMPULSO_BAIXA"))
                if not _motivo_g and not _fase_ok:
                    try:
                        _ali = (_pac_g or {}).get("alinhamento") or {}
                        if str(_ali.get("lado") or "").lower() == _dir_contra:
                            _cic = _ciclo_reversao_pullback(cs_op, scanner=_pac_g, alvo=_dir_pos)
                            _ver = (_cic or {}).get("veredicto")
                            if _ver != "REVERSAO_EM_CURSO":
                                _motivo_g = ("entrada nativa contra o alinhamento ("
                                             + str(_ali.get("resumo") or _dir_contra)[:60]
                                             + ") sem reversao confirmada — ciclo "
                                             + str(_ver or "sem dado"))
                    except Exception:
                        pass
                # (d) v7.39 — VETO DE FASE COM MANDATO (a colheita do Professor,
                # 05/ago: XAU M30 Cruzamento re-simulado nos 6 meses de CSV real
                # com esta politica: PF 1.44 -> 1.52, mesmo liquido com 63 trades
                # a menos = APROVADO; BTC M30 0.95 -> 0.96 = reprovado, nao liga.
                # Por isso o mandato e POR CELULA: so age quando o dono gravou
                # veto_fase=true no config_operacional do bot — hoje, apenas a
                # celula aprovada. A politica identica a testada:
                #   - fase LATERAL -> entrada nativa fora de historia = condena;
                #   - entrada CONTRA IMPULSO oposto -> condena (a fase REVERSAO
                #     na direcao da entrada e outra fase, entao a excecao do
                #     Professor esta embutida na propria gramatica).
                if not _motivo_g and bool(cfg.get("veto_fase")):
                    if _fz_g == "LATERAL":
                        _motivo_g = ("VETO DE FASE (mandato medido pelo Professor): "
                                     "entrada nativa em fase LATERAL — fora de historia direcional")
                    elif _fz_g == ("IMPULSO_BAIXA" if _lado_f == "long" else "IMPULSO_ALTA"):
                        _motivo_g = ("VETO DE FASE (mandato medido pelo Professor): "
                                     "entrada nativa CONTRA " + _fz_g + " sem reversao confirmada")
                if _motivo_g:
                    if _prot_cmd(sb, bot, "close_all", {},
                                 "GUARDIAO DE ADERENCIA: " + _motivo_g):
                        st["barra_acao"] = bucket
                        try:
                            sb.table("agente_eventos").insert({
                                "user_id": bot.get("user_id"),
                                "tipo": "bot_guardiao_aderencia", "regra": None,
                                "detalhe_json": {"bot_nome": bot.get("nome") or "",
                                                 "lado": _lado_f, "motivo": _motivo_g,
                                                 "preco": preco},
                            }).execute()
                        except Exception:
                            pass
                    return
    except Exception:
        pass

    # v7.33 — daqui pra baixo e GESTAO: respeita o toggle protecao original
    if not protecao_on:
        return

    # ── R0b (v7.35 — cobranca do dono 05/ago, print do 54 nascendo com stop
    # geometrico ~60 pts abaixo, ate embaixo do topo rompido: o EA calcula o
    # SL inicial por multiplo de ATR, cego a estrutura — e o ATR inflado num
    # dia de 4 por cento fabrica risco maximo. O CEREBRO conhece a estrutura E
    # conhece o SL registrado da entrada (v6.89 grava decisao.sl): posicao
    # FRESCA (<=15 min) legitima ganha STOP ESTRUTURAL — o fundo das ultimas
    # 8 fechadas (long) / topo (short) com folga de 0.3xATR — via mover_sl,
    # SO SE APERTA o stop registrado (catraca: nunca afrouxa, nunca cola a
    # menos de 0.5xATR do preco). Uma vez por posicao (_PROT_STATE). ──
    try:
        if abertas and cs_op and len(cs_op) >= 10 and preco is not None:
            _atr0 = _prot_atr(cs_op) or _prot_atr(cs5) or 0
            if _atr0 > 0:
                _f0 = cs_op[:-1][-8:]
                movidos0 = 0
                for a in abertas:
                    if movidos0 >= 3:
                        break
                    if not a.get("lado") or a.get("idade_s") is None or a["idade_s"] > 900:
                        continue
                    if not a.get("ticket"):
                        continue
                    _ja = st.setdefault("sl_estrutural", set())
                    if a.get("id_bm") in _ja:
                        continue
                    if a["lado"] == "long":
                        nivel = min(float(b["l"]) for b in _f0) - 0.3 * _atr0
                        cola = nivel > preco - 0.5 * _atr0
                    else:
                        nivel = max(float(b["h"]) for b in _f0) + 0.3 * _atr0
                        cola = nivel < preco + 0.5 * _atr0
                    # v7.36 — APERTA COM OU SEM SL REGISTRADO: (a) sl gravado ->
                    # compara direto (nunca afrouxa); (b) sl AUSENTE (gap do OTT:
                    # o evento aberto nao carrega SL, o caso real dos 54/55) ->
                    # usa a ENTRADA gravada como referencia e SO move se o nivel
                    # estrutural for mais justo que o PISO DE FABRICA do EA
                    # (1.5xATR do R6): distancia entrada->nivel < 1.2xATR garante
                    # aperto matematico sem conhecer o stop. Sem sl E sem entrada
                    # = pula com honestidade.
                    aperta = False
                    _sl_ref = a.get("sl")
                    if _sl_ref is None and a.get("entrada") is not None:
                        # v7.37 — sl ausente no registro (gap do OTT): ESTIMA do
                        # stop do ENVIO persistido (sl_envio_pts, verdade do
                        # /mt5/enviar): sl_estimado = entrada -/+ pontos. Vale
                        # pro XAU largo (60 -> aperta) E pro BTC apertado
                        # (3000? nivel mais fundo que o stop -> nao mexe).
                        try:
                            _pts_env = float(cfg.get("sl_envio_pts"))
                            _sl_ref = (float(a["entrada"]) - _pts_env) if a["lado"] == "long" else (float(a["entrada"]) + _pts_env)
                        except Exception:
                            _sl_ref = None
                    if _sl_ref is not None:
                        aperta = (nivel > float(_sl_ref) + 1e-9) if a["lado"] == "long" else (nivel < float(_sl_ref) - 1e-9)
                    elif a.get("entrada") is not None:
                        _dist = abs(float(a["entrada"]) - nivel)
                        aperta = _dist < 1.2 * _atr0
                    if aperta and not cola:
                        if _prot_cmd(sb, bot, "mover_sl",
                                     {"ticket": a["ticket"], "sl": round(nivel, 2)},
                                     f"stop ESTRUTURAL de entrada: {round(nivel,2)} (fundo/topo das 8 fechadas +-0.3xATR) aperta o geometrico {a['sl']}"):
                            _ja.add(a.get("id_bm"))
                            movidos0 += 1
                if movidos0:
                    st["barra_acao"] = bucket
                    return
    except Exception:
        pass

    # ── R2c (v7.33 — exigencia do dono: reversao confirmada no 5m = CORTA,
    # sem esperar 15/30min; e barra gigante que ATRAVESSA o canal e fecha do
    # lado oposto tambem corta — o R2 original so pegava a transicao suave
    # de-fora-pra-dentro). Com lucro: cascata confirmando contra OU M5 fechado
    # ALEM do canal oposto -> close_all. Negativa: exige as DUAS (cascata
    # confirmada E fechamento alem do canal) — reversao identificada corta
    # mesmo no vermelho, mas ruido isolado nao. ──
    try:
        if lado_pos and cs5 and len(cs5) >= 8:
            _f5 = cs5[:-1]
            _eh5 = _prot_ema([c["h"] for c in _f5], 20)
            _el5 = _prot_ema([c["l"] for c in _f5], 20)
            if _eh5 and _el5:
                _cu = _f5[-1]
                _alem = ((lado_pos == "long" and float(_cu["c"]) < _el5[-1])
                         or (lado_pos == "short" and float(_cu["c"]) > _eh5[-1]))
                _dir_c = "baixa" if lado_pos == "long" else "alta"
                _casc2 = {}
                try:
                    _casc2 = ((_scanner_pacote(det) or {}).get("cascata_reversao") or {})
                except Exception:
                    _casc2 = {}
                _casc_contra = (str(_casc2.get("direcao") or "").lower() == _dir_c
                                and "confirm" in str(_casc2.get("estado") or "").lower())
                _casc_forte = (str(_casc2.get("direcao") or "").lower() == _dir_c
                               and "confirmada" in str(_casc2.get("estado") or "").lower())
                _corta = False
                if lucro_sym is not None and lucro_sym > 0 and (_alem or _casc_contra):
                    _corta = True
                elif _alem and _casc_forte:
                    _corta = True   # negativa: dupla condicao
                if _corta:
                    _mot_c = ("saida pela CASCATA (R2c): M5 "
                              + ("fechou ALEM do canal contra" if _alem else "")
                              + (" + " if (_alem and _casc_contra) else "")
                              + (("cascata " + str(_casc2.get("estado"))) if _casc_contra else ""))
                    if lucro_sym is not None:
                        _mot_c += f" — lucro simbolo {lucro_sym:+.1f} pts"
                    if _prot_cmd(sb, bot, "close_all", {}, _mot_c):
                        st["barra_acao"] = bucket
                    return
    except Exception:
        pass

    # ── R9 (doutrina 27/jul): REVERSAO IDENTIFICADA -> FECHA, mesmo negativa.
    # Prioridade maxima: se o mercado provou a reversao, nao ha o que proteger.
    try:
        if lado_pos and abertas:
            _rev, _quadro = _prot_reversao_identificada(det, lado_pos, preco, cs5, cs_op)
            if _rev:
                if _prot_cmd(sb, bot, "close_all", {},
                             f"reversao identificada contra a posicao ({_quadro}) — aborto da doutrina"):
                    st["barra_acao"] = bucket
                return
    except Exception:
        pass

    # ── R2: SAIDA ESTRUTURAL M5 (fechamento de VOLTA pro canal contra) ──
    # Exige transicao real: barra anterior FORA do canal, ultima fechada DENTRO.
    # So com flutuante positivo — o protetor realiza lucro, nao corta perda
    # (a perda e territorio do stop do EA).
    try:
        if lado_pos and lucro_sym is not None and lucro_sym > 0 and cs5 and len(cs5) >= 8:
            fechados5 = cs5[:-1]
            eh = _prot_ema([c["h"] for c in fechados5], 20)
            el = _prot_ema([c["l"] for c in fechados5], 20)
            if eh and el and len(fechados5) >= 3:
                c_ult, c_ant = fechados5[-1], fechados5[-2]
                if lado_pos == "long" and float(c_ant["c"]) > eh[-2] and float(c_ult["c"]) <= eh[-1]:
                    if _prot_cmd(sb, bot, "close_all", {},
                                 f"saida estrutural M5: fechamento {float(c_ult['c']):g} de volta pro canal contra a compra (lucro simbolo {lucro_sym:+.1f} pts)"):
                        st["barra_acao"] = bucket
                    return
                if lado_pos == "short" and float(c_ant["c"]) < el[-2] and float(c_ult["c"]) >= el[-1]:
                    if _prot_cmd(sb, bot, "close_all", {},
                                 f"saida estrutural M5: fechamento {float(c_ult['c']):g} de volta pro canal contra a venda (lucro simbolo {lucro_sym:+.1f} pts)"):
                        st["barra_acao"] = bucket
                    return
    except Exception:
        pass

    if preco is None or not abertas:
        return
    atr = _prot_atr(cs_op) or _prot_atr(cs5)

    # ── R3: SINAL DE REVERSAO no TF de operacao -> aperta SL pro extremo
    #        da barra do sinal, SO alem da entrada (breakeven-ou-melhor
    #        garantido sem conhecer o SL atual) ──
    enviados = None
    acao = False
    try:
        if cs_op and len(cs_op) >= 3:
            sinal = cs_op[-2]   # ultima barra FECHADA
            movidos = 0
            for a in abertas:
                if movidos >= 3:
                    break
                if not a["lado"] or a["entrada"] is None or not a.get("ticket"):
                    continue
                if not _prot_pin_contra(sinal, a["lado"]):
                    continue
                if a["lado"] == "long":
                    alvo_sl = float(sinal["l"])
                    if alvo_sl <= a["entrada"] or preco <= alvo_sl:
                        continue
                else:
                    alvo_sl = float(sinal["h"])
                    if alvo_sl >= a["entrada"] or preco >= alvo_sl:
                        continue
                if enviados is None:
                    enviados = _prot_sl_ja_enviado(sb, bot_id)
                ja = enviados.get(a["ticket"])
                if ja is not None and ((a["lado"] == "long" and alvo_sl <= ja) or
                                       (a["lado"] == "short" and alvo_sl >= ja)):
                    continue   # nunca afrouxa o que ja foi apertado
                if _prot_cmd(sb, bot, "mover_sl", {"ticket": a["ticket"], "sl": round(alvo_sl, 5)},
                             f"reversao no {tf_op or 'TF op'}: pin bar contra — SL pro extremo da barra do sinal"):
                    enviados[a["ticket"]] = alvo_sl
                    movidos += 1
                    acao = True
        if acao:
            st["barra_acao"] = bucket
            return
    except Exception:
        pass

    # ── R1: BREAKEVEN — avanco >= 0.6 x ATR a favor -> SL na entrada ──
    try:
        if atr is None:
            return
        movidos = 0
        for a in abertas:
            if movidos >= 3:
                break
            if not a["lado"] or a["entrada"] is None or not a.get("ticket"):
                continue
            _base_be = fech5 if fech5 is not None else preco
            avanco = (_base_be - a["entrada"]) if a["lado"] == "long" else (a["entrada"] - _base_be)
            if avanco < 0.6 * atr:
                continue
            alvo_sl = a["entrada"]
            if enviados is None:
                enviados = _prot_sl_ja_enviado(sb, bot_id)
            ja = enviados.get(a["ticket"])
            if ja is not None and ((a["lado"] == "long" and alvo_sl <= ja) or
                                   (a["lado"] == "short" and alvo_sl >= ja)):
                continue   # SL ja esta na entrada ou melhor — nunca afrouxa
            if _prot_cmd(sb, bot, "mover_sl", {"ticket": a["ticket"], "sl": round(alvo_sl, 5)},
                         f"breakeven no fechamento M5: avanco {avanco:.1f} pts >= 0.6 x ATR ({0.6*atr:.1f}) — SL pra entrada"):
                enviados[a["ticket"]] = alvo_sl
                movidos += 1
                acao = True
        if acao:
            st["barra_acao"] = bucket
    except Exception:
        pass

    # ── R5 (doutrina 27/jul, degrau 2 da escada): PERSEGUICAO ESTRUTURAL —
    # depois do breakeven, o SL cola no canal EMA20 do M5 (low pra compra,
    # high pra venda) e sobe a cada vela fechada a favor. Catraca mantida:
    # so anda na direcao do lucro e nunca cruza o preco.
    try:
        if st.get("barra_acao") == bucket:
            return
        if not cs5 or len(cs5) < 8 or preco is None:
            return
        _f5 = cs5[:-1]
        _eh = _prot_ema([c["h"] for c in _f5], 20)
        _el = _prot_ema([c["l"] for c in _f5], 20)
        if not _eh or not _el:
            return
        movidos = 0
        acao2 = False
        for a in abertas:
            if movidos >= 3:
                break
            if not a["lado"] or a["entrada"] is None or not a.get("ticket"):
                continue
            if enviados is None:
                enviados = _prot_sl_ja_enviado(sb, bot_id)
            ja = enviados.get(a["ticket"])
            if ja is None:
                continue   # degrau 2 so DEPOIS do degrau 1 (breakeven feito)
            if a["lado"] == "long":
                if ja < a["entrada"]:
                    continue
                alvo_sl = float(_el[-1])
                if alvo_sl <= ja or alvo_sl >= preco:
                    continue
            else:
                if ja > a["entrada"]:
                    continue
                alvo_sl = float(_eh[-1])
                if alvo_sl >= ja or alvo_sl <= preco:
                    continue
            if _prot_cmd(sb, bot, "mover_sl", {"ticket": a["ticket"], "sl": round(alvo_sl, 5)},
                         "escada degrau 2: SL perseguindo o canal EMA do M5"):
                enviados[a["ticket"]] = alvo_sl
                movidos += 1
                acao2 = True
        if acao2:
            st["barra_acao"] = bucket
    except Exception:
        pass


@app.post("/conector/snapshot")
def conector_snapshot(snap: ConectorSnapshot):
    """Recebe snapshot read-only do conector. Atualiza ping, grava e roda o agente."""
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponível")
    bot = _bot_por_token(sb, snap.bot_token)
    if not bot:
        raise HTTPException(status_code=401, detail="bot_token inválido")
    # MULTI-BOT — guarda contra snapshot entregue no token ERRADO. O magic que o
    # EA imprime é derivado do token (determinístico). Se o snapshot chega com um
    # magic que NÃO bate com este bot, ele é de OUTRO bot do mesmo usuário (outro
    # gráfico) e foi roteado pro token errado. Ignora: NÃO atualiza ping/posições —
    # senão a trilha acende "Operar" pra um bot que nem está no gráfico ainda.
    _magic_rec = int(getattr(snap, "magic_number", 0) or 0)
    if _magic_rec and _magic_rec != _magic_do_token(bot.get("bot_token") or snap.bot_token):
        try:
            _clm_divergencia_magic(sb, bot, _magic_rec)       # C27R13: registrada, nunca silenciosa
        except Exception:
            pass
        return {"ok": True,
                "ignorado": "magic nao confere com o bot (snapshot de outro bot)",
                "sugestoes_novas": []}
    user_id = bot.get("user_id")
    agora = _dt.now(_tz.utc).isoformat()
    # ── VISÃO → REGIME: sintetiza a partir das zonas cruas (as duas juntas) ──
    det = dict(snap.detalhe or {})
    regime = _regime_das_zonas(det)
    if regime:
        det["regime"] = regime                       # cru + sintetizado no mesmo JSON
    # ── OFFMIND AO VIVO: só quando a leva de candles chega (~1x/min) ──
    if any(k in det for k, _ in _BT_TF_MECANICA) or any(k in det for k, _ in _BT_TF_ESTRUTURA):
        try:
            om = _offmind_ao_vivo(det)
            if om:
                det["offmind"] = om                  # padrões + estrutura ao vivo
        except Exception as _e:
            import sys as _sys
            print(f"[offmind vivo] {_e}", file=_sys.stderr)
    # ── CONFIRMAÇÃO CONTEXTUAL (v6.48): cenário de agora × banco histórico ──
    try:
        conf = _confirmacao_contextual(det, snap.simbolo)
        if conf:
            det["confirmacao"] = conf
    except Exception as _e:
        import sys as _sys
        print(f"[confirmacao] {_e}", file=_sys.stderr)
    # reaproveita a coluna ultima_direcao/direcao_d1 (vinha vazia) pro estado do regime
    direcao_final = (regime or {}).get("estado") or snap.direcao_d1
    # ── IA GERENCIADORA: leitura acionável por EVENTO (com cooldown) ──
    # Read-only: vira sugestão no monitor, NÃO comanda o bot.
    try:
        gat = _gatilho_leitura(regime, det.get("offmind"))
        if gat and not _agente_em_cooldown(sb, user_id, "LEITURA"):
            leitura = _leitura_ao_vivo(gat, regime, det.get("offmind"), snap)
            det["leitura"] = leitura
            _agente_emite(sb, user_id, "LEITURA", "operacao",
                          leitura["texto"], "info", leitura)
    except Exception as _e:
        import sys as _sys
        print(f"[leitura ao vivo] {_e}", file=_sys.stderr)
    try:
        # v6.53: só atualiza os campos que VIERAM no snapshot — snapshot velho
        # (bots pré-v6.37 sem "lucro=") não deve mais sobrescrever com NULL o
        # que um snapshot novo escreveu antes. Ping e posições sempre vão.
        _upd = {"ultimo_ping": agora, "posicoes_abertas": snap.posicoes_abertas}
        if snap.equity is not None:         _upd["ultimo_equity"] = snap.equity
        if snap.drawdown_atual is not None: _upd["ultimo_dd"] = snap.drawdown_atual
        if direcao_final is not None:       _upd["ultima_direcao"] = direcao_final
        if snap.padrao_ativo is not None:   _upd["ultimo_padrao"] = snap.padrao_ativo
        sb.table("conector_bots").update(_upd).eq("id", bot["id"]).execute()
        _clm_ins = sb.table("conector_snapshots").insert({
            "user_id": user_id, "bot_token": snap.bot_token,
            "conta_login": snap.conta_login, "corretora": snap.corretora,
            "simbolo": snap.simbolo, "magic_number": snap.magic_number,
            "equity": snap.equity, "balance": snap.balance,
            "margem_livre": snap.margem_livre,
            "posicoes_abertas": snap.posicoes_abertas,
            "lucro_flutuante": snap.lucro_flutuante,
            "drawdown_atual": snap.drawdown_atual,
            "direcao_d1": direcao_final, "padrao_ativo": snap.padrao_ativo,
            "detalhe_json": det,
        }).execute()
        _clm_snap_id = ((getattr(_clm_ins, "data", None) or [{}])[0]).get("id")
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Erro ao gravar snapshot: {e}")
    # C27R13 — Learning Machine dos Ciclos: registra a leitura da barra M15 (best-effort)
    try:
        _clm_ingerir(sb, bot, snap, det, _clm_snap_id)
    except Exception as _e:
        try: print(f"[clm] {_e}")
        except Exception: pass
    # C27R19 — seleção M15/M30/H1 em MODO OBSERVAR: grava a avaliação da barra e o acompanhamento
    # prospectivo. Nunca emite decisão/comando; falha aqui nunca derruba o snapshot.
    try:
        _sel_ingerir(sb, {**bot, "posicoes_abertas": snap.posicoes_abertas}, det)
        _sel_acompanhar(sb, bot, det)
    except Exception as _e:
        try: print(f"[sel] {_e}")
        except Exception: pass
    novas = _agente_bloco_f(sb, user_id, bot, snap)
    # v6.74 — DETECTOR DE OPORTUNIDADE. Roda 24/7 aqui pra funcionar mesmo com
    # cockpit fechado. Nao chama IA se bot esta em modo observar (~99% dos casos).
    try:
        _leit = _anl_ler_leitura(sb, user_id, bot.get("id"))
        if _leit:
            fatos = _analisar_bot_tecnica(
                None, _leit.get("ema_h"), _leit.get("ema_l"),
                _leit.get("preco"), _leit.get("regime"),
                _leit.get("posicoes"),
                offmind={"padroes": _leit.get("padroes"),
                         "estrutura": (det.get("offmind") or {}).get("estrutura") or []},
            ) or {}
            # complementa fatos com o que o detector precisa
            fatos["regime"] = str((_leit.get("regime") or {}).get("estado") or "").upper()
            fatos["preco"] = _leit.get("preco")
            fatos["distancia_ema_h"] = _leit.get("ema_h")
            fatos["distancia_ema_l"] = _leit.get("ema_l")
            # ultima analise cruzada da IA se houver
            ult_anl = list(_anl_hist(bot.get("id")))[-1:] or [None]
            veredito = ult_anl[0] if ult_anl and ult_anl[0] else None
            _detectar_oportunidade(
                sb, {**bot, "posicoes_abertas": snap.posicoes_abertas},
                fatos, _leit, veredito=veredito,
                snap_dict={"equity": snap.equity},
            )
    except Exception as _e:
        try: print(f"[detector] {_e}")
        except Exception: pass
    # v7.21 — PROTETOR DE POSICAO: o complemento do detector. So faz algo com
    # posicao aberta e protecao ligada; nunca quebra o snapshot.
    try:
        _protetor_posicao(sb, bot, snap, det)
    except Exception as _e:
        try:
            import sys as _sys
            print(f"[protetor] {_e}", file=_sys.stderr)
        except Exception:
            pass
    return {"ok": True, "sugestoes_novas": novas}


# ════════════════════════════════════════════════════════════════════════════
#  v6.74 — Endpoints do DETECTOR DE OPORTUNIDADE
# ════════════════════════════════════════════════════════════════════════════

class BotConfigIn(BaseModel):
    modo_operacional:   Optional[str] = None   # observar|copiloto|automatico
    modo_sensibilidade: Optional[str] = None   # conservador|moderado|agressivo
    drawdown_max_dia:   Optional[float] = None
    max_operacoes_dia:  Optional[int] = None
    estrelas_min_auto:  Optional[int] = None
    pausado:            Optional[bool] = None
    lote_padrao:        Optional[float] = None


@app.get("/monitor/bot/{bot_id}/config")
def monitor_bot_config_get(bot_id: int):
    """Retorna a config atual do bot (ou defaults conservadores se nunca setado).
    v7.07: mescla a config PERSISTIDA da linha do bot — pos-restart o cockpit
    pinta o que o usuario realmente escolheu, nao o default da memoria."""
    cfg = _bot_config_get(bot_id)
    try:
        _sbg = _sb_admin()
        if _sbg is not None:
            _rowg = (_sbg.table("conector_bots").select("config_operacional")
                     .eq("id", bot_id).limit(1).execute())
            if _rowg.data:
                _cog = _rowg.data[0].get("config_operacional") or {}
                for _k in _DETECTOR_DEFAULT_CONFIG:
                    if _k in _cog:
                        cfg[_k] = _cog[_k]
    except Exception:
        pass
    return {"config": cfg}


@app.post("/monitor/bot/{bot_id}/config")
def monitor_bot_config_set(bot_id: int, inp: BotConfigIn):
    """Atualiza config do bot. Campos nao enviados ficam como estao."""
    novo = {}
    for k, v in inp.model_dump(exclude_none=True).items():
        novo[k] = v
    # valida enums
    if "modo_operacional" in novo and novo["modo_operacional"] not in ("observar", "copiloto", "automatico"):
        raise HTTPException(status_code=400, detail="modo_operacional invalido")
    if "modo_sensibilidade" in novo and novo["modo_sensibilidade"] not in ("conservador", "moderado", "agressivo"):
        raise HTTPException(status_code=400, detail="modo_sensibilidade invalido")
    if "estrelas_min_auto" in novo and not (1 <= int(novo["estrelas_min_auto"]) <= 5):
        raise HTTPException(status_code=400, detail="estrelas_min_auto deve ser 1-5")
    if "lote_padrao" in novo and not (0.01 <= float(novo["lote_padrao"]) <= 100):
        raise HTTPException(status_code=400, detail="lote_padrao deve ser 0.01-100")
    cfg = _bot_config_set(bot_id, novo)
    # v7.02 — LIGA/DESLIGA persistente: o pausado tambem vai pro
    # config_operacional (JSONB v6.75, merge — mesmo padrao do estrategia_nome
    # v6.90). Sobrevive a restart do Railway e vale pra TODOS os workers: o
    # /conector/bots devolve a coluna pro front pintar o botao, e o gate do
    # detector le a coluna da linha do bot (verdade unica). Best-effort.
    # v7.07 — PERSISTENCIA TOTAL (pedido do dono: os parametros de atuacao sao
    # do USUARIO): TODOS os campos operacionais vao pro config_operacional
    # (JSONB v6.75, merge) — modo, sensibilidade, lote, breakers, pausado.
    # Sobrevive a restart e vale pra todos os workers (generaliza o v7.02).
    if novo:
        try:
            _sbp = _sb_admin()
            if _sbp is not None:
                _row = (_sbp.table("conector_bots").select("id,config_operacional")
                        .eq("id", bot_id).limit(1).execute())
                if _row.data:
                    _cfgp = dict(_row.data[0].get("config_operacional") or {})
                    for _k, _v in novo.items():
                        _cfgp[_k] = _v
                    _sbp.table("conector_bots").update(
                        {"config_operacional": _cfgp}).eq("id", bot_id).execute()
        except Exception:
            pass
    return {"ok": True, "config": cfg}


@app.get("/monitor/bot/{bot_id}/oportunidades")
def monitor_bot_oportunidades(bot_id: int, limite: int = 10):
    """Oportunidades detectadas recentemente pra este bot. Mais novas por ultimo."""
    hist = list(_oportunidade_hist(bot_id))
    limite = max(1, min(50, int(limite)))
    return {"oportunidades": hist[-limite:]}


class OportExecutarIn(BaseModel):
    bot_token: str


@app.post("/monitor/oportunidade/{oport_id}/executar")
def monitor_oportunidade_executar(oport_id: str, inp: OportExecutarIn):
    """Executa uma oportunidade em modo copiloto (usuario clicou Executar).
    Cria comando via /mt5/comando internamente com origem=copiloto."""
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponivel")
    bot = _bot_por_token(sb, inp.bot_token)
    if not bot:
        raise HTTPException(status_code=401, detail="bot_token invalido")
    hist = _oportunidade_hist(bot.get("id"))
    oport = next((o for o in hist if o.get("id") == oport_id), None)
    if not oport:
        raise HTTPException(status_code=404, detail="oportunidade nao encontrada")
    if oport.get("status") in ("auto_executada", "executada", "expirada"):
        raise HTTPException(status_code=409, detail=f"oportunidade ja esta {oport.get('status')}")
    config = _bot_config_get(bot.get("id"))
    # v7.07 — mesma verdade unica do detector: config persistida da linha
    # do bot sobrescreve a memoria (o lote do Executar e o do usuario).
    try:
        _co2 = bot.get("config_operacional") or {}
        for _k2 in _DETECTOR_DEFAULT_CONFIG:
            if _k2 in _co2:
                config[_k2] = _co2[_k2]
    except Exception:
        pass
    lote = float(config.get("lote_padrao") or 0.01)
    tipo = "buy" if oport["direcao"] == "long" else "sell"
    _params01 = {"lote": lote, "sl": oport["stop"], "tp": oport["alvo1"]}
    _did = oport.get("decisao_id")           # c27r2: o servidor EMITE aqui
    if not _did:
        _okE, _rE = _r01_emitir_decisao(sb, bot, tipo)
        if not _okE:
            raise HTTPException(status_code=422,
                                detail=f"abertura_recusada[{_rE}]")
        _did = _rE["id"]
    _params01["decisao_id"] = _did
    _okI, cmd = _r01_abrir_via_rpc(sb, bot, tipo, _params01, "copiloto")
    if not _okI:                          # c27r4: recusa nomeada da RPC/leitura
        raise HTTPException(status_code=422,
                            detail=f"abertura_recusada[{cmd}]")
    try:
        oport["comando_id"] = cmd.get("id")
        oport["status"] = "executada"
        import time
        st = _CIRCUIT_STATE.get(bot.get("id")) or {}
        st["ops_hoje"] = int(st.get("ops_hoje") or 0) + 1
        st["ultima_op_ts"] = time.time()
        _CIRCUIT_STATE[bot.get("id")] = st
        # v6.76 — BabyMachine registra a decisao do copiloto (non-blocking)
        try:
            _leit_bm = _anl_ler_leitura(sb, bot.get("user_id"), bot.get("id"))
            _bm_registrar_do_detector(sb, bot, oport, _leit_bm, None,
                                      cmd.get("id"), "detector_copiloto")
        except Exception as _e2:
            try: print(f"[bm copiloto] {_e2}")
            except Exception: pass
        return {"ok": True, "comando_id": cmd.get("id"), "oportunidade": oport}
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"erro ao executar: {e}")


# ════════════════════════════════════════════════════════════════════════════
#  v6.73 — CANAL DE COMANDO CLOUD→EA (Sessão 1 do loop fechado)
#
#  Estas rotas fecham o círculo que estava aberto desde o dia 1: a plataforma
#  agora pode MANDAR ordens pro EA (não só receber snapshots). A inteligência
#  que a gente construiu (BOT + IA + veredito + banco) passa a ter mão.
#
#  Fluxo de um comando:
#    1. POST /mt5/comando cria linha com status=pendente na mt5_comandos
#    2. Conector PY faz GET /mt5/comando/pendente a cada 3-5s por bot
#    3. Backend retorna o mais antigo, marca como entregue
#    4. Conector escreve arquivo bt_cmd_<magic>.txt na pasta MQL5/Files
#    5. EA (função BTLerComando injetada) lê, executa, grava bt_ok_<magic>.txt
#    6. Conector lê bt_ok e chama POST /mt5/comando/confirmar
#    7. Backend atualiza status → executado ou falhou
#
#  Circuit breakers básicos (sessão 3 refina):
#    • Bot precisa estar ONLINE (ultimo_ping < OFFLINE_APOS_SEGUNDOS)
#    • MAX_COMANDOS_DIA por bot (protege contra bug em cascata)
#    • Comandos vencidos (expira_em < now()) viram expirado via
#      _mt5_expirar_comandos() (throttle no código pra não rodar toda request)
# ════════════════════════════════════════════════════════════════════════════

MAX_COMANDOS_DIA_POR_BOT = 20  # circuit breaker inicial — sessão 3 refina
_MT5_EXPIRAR_THROTTLE = {"ultimo": 0.0}
# ── c27r2: R-CICLO-01 — AUTORIDADE DE DECISÃO DOS DOIS CICLOS ───────────────
# A ficha inline morreu (era forjável: formato ≠ autoridade). Abertura só com
# decisão EMITIDA E PERSISTIDA pelo servidor (ciclo_decisoes), consumida por
# claim atômico no último ponto antes do insert. Fonte da leitura: o último
# snapshot do próprio bot (canal read-only EA→conector→nuvem), NUNCA o corpo
# de um POST. Espelho doutrinário: bt_decisao_contrato.py v2.
_R01_ABERTURAS = ("buy", "sell")
_R01_DEC_TTL_S = 900.0            # 1 barra M15 a partir da barra FECHADA


try:                                   # c27r3 — assinador/verificador do atestado
    import bt_cv_atestado as _cvat
except Exception:                      # módulo ausente = elo inexistente = fail-closed
    _cvat = None


def _r01_ler_ciclos_servidor(sb, bot):
    """(atestado, ts_barra, falha). c27r3: a leitura que AUTORIZA abertura é o
    ATESTADO ASSINADO pelo motor/conector (det.cv_atestado do último snapshot),
    verificado com HMAC-SHA256 + segredo BT_CV_SEGREDO. cv2_dirs cru do
    snapshot DEIXOU de ser autoridade (a auditoria provou forja pela rota
    real). Sem segredo configurado, sem atestado, assinatura inválida, magic
    zero, símbolo divergente ou barra não-fechada = fail-closed nomeado."""
    from datetime import datetime as _d3, timezone as _z3
    if _cvat is None:
        return None, None, "atestado_modulo_ausente(fail_closed)"
    try:
        snaps = (sb.table("conector_snapshots")
                 .select("simbolo,magic_number,detalhe_json")
                 .eq("bot_token", bot.get("bot_token"))
                 .order("id", desc=True).limit(1).execute().data or [])
    except Exception:
        snaps = []
    if not snaps:
        return None, None, "sem_leitura_servidor(snapshot_ausente)"
    det = snaps[0].get("detalhe_json") or {}
    at = det.get("cv_atestado")
    if not isinstance(at, dict):
        return None, None, "atestado_ausente(cv2_cru_nao_e_autoridade)"
    ok, motivo = _cvat.verificar(at)           # forma + magic>0 + HMAC
    if not ok:
        return None, None, motivo
    import hashlib as _hashlib_ciclo
    token = bot.get("bot_token")
    if not isinstance(token, str) or not token or at.get("bot_token_hash") != \
            _hashlib_ciclo.sha256(token.encode("utf-8")).hexdigest():
        return None, None, "atestado_de_outro_bot(fail_closed)"
    if str(at.get("simbolo")) != str(bot.get("simbolo")):
        return None, None, "atestado_simbolo_divergente"
    _mag_snap = snaps[0].get("magic_number")
    try:
        if int(_mag_snap) <= 0 or int(_mag_snap) != int(at.get("magic")):
            return None, None, "atestado_magic_divergente_do_snapshot"
    except (TypeError, ValueError, OverflowError):
        return None, None, "snapshot_magic_invalido(fail_closed)"
    try:
        ts = _d3.fromisoformat(str(at.get("ts_barra_m15"))
                               .replace("Z", "+00:00"))
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=_z3.utc)
    except Exception:
        return None, None, "atestado_ts_barra_invalido"
    if ts.minute % 15 != 0 or ts.second != 0 or ts.microsecond != 0:
        return None, None, "barra_nao_alinhada_ao_grid_m15"
    idade = (_d3.now(_z3.utc) - ts).total_seconds()
    if idade < 0:
        return None, None, "barra_em_formacao_ou_futura"
    if idade > _R01_DEC_TTL_S:
        return None, None, f"leitura_vencida({idade:.0f}s)"
    return at, ts, None


def _r01_comando_por_uid(sb, bot_id, uid):
    """Consulta idempotente: o comando de ABERTURA já existe pra este uid?"""
    try:
        r = (sb.table("mt5_comandos").select("*")
             .eq("bot_id", bot_id).execute())
        for c in (r.data or []):
            if (c.get("tipo") in _R01_ABERTURAS and
                    (c.get("params") or {}).get("uid") == uid):
                return c
    except Exception:
        return None
    return None


def _r01_abrir_via_rpc(sb, bot, tipo, params, origem):
    """c27r4/P2 — O CAMINHO ÚNICO DE ABERTURA dos 3 produtores. Valida a
    decisão por LEITURA, então chama a RPC transacional r01_claim_e_comando
    (claim emitida→consumida + INSERT do comando na MESMA transação; falha em
    qualquer ponto desfaz tudo no banco — a compensação client-side da c27r3
    morreu: nunca mais reemitir decisão após resultado desconhecido).
    RESPOSTA PERDIDA APÓS COMMIT: exceção de transporte NÃO é 'insert falhou'
    — a recuperação consulta o estado por UID/id e responde sem duplicar:
    comando existe → devolve o existente; decisão ainda emitida (commit não
    chegou a acontecer) → um único retry; consumida sem comando → impossível
    pela RPC, erro nomeado, nada reemitido. (ok, cmd|motivo)."""
    params = params if isinstance(params, dict) else {}
    if params.get("decisao") is not None:
        return False, ("ficha_inline_nao_e_autoridade"
                       "(use decisao_id emitido pelo servidor)")
    ok, d = _r01_validar_decisao(sb, bot, tipo, params.get("decisao_id"))
    if not ok:
        return False, d
    uid = d.get("uid")
    params["uid"] = uid
    params["decisao"] = {"id": d.get("id"), "uid": uid,
                         "ts_barra": d.get("ts_barra"),
                         "veredito": d.get("veredito")}
    rpc_args = {"p_decisao_id": d.get("id"), "p_bot_id": bot.get("id"),
                "p_bot_token": bot.get("bot_token"),
                "p_user_id": bot.get("user_id"), "p_tipo": tipo,
                "p_params": params, "p_origem": origem}
    for tentativa in (1, 2):
        try:
            r = sb.rpc("r01_claim_e_comando", rpc_args).execute()
            row = (getattr(r, "data", None) or [{}])[0]
            if not row.get("ok"):
                return False, str(row.get("motivo") or "rpc_recusou")
            return True, {"id": row.get("comando_id"), "tipo": tipo,
                          "params": params, "status": "pendente",
                          "origem": origem}
        except Exception as _e:
            # transporte caiu / resposta perdida: consultar, nunca reemitir
            cmd = _r01_comando_por_uid(sb, bot.get("id"), uid)
            if cmd is not None:            # commit aconteceu — idempotente
                try:
                    print(f"[r-ciclo-01] resposta_perdida_recuperada "
                          f"uid={uid} comando={cmd.get('id')}")
                except Exception:
                    pass
                return True, cmd
            try:
                rows = (sb.table("ciclo_decisoes").select("status")
                        .eq("id", d.get("id")).limit(1).execute().data or [])
            except Exception:
                rows = []
            st = (rows[0].get("status") if rows else None)
            if st == "emitida" and tentativa == 1:
                continue                    # commit não houve — 1 retry
            if st == "consumida":
                return False, ("estado_indeterminado_pos_falha_rpc"
                               "(consumida_sem_comando_visivel — auditar; "
                               "nada reemitido)")
            return False, f"rpc_falhou({_e})"
    return False, "rpc_falhou(retry_esgotado)"


def _r01_emitir_decisao(sb, bot, tipo):
    """SÓ o servidor chama (detector/copiloto/bancada). Avalia a Lei do
    Contexto D1×H4 na leitura do servidor e PERSISTE a decisão. Abertura
    contra a referência ou sem leitura = a decisão NEM NASCE (fail-closed).
    Idempotente por (bot, ts_barra, lado). (ok, linha|motivo)."""
    from datetime import timedelta as _td3
    if tipo not in _R01_ABERTURAS:
        return False, "emissao_so_para_abertura"
    lado = 1 if tipo == "buy" else -1
    at, ts_barra, falha = _r01_ler_ciclos_servidor(sb, bot)
    if falha:
        return False, falha
    # ── c27r4/P1 — O VEREDITO DO CICLO 1 É VETO. Ordem de avaliação:
    # (1) veredito primeiro: "bloqueada" veta SEMPRE — janela favorável,
    #     HMAC válido, nada o sobrescreve; "neutra" não autoriza abertura;
    # (2) só "autorizada" segue, e então TUDO tem que ser coerente com a lei
    #     do motor (bt_ciclo_v1 l.413-415: autorizada ⇔ D1&H4 a favor):
    #     janela M1/M5/M15 toda no lado e CV2 D1==H4==lado. Atestado
    #     "autorizada" com janela/CV2 que a lei não produziria = CONTRADITÓRIO
    #     → recusa nomeada (fail-closed), nunca "corrigido" pra abrir.
    cv1 = at.get("cv1") or {}
    ver = cv1.get("veredito")
    if ver not in _cvat.VEREDITOS_CV1:                    # cinto (forma já barra)
        return False, "ciclo1_veredito_desconhecido(fail_closed)"
    if ver == "bloqueada":
        return False, f"ciclo1_veto(bloqueada)[{cv1.get('motivo') or 'motor'}]"
    if ver == "neutra":
        return False, "ciclo1_neutro_nao_autoriza"
    dirs = (at.get("cv2") or {}).get("dirs") or {}
    d1, h4 = dirs.get("D1"), dirs.get("H4")
    jan = cv1.get("janela") or {}
    j = [jan.get("M1"), jan.get("M5"), jan.get("M15")]
    if any(v == -lado for v in j):
        cont1 = "/".join(n for n, v in zip(("M1", "M5", "M15"), j)
                         if v == -lado)
        return False, f"atestado_incoerente(autorizada_com_janela_contra:{cont1})"
    if not all(v == lado for v in j):
        falt = "/".join(n for n, v in zip(("M1", "M5", "M15"), j)
                        if v != lado)
        return False, f"atestado_incoerente(autorizada_com_janela_{falt})"
    if d1 == -lado or h4 == -lado:
        cont = "/".join(n for n, v in (("D1", d1), ("H4", h4)) if v == -lado)
        return False, f"atestado_incoerente(autorizada_com_cv2_contra:{cont})"
    if not (d1 == lado and h4 == lado):
        return False, "atestado_incoerente(autorizada_sem_cv2_a_favor)"
    topdown = ["autorizada",
               "cv1_autorizada+janela(M1/M5/M15)+item1_referencia(D1&H4)"]
    ts_iso = ts_barra.isoformat()
    try:                              # idempotência de emissão
        ja = (sb.table("ciclo_decisoes").select("*")
              .eq("bot_id", bot.get("id")).eq("ts_barra", ts_iso)
              .eq("lado", lado).eq("status", "emitida")
              .limit(1).execute().data or [])
        if ja:
            # c27r4fim/P1.2 — colisão de barra com decisão PRÉ-v4: a linha
            # emitida na MESMA (bot, ts_barra, lado) sem contrato r01v4 nunca
            # é reciclada (o consumo a invalidaria e o produtor travaria a
            # barra sem diagnóstico) nem "promovida": recusa NOMEADA,
            # fail-closed. Saída: aguardar a PRÓXIMA barra M15 (novo ts_barra
            # = nova UNIQUE) ou limpeza da linha velha SÓ no banco isolado.
            velho = ja[0].get("veredito") or {}
            if velho.get("contrato") == "r01v4":
                # A mesma barra pode receber uma leitura nova do Ciclo.
                # Reuso só é idempotente enquanto os dados de autoridade
                # assinados continuam idênticos aos da decisão persistida.
                if (velho.get("cv1_veredito") != ver or
                        velho.get("cv1_janela") != jan or
                        velho.get("dirs") != dirs or
                        velho.get("versao_motor") != at.get("versao_motor")):
                    return False, "decisao_v4_leitura_alterada_na_barra(fail_closed)"
                return True, ja[0]
            return False, ("decisao_pre_v4_na_barra"
                           "(aguardar_proxima_barra_ou_limpeza_no_banco_isolado)")
    except Exception:
        pass
    uid = (f"{bot.get('id')}-"
           f"{ts_iso.replace('-', '').replace(':', '')[:13]}-"
           f"{'B' if lado == 1 else 'S'}")
    linha = {
        "id": _secrets.token_hex(16),           # NÃO derivável pelo cliente
        "bot_id": bot.get("id"), "simbolo": bot.get("simbolo"),
        "lado": lado, "uid": uid, "ts_barra": ts_iso,
        "veredito": {"contrato": "r01v4",       # c27r4: decisões pré-conserto
                     # não carregam este carimbo e o consumo as INVALIDA
                     "topdown": topdown, "dirs": dirs,
                     "cv1_janela": jan, "cv1_veredito": cv1.get("veredito"),
                     "versao_motor": at.get("versao_motor")},
        "status": "emitida",
        "ts_emissao": _dt.now(_tz.utc).isoformat(),
        "expira_em": (ts_barra + _td3(seconds=_R01_DEC_TTL_S)).isoformat(),
    }
    try:
        sb.table("ciclo_decisoes").insert(linha).execute()
    except Exception as _e:
        return False, f"emissao_falhou({_e})"
    return True, linha


def _r01_uid_ja_comandado(sb, bot_id, uid) -> bool:
    try:
        r = (sb.table("mt5_comandos").select("id,tipo,params")
             .eq("bot_id", bot_id).execute())
        for c in (r.data or []):
            if (c.get("tipo") in _R01_ABERTURAS and
                    (c.get("params") or {}).get("uid") == uid):
                return True
    except Exception:
        return True                    # dúvida = fail-closed
    return False


def _r01_validar_decisao(sb, bot, tipo, decisao_id):
    """c27r4/P2: LEITURA PURA da decisão (bot/símbolo/lado/contrato v4/prazo)
    — NÃO consome. O claim e o insert do comando acontecem juntos, numa única
    operação, dentro da RPC r01_claim_e_comando (migração 0003). O veredito é
    imutável pós-emissão, então validá-lo aqui por leitura é seguro; status e
    corrida são julgados pela RPC no banco. (ok, linha|motivo)."""
    if not isinstance(decisao_id, str) or not decisao_id.strip():
        return False, "decisao_ausente(fail_closed)"
    try:
        rows = (sb.table("ciclo_decisoes").select("*")
                .eq("id", decisao_id).limit(1).execute().data or [])
    except Exception:
        rows = []
    if not rows:
        return False, "decisao_inexistente"
    d = rows[0]
    if str(d.get("bot_id")) != str(bot.get("id")):
        return False, "decisao_de_outro_bot"
    if d.get("simbolo") != bot.get("simbolo"):
        return False, "decisao_de_outro_simbolo"
    lado = 1 if tipo == "buy" else -1
    if d.get("lado") != lado:
        return False, "decisao_lado_incoerente"
    _v = d.get("veredito") or {}
    if _v.get("contrato") != "r01v4" or _v.get("cv1_veredito") != "autorizada":
        # c27r4/P1: decisão emitida por contrato anterior (ou forjada no
        # banco sem o carimbo) NÃO contorna o veto do CV1 — invalidada.
        return False, "decisao_de_contrato_anterior_invalidada(fail_closed)"
    td = _v.get("topdown")
    if not isinstance(td, (list, tuple)) or len(td) < 2 \
            or td[0] != "autorizada":
        return False, "veredito_desconhecido(fail_closed)"
    try:
        exp = _dt.fromisoformat(str(d.get("expira_em")).replace("Z", "+00:00"))
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=_tz.utc)
    except Exception:
        return False, "decisao_sem_validade(fail_closed)"
    if _dt.now(_tz.utc) > exp:
        return False, "decisao_vencida"
    # Um decisao_id emitido ANTES de um novo snapshot não autoriza uma
    # abertura depois que o Ciclo mudou. Conferir a leitura assinada atual
    # novamente no último ponto da API antes do claim transacional.
    at, ts_atual, falha = _r01_ler_ciclos_servidor(sb, bot)
    if falha:
        return False, f"decisao_sem_leitura_atual({falha})"
    try:
        ts_dec = _dt.fromisoformat(str(d.get("ts_barra")).replace("Z", "+00:00"))
        if ts_dec.tzinfo is None:
            ts_dec = ts_dec.replace(tzinfo=_tz.utc)
    except Exception:
        return False, "decisao_barra_invalida"
    cv1 = at.get("cv1") or {}
    dirs = (at.get("cv2") or {}).get("dirs") or {}
    janela = cv1.get("janela") or {}
    if (ts_dec != ts_atual or cv1.get("veredito") != "autorizada" or
            _v.get("cv1_janela") != janela or _v.get("dirs") != dirs or
            _v.get("versao_motor") != at.get("versao_motor") or
            any(janela.get(tf) != lado for tf in ("M1", "M5", "M15")) or
            dirs.get("D1") != lado or dirs.get("H4") != lado):
        return False, "decisao_leitura_atual_divergente(fail_closed)"
    return True, d


# c27r4/P2: _r01_portao_abertura foi SUBSTITUÍDO por _r01_abrir_via_rpc —
# claim separado e compensação client-side saíram do caminho ativo.


_MT5_TIPOS_VALIDOS = {"buy", "sell", "close", "close_all",
                      "mover_sl", "mover_tp", "cancelar"}


class MT5ComandoIn(BaseModel):
    bot_token: str
    tipo: str
    params: dict = {}
    origem: str = "manual"        # manual | copiloto | auto_detector | admin


class MT5ComandoConfirmIn(BaseModel):
    comando_id: int
    sucesso: bool
    resultado: dict = {}          # {ticket, preco_real, retcode, erro}
    bot_token: Optional[str] = None   # C27R16: obrigatório — só o dono do comando confirma


def _mt5_expirar_throttled(sb):
    """Chama _mt5_expirar_comandos() no Supabase no máximo 1x por 30s.
    Comandos expirados NÃO são urgência — throttle protege o banco."""
    import time
    agora = time.time()
    if agora - _MT5_EXPIRAR_THROTTLE["ultimo"] < 30:
        return
    _MT5_EXPIRAR_THROTTLE["ultimo"] = agora
    try:
        sb.rpc("_mt5_expirar_comandos").execute()
    except Exception as _e:
        try: print(f"[mt5 expirar] {_e}")
        except Exception: pass


def _mt5_bot_online(bot: dict) -> bool:
    """Bot precisa estar emitindo snapshots recentes pra receber comandos.
    Sem essa checagem, poderíamos criar comando pra bot morto."""
    ping = bot.get("ultimo_ping")
    if not ping: return False
    try:
        p = _dt.fromisoformat(str(ping).replace("Z", "+00:00"))
        return (_dt.now(_tz.utc) - p).total_seconds() < OFFLINE_APOS_SEGUNDOS
    except Exception:
        return False


def _mt5_contar_comandos_dia(sb, bot_id: int) -> int:
    """Conta comandos criados nas últimas 24h pro bot. Base do circuit breaker."""
    try:
        desde = (_dt.now(_tz.utc) - timedelta(days=1)).isoformat()
        r = (sb.table("mt5_comandos")
             .select("id", count="exact")
             .eq("bot_id", bot_id)
             .gte("criado_em", desde)
             .execute())
        return int(getattr(r, "count", None) or len(r.data or []))
    except Exception:
        return 0


@app.post("/mt5/comando")
def mt5_comando_criar(inp: MT5ComandoIn):
    """Cria um comando na fila pra ser puxado pelo conector PY. Valida bot
    online, tipo suportado, e limite diário. UI, detector automático e admin
    usam este mesmo endpoint — diferença fica em 'origem'."""
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponivel")
    tipo = (inp.tipo or "").lower().strip()
    if tipo not in _MT5_TIPOS_VALIDOS:
        raise HTTPException(status_code=400, detail=f"tipo invalido (validos: {sorted(_MT5_TIPOS_VALIDOS)})")
    bot = _bot_por_token(sb, inp.bot_token)
    if not bot:
        raise HTTPException(status_code=401, detail="bot_token invalido")
    # Bot precisa estar online — sem ping recente, comando fica pendurado
    if not _mt5_bot_online(bot):
        raise HTTPException(status_code=409, detail="bot offline — nao emite snapshot ha mais de 45s")
    # Circuit breaker: limite de comandos por dia por bot (sessao 3 refina)
    if _mt5_contar_comandos_dia(sb, bot.get("id")) >= MAX_COMANDOS_DIA_POR_BOT:
        raise HTTPException(status_code=429, detail=f"limite diario de {MAX_COMANDOS_DIA_POR_BOT} comandos atingido")
    origem = (inp.origem or "manual").lower().strip()
    if origem not in ("manual", "copiloto", "auto_detector", "admin"):
        origem = "manual"
    if tipo in _R01_ABERTURAS:            # c27r4: abertura SÓ pela RPC
        _okI, criado = _r01_abrir_via_rpc(sb, bot, tipo, inp.params or {},
                                          origem)
        if not _okI:
            raise HTTPException(status_code=422,
                                detail=f"abertura_recusada[{criado}]")
    else:                                  # gestão: sem leitura, insert direto
        linha = {
            "bot_token": inp.bot_token,
            "user_id": bot.get("user_id"),
            "bot_id": bot.get("id"),
            "tipo": tipo,
            "params": inp.params or {},
            "status": "pendente",
            "origem": origem,
        }
        try:
            r = sb.table("mt5_comandos").insert(linha).execute()
            criado = (r.data or [{}])[0]
        except Exception as e:
            raise HTTPException(status_code=500,
                                detail=f"erro ao criar comando: {e}")
    _mt5_expirar_throttled(sb)
    return {"ok": True, "comando_id": criado.get("id"), "status": criado.get("status"), "expira_em": criado.get("expira_em")}


# ── B10-B: FIM DO bot_token EM URL NO PAR CLOUD↔CONECTOR (AUT-011..013) ─────
# As 6 rotas GET que carregavam a credencial do conector em query string ganham
# um POST GÊMEO com o token no CORPO (consumido pelo conector v1.36). O GET
# legado SOBREVIVE durante a migração da frota (v1.35 no ar), TELEMETRADO —
# morre numa R7 quando a telemetria zerar por janela acordada. Regras do par:
#   - REVOGAÇÃO: token de bot EXCLUÍDO deixa de autenticar (excluir = revogar);
#     resposta idêntica à de token inexistente (sem oráculo de existência);
#   - bot alheio ≡ inexistente no /conector/bot/mq5 (o 403/404 que denunciava
#     ids de bots de terceiros morreu — 404 byte-idêntico nos dois);
#   - ONE-SHOT (subir-conector) e FILA (comando/pendente) com CLAIM ATÔMICO:
#     update condicional no banco elege UM vencedor sob corrida de 2 clientes;
#     replay depois do consumo responde o mesmo "nada pra você" de sempre.
import threading as _b10b_th
_GET_LEGADO_USOS: dict = {}
_B10B_LOCK = _b10b_th.Lock()


def _tele_get_legado(rota: str):
    try:
        with _B10B_LOCK:
            _GET_LEGADO_USOS[rota] = _GET_LEGADO_USOS.get(rota, 0) + 1
    except Exception:
        pass


def _bot_vivo_por_token(sb, bot_token: str):
    """_bot_por_token + revogação: bot excluído não autentica mais nada.
    Token de bot excluído responde IDÊNTICO a token inexistente."""
    b = _bot_por_token(sb, (bot_token or "").strip())
    if not b or b.get("excluido"):
        return None
    _rl_registrar_identidade((bot_token or "").strip(), "bot:" + str(b.get("id") or b.get("bot_token") or ""))
    return b


def _subir_conector_claim(bot_token: str) -> bool:
    """One-shot do 'subir conector' com CLAIM atômico: sob corrida de dois
    clientes com o mesmo token, exatamente UM recebe True (o update condicional
    devolve 0 linhas pro perdedor). Token vazio, inexistente, revogado ou sem
    sinal respondem o MESMO False — sem oráculo nenhum."""
    tok = (bot_token or "").strip()
    if not tok:
        return False
    try:
        sb = _sb_admin()
    except Exception:
        sb = None
    if sb is not None and _bot_vivo_por_token(sb, tok) is None:
        return False
    with _B10B_LOCK:
        mem_ts = _MT5_RAISE.pop(tok, 0)
    mem_ok = bool(mem_ts and (_time_mt5.time() - mem_ts) < 180)
    if sb is None:
        return mem_ok   # sem banco, vale a memória do worker (legado)
    try:
        r = (sb.table("conector_bots").select("subir_pedido_em")
             .eq("bot_token", tok).limit(1).execute())
        val = r.data[0].get("subir_pedido_em") if r.data else None
        if not val:
            # sinal só existia em memória (gravação no banco falhou na origem)
            return mem_ok
        try:
            pedido = _dt.fromisoformat(str(val).replace("Z", "+00:00"))
            recente = (_dt.now(_tz.utc) - pedido).total_seconds() < 180
        except Exception:
            recente = True
        if not recente:
            try:
                (sb.table("conector_bots").update({"subir_pedido_em": None})
                 .eq("bot_token", tok).eq("subir_pedido_em", val).execute())
            except Exception:
                pass
            return False
        upd = (sb.table("conector_bots").update({"subir_pedido_em": None})
               .eq("bot_token", tok).eq("subir_pedido_em", val).execute())
        return bool(getattr(upd, "data", None))
    except Exception:
        return mem_ok


class ConectorTokenIn(BaseModel):
    bot_token: str = ""


class ConectorTokenBotIn(BaseModel):
    bot_token: str = ""
    bot_id: int = 0


def _comando_pendente_claim(bot_token: str) -> dict:
    """Entrega o comando pendente mais antigo com CLAIM ATÔMICO por comando:
    o update condicional (status ainda 'pendente') devolve 0 linhas pro poll
    que PERDEU a corrida — dois conectores nunca levam o mesmo comando (B10-B;
    a versão antiga selecionava e só depois marcava, com janela de corrida, e
    entregava mesmo quando a marcação falhava). Token de bot excluído responde
    401 idêntico a token inexistente (revogação)."""
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponivel")
    bot = _bot_vivo_por_token(sb, bot_token)
    if not bot:
        raise HTTPException(status_code=401, detail="bot_token invalido")
    _mt5_expirar_throttled(sb)
    try:
        r = (sb.table("mt5_comandos")
             .select("*")
             .eq("bot_token", bot_token)
             .eq("status", "pendente")
             .order("criado_em")
             .limit(5)
             .execute())
        linhas = r.data or []
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"erro ao buscar comando: {e}")
    for cmd in linhas:
        try:
            upd = (sb.table("mt5_comandos").update({
                "status": "entregue",
                "entregue_em": _dt.now(_tz.utc).isoformat(),
            }).eq("id", cmd["id"]).eq("status", "pendente").execute())
        except Exception:
            continue
        if not getattr(upd, "data", None):
            continue   # outro cliente levou este comando; tenta o próximo
        return {"comando": {
            "id": cmd["id"],
            "tipo": cmd["tipo"],
            "params": cmd.get("params") or {},
            "criado_em": cmd.get("criado_em"),
            "expira_em": cmd.get("expira_em"),
        }}
    return {"comando": None}


@app.get("/mt5/comando/pendente")
def mt5_comando_pendente(bot_token: str):
    """LEGADO (AUT-012): token em QUERY — telemetrado. Sem consumidor vivo no
    conector v1.35 (o canal de comando nunca integrou, Sessão 2); a v1.36+
    usa o POST gêmeo. Claim atômico compartilhado (B10-B)."""
    _tele_get_legado("mt5/comando/pendente")
    return _comando_pendente_claim(bot_token)


@app.post("/mt5/comando/pendente/checar")
def mt5_comando_pendente_post(req: ConectorTokenIn):
    """v1.36 (AUT-012): o token viaja no CORPO — segredo fora de URL e logs."""
    return _comando_pendente_claim(req.bot_token)


@app.post("/mt5/comando/confirmar")
def mt5_comando_confirmar(inp: MT5ComandoConfirmIn):
    """EA confirma execucao (via conector PY). resultado.ticket + preco_real
    quando sucesso; resultado.erro quando falhou. Idempotente: se ja foi
    confirmado, retorna o estado atual sem sobrescrever."""
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponivel")
    try:
        atual = (sb.table("mt5_comandos").select("*").eq("id", inp.comando_id).limit(1).execute().data or [])
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"erro ao buscar: {e}")
    if not atual:
        raise HTTPException(status_code=404, detail="comando nao encontrado")
    cmd = atual[0]
    # C27R16 — antes qualquer chamador confirmava qualquer comando só pelo id. Agora a
    # confirmação exige o token do bot DONO do comando (resposta idêntica para id
    # inexistente e token errado: não revela a existência do comando).
    import hmac as _hm16
    if not inp.bot_token or not _hm16.compare_digest(str(inp.bot_token), str(cmd.get("bot_token") or "")):
        raise HTTPException(status_code=404, detail="comando nao encontrado")
    if cmd.get("status") in ("executado", "falhou", "expirado", "cancelado"):
        return {"ok": True, "status": cmd["status"], "ja_confirmado": True}
    novo_status = "executado" if inp.sucesso else "falhou"
    try:
        sb.table("mt5_comandos").update({
            "status": novo_status,
            "confirmado_em": _dt.now(_tz.utc).isoformat(),
            "resultado": inp.resultado or {},
        }).eq("id", inp.comando_id).execute()
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"erro ao confirmar: {e}")
    try:
        _res = inp.resultado or {}
        _clm_comando_evento(sb, cmd, "resposta_mt5", "ok" if inp.sucesso else "falha",
                            (f"MT5 executou: ticket {_res.get('ticket')} preço {_res.get('preco_real')} "
                             f"retcode {_res.get('retcode')}"
                             if inp.sucesso else
                             f"{'EA/conector' if _res.get('etapa') in ('ea', 'conector') else 'MT5'} "
                             f"não executou: {_res.get('erro')} (retcode {_res.get('retcode')})"))
    except Exception:
        pass
    # v6.76 — se comando executou com sucesso, BabyMachine marca pendente como aberta
    if inp.sucesso:
        try: _bm_marcar_aberta_por_comando(sb, inp.comando_id, inp.resultado or {})
        except Exception as _e:
            try: print(f"[bm confirmar] {_e}")
            except Exception: pass
    return {"ok": True, "status": novo_status}


