# ── VITRINE: estratégias prontas + desempenho MÉDIO histórico (público) ──
# Regra de marca: nunca revelar a existência da biblioteca interna. Aqui
# devolvemos apenas uma MÉDIA de desempenho histórico por estratégia,
# apresentada como "média histórica" — sem expor linhas nem a fonte.
_VITRINE_CACHE = {"t": 0.0, "dados": None}

def _vit_faixa(wrs):
    """Faixa de acerto min-max arredondada em 5 (ex. [65, 75]). Numero cravado
    com 1 casa em cima de 2 medicoes e falsa precisao — a faixa diz a verdade
    sobre o tamanho da amostra sem precisar explicar amostra."""
    wrs = [w for w in wrs if w is not None]
    if not wrs:
        return None
    lo = max(0, int(min(wrs) // 5 * 5))
    hi = min(100, int(-(-max(wrs) // 5) * 5))
    if hi <= lo:
        hi = min(100, lo + 5)
    return [lo, hi]


def _vit_periodos_tf(tf):
    """Quantas medicoes o motor da biblioteca CONSEGUE fazer neste timeframe.
    Vem do proprio _BIB_COMBOS: 1d tem 3 periodos, 15m/30m/1h/4h tem 2 e o 5m
    tem 1 — limitacao de historico intradiario do provedor, nao escolha. Serve
    pra cobrar completude do que e obtenivel em vez de um numero fixo."""
    try:
        return max(1, len(_BIB_COMBOS.get(str(tf or "").strip().lower(), []) or []))
    except Exception:
        return 3


def _vit_estrelas(sh_max, bons, n, min_trades_ok, tf=None):
    """Piso ABSOLUTO de qualidade (o rank relativo entre TFs vem depois). Sem
    isso, um card ruim ganharia 5 estrelas so por ter o 'menos pior' dos TFs."""
    if not min_trades_ok:
        return 1
    aprov = (bons / n) if n else 0.0
    # v7.15 — completude exigida RELATIVA ao obtenivel naquele TF (ver
    # _vit_periodos_tf). Piso de 2 mantido: uma medicao unica nao e evidencia.
    _n_min = max(2, min(3, _vit_periodos_tf(tf))) if tf else 3
    if sh_max >= 2.5 and bons == n and n >= _n_min:
        e = 5
    elif sh_max >= 1.5 and aprov >= 0.66 and bons >= 1:
        e = 4
    elif sh_max >= 1.0 and bons >= 1:
        e = 3
    elif sh_max > 0:
        e = 2
    else:
        e = 1
    if n < _n_min:
        e = min(e, 4)   # 5 estrelas se conquista com medicao, nao com sorte
    return e


def _vit_escada_tf(combos, min_trades):
    """Escada de timeframes de UM ativo: cada TF com estrelas e faixa de acerto.
    COLAPSADA DE PROPOSITO — no maximo 3 TFs individuais + uma linha 'demais'.
    A vitrine vende direcao, nao entrega o banco de estudo (decisao do dono)."""
    porf = {}
    _visto = set()
    for c in combos:
        tf = c.get("tf") or ""
        if not tf:
            continue
        # v7.15b — ANTI-EVIDENCIA DUPLICADA: o yfinance corta intradiario em
        # ~60 dias, entao pedir "6 meses" e "1 ano" em 15m/30m devolve a MESMA
        # janela e grava duas linhas identicas com periodo diferente. Contar as
        # duas como 2 medicoes inflaria o n e daria estrela por evidencia que
        # nao existe. Medicoes com numeros identicos valem UMA.
        _assin = (tf, round(float(c.get("sh") or 0), 6), round(float(c.get("wr") or 0), 6),
                  int(c.get("trades") or 0), round(float(c.get("ret") or 0), 6))
        if _assin in _visto:
            continue
        _visto.add(_assin)
        d = porf.setdefault(tf, {"n": 0, "bons": 0, "sh": [], "wr": [], "trades": 0})
        d["n"] += 1
        d["sh"].append(c.get("sh") or 0.0)
        d["wr"].append(c.get("wr"))
        d["trades"] = max(d["trades"], int(c.get("trades") or 0))
        if (c.get("ret") or 0) > 0 and (c.get("sh") or 0) >= 1.0 \
           and int(c.get("trades") or 0) >= min_trades:
            d["bons"] += 1
    if not porf:
        return []
    linhas = []
    for tf, d in porf.items():
        sh_max = max(d["sh"]) if d["sh"] else 0.0
        linhas.append({
            "tf": tf,
            "estrelas": _vit_estrelas(sh_max, d["bons"], d["n"], d["trades"] >= min_trades, tf),
            "faixa": _vit_faixa(d["wr"]),
            "n": d["n"],
            "_sh": round(sh_max, 2),
            "_aprov": (d["bons"] / d["n"]) if d["n"] else 0.0,
        })
    linhas.sort(key=lambda x: (x["estrelas"], x["_aprov"], x["_sh"]), reverse=True)
    fortes = [l for l in linhas if l["estrelas"] >= 2][:3]
    resto = [l for l in linhas if l not in fortes]
    out = []
    for l in fortes:
        out.append({"tf": l["tf"], "estrelas": l["estrelas"], "faixa": l["faixa"], "n": l["n"]})
    if resto:
        out.append({"tf": "demais", "estrelas": 1, "faixa": None,
                    "n": sum(l["n"] for l in resto), "agrupado": len(resto)})
    return out



def _vit_celulas_aprovadas(ativos, min_trades):
    """v7.23 — CURADORIA: celulas (ativo x TF) desta estrategia que passam a
    REGUA DE APROVACAO: estrelas >= 4 (mesma _vit_estrelas da escada, com o
    dedup anti-evidencia da v7.15b) + melhor combo do TF com retorno positivo,
    PF >= 1.3 e sharpe > 0. Saida COLAPSADA (estrelas + faixa, nunca os
    numeros crus por celula) — o anti-vazamento do banco continua valendo."""
    out = []
    try:
        for ativo_nome, d in (ativos or {}).items():
            combos = d.get("combos") or []
            porf, visto = {}, set()
            for c in combos:
                tf = c.get("tf") or ""
                if not tf:
                    continue
                assin = (tf, round(float(c.get("sh") or 0), 6), round(float(c.get("wr") or 0), 6),
                         int(c.get("trades") or 0), round(float(c.get("ret") or 0), 6))
                if assin in visto:
                    continue
                visto.add(assin)
                g = porf.setdefault(tf, {"n": 0, "bons": 0, "sh": [], "wr": [],
                                         "pf": [], "ret": [], "trades": 0})
                g["n"] += 1
                g["sh"].append(c.get("sh") or 0.0)
                g["wr"].append(c.get("wr"))
                g["pf"].append(c.get("pf") or 0.0)
                g["ret"].append(c.get("ret") or 0.0)
                g["trades"] = max(g["trades"], int(c.get("trades") or 0))
                if (c.get("ret") or 0) > 0 and (c.get("sh") or 0) >= 1.0 \
                   and int(c.get("trades") or 0) >= min_trades:
                    g["bons"] += 1
            for tf, g in porf.items():
                sh_max = max(g["sh"]) if g["sh"] else 0.0
                estrelas = _vit_estrelas(sh_max, g["bons"], g["n"], g["trades"] >= min_trades, tf)
                pf_max = max(g["pf"]) if g["pf"] else 0.0
                ret_max = max(g["ret"]) if g["ret"] else 0.0
                if estrelas >= 4 and pf_max >= 1.3 and sh_max > 0 and ret_max > 0:
                    out.append({"ativo": ativo_nome, "tf": tf, "estrelas": estrelas,
                                "faixa": _vit_faixa(g["wr"]), "_sh": round(sh_max, 2)})
        out.sort(key=lambda x: (x["estrelas"], x["_sh"]), reverse=True)
    except Exception:
        pass
    return out[:3]


def _vitrine_com_card_teste(out, authorization):
    """v7.74 — GATE SERVER-SIDE DO CARD DE TESTE (MAPA_E_ORDEM_VITRINE_MT5,
    27/set, item 2 da ordem): o card TESTE DE INTEGRACAO MT5 — DEMO so existe
    na resposta quando O SERVIDOR autoriza — env BT_CARD_TESTE_USER setada E a
    SESSAO da chamada (Authorization Bearer -> _sessao_user_id) pertencer
    exatamente a esse usuario. NENHUM parametro de cliente ativa o card (o
    gate mora em env do servidor + sessao validada no Supabase Auth); o cache
    compartilhado da vitrine NUNCA contem o card — ele e apensado numa COPIA
    da resposta, por chamada, entao a resposta cacheada servida a qualquer
    outro caller e byte-identica a de sempre. Anonimo, sessao invalida ou
    sessao de outro usuario recebem a resposta padrao SEM erro novo (a rota
    continua anonima; o gate falha em silencio de proposito — sem oraculo da
    existencia do card). Sem melhor_combo/medicoes por construcao: o front
    (v9.47+) mostra "Em medicao" e NAO dispara backtest automatico."""
    import os as _os
    alvo = (_os.environ.get("BT_CARD_TESTE_USER") or "").strip()
    if not alvo:
        return out
    try:
        uid = _sessao_user_id(authorization)
    except Exception:
        return out
    try:
        if not _hmac.compare_digest(str(uid), alvo):
            return out
    except Exception:
        return out
    try:
        est = ESTRATEGIA_TESTE_MT5
        item = {
            "id": est["id"], "nome": est["nome"], "desc": est["desc"],
            "emoji": est.get("emoji", "\U0001f9ea"), "tags": list(est.get("tags", [])),
            "categoria": "teste", "nivel": est.get("nivel", "interno"),
            "mercados": list(est.get("mercados", [])),
            "top_ativos": list(est.get("mercados", []))[:3],
            "melhor_combo": None, "escada_tf": {}, "celulas_aprovadas": [],
            "aprovacao": "em_medicao", "medida": False, "casa": False,
            "cor_destaque": None, "codigo": est.get("codigo", ""),
            "ensaio": dict(est.get("ensaio") or {}),
            "sharpe_medio": None, "pf_medio": None, "retorno_medio": None,
            "winrate_medio": None, "combos": 0, "forte_pct": 0,
        }
        copia = dict(out or {})
        copia["estrategias"] = list((out or {}).get("estrategias") or []) + [item]
        copia["total"] = len(copia["estrategias"])
        return copia
    except Exception:
        return out


@app.get("/estrategias/vitrine")
def estrategias_vitrine(lang: str = "pt", authorization: str = Header("")):
    import time as _t
    # cache de 1h (cálculo de média é estável; evita varrer a tabela a cada visita)
    if _VITRINE_CACHE["dados"] is not None and (_t.time() - _VITRINE_CACHE["t"] < 3600):
        return _vitrine_com_card_teste(_VITRINE_CACHE["dados"], authorization)

    # agrega média por estrategia_id (server-side; nunca devolve linha individual)
    medias = {}
    sb = _sb_admin()
    if sb is not None:
        try:
            # v6.45 — PAGINAÇÃO: o PostgREST/Supabase tem teto padrão de ~1000
            # linhas por requisição MESMO pedindo .limit(8000). Com a biblioteca
            # completa (6.720 linhas), a vitrine agregava só ~15% do banco — por
            # isso estratégias plenamente medidas apareciam "Em medição".
            rows = []
            _pg = 0
            while True:
                lote = (sb.table("estudo_biblioteca")
                        .select("estrategia_id,ativo,sharpe,profit_factor,retorno,win_rate,trades,forca,timeframe,periodo,regras_versao,captura_pct")
                        .range(_pg * 1000, _pg * 1000 + 999).execute().data or [])
                rows.extend(lote)
                if len(lote) < 1000 or _pg >= 15:   # teto de segurança: 16k linhas
                    break
                _pg += 1
            print(f"[vitrine] biblioteca: {len(rows)} linhas agregadas ({_pg + 1} páginas)")
            # ── v7.16: DEDUP NA RAIZ (medido no banco em 26/jul) ────────────
            # 100% das celulas de 15m e 30m (594 de 594 = 18 estrategias x 33
            # ativos) tinham DUAS linhas com numeros IDENTICOS e periodo
            # diferente: o yfinance corta intradiario em ~60 dias, entao pedir
            # "6 meses" e "1 ano" baixa o MESMO arquivo. Eram ~1.188 linhas de
            # eco num banco de ~7.100 (17%), entrando com PESO DOBRADO em
            # sharpe_medio/winrate_medio/pf_medio dos cards e inflando o n das
            # estrelas. Medicao identica vale UMA — a partir daqui, em tudo.
            # ── v7.17: MIGRACAO SUAVE ENTRE ERAS DE MEDICAO ────────────────
            # Durante a remedicao o banco tem linhas velhas (stop fixo 0,50%) e
            # novas (regras de fabrica). Misturar as duas numa media so seria
            # pior que qualquer uma sozinha. Por CELULA: se ja existe medicao da
            # versao atual, usa SO ela; senao mantem a antiga. Card nenhum fica
            # vazio e media nenhuma mistura eras — a vitrine migra sozinha,
            # celula por celula, conforme o esquenta avanca.
            _tem_novo = set()
            for _r in rows:
                if (_r.get("regras_versao") or "") == REGRAS_VERSAO_BIB:
                    _tem_novo.add((_r.get("estrategia_id"), _r.get("ativo"), _r.get("timeframe")))
            if _tem_novo:
                _antes = len(rows)
                rows = [_r for _r in rows
                        if (_r.get("estrategia_id"), _r.get("ativo"), _r.get("timeframe")) not in _tem_novo
                        or (_r.get("regras_versao") or "") == REGRAS_VERSAO_BIB]
                print(f"[vitrine] eras: {len(_tem_novo)} celulas ja remedidas "
                      f"({_antes} -> {len(rows)} linhas apos preferir a versao atual)")
            _dedup, _vistas = [], set()
            for _r in rows:
                _k = (_r.get("estrategia_id"), _r.get("ativo"), _r.get("timeframe"),
                      _r.get("sharpe"), _r.get("win_rate"), _r.get("trades"), _r.get("retorno"))
                if _k in _vistas:
                    continue
                _vistas.add(_k)
                _dedup.append(_r)
            if len(_dedup) != len(rows):
                print(f"[vitrine] dedup: {len(rows)} -> {len(_dedup)} linhas "
                      f"({len(rows) - len(_dedup)} medicoes repetidas descartadas)")
            rows = _dedup
            # ── SEM AÇÕES NA VITRINE (v6.41) ─────────────────────────────────
            # Ações (Magnificent 7, Ações Pro, B3) ficam FORA da vitrine: o bull
            # de longo prazo delas (Google/Microsoft etc.) distorce as médias e
            # não é referência estável — os setores estão mudando. A vitrine
            # compara a estratégia em Índices, Forex, Commodities e Cripto.
            # (As ações continuam no catálogo pra quem quiser testar por conta.)
            _CATS_ACOES = ("Magnificent 7", "Ações Pro", "B3 — Brasil")
            _ATIVOS_ACOES = set()
            for _cat in _CATS_ACOES:
                for _a in CATALOGO_ATIVOS.get(_cat, []):
                    _ATIVOS_ACOES.add(_a.get("nome"))
            rows = [r for r in rows if r.get("ativo") not in _ATIVOS_ACOES]
            acc = {}
            por_ativo = {}   # estrategia_id -> {ativo -> {sh:[], n:int}}  (p/ ranking de ativos)
            for r in rows:
                eid = r.get("estrategia_id")
                if not eid:
                    continue
                a = acc.setdefault(eid, {"sh": [], "pf": [], "ret": [], "wr": [], "n": 0, "forte": 0})
                a["sh"].append(float(r.get("sharpe") or 0))
                a["pf"].append(float(r.get("profit_factor") or 0))
                a["ret"].append(float(r.get("retorno") or 0))
                a["wr"].append(float(r.get("win_rate") or 0))
                a["n"] += 1
                if r.get("forca") == "forte":
                    a["forte"] += 1
                # acumula sharpe + trades + timeframe por ativo (p/ achar onde a estratégia
                # mais funciona). Estratégias diárias são avaliadas só no D1 (ver _TF_NATURAL);
                # as demais, pelo melhor timeframe robusto.
                ativo_nome = r.get("ativo")
                if ativo_nome:
                    pa = por_ativo.setdefault(eid, {}).setdefault(ativo_nome, {"combos": []})
                    pa["combos"].append({"sh": float(r.get("sharpe") or 0),
                                         "trades": int(r.get("trades") or 0),
                                         "tf": str(r.get("timeframe") or "").strip().lower(),
                                         "periodo": str(r.get("periodo") or "").strip(),
                                         "ret": float(r.get("retorno") or 0),
                                         "pf": float(r.get("profit_factor") or 0),
                                         "wr": float(r.get("win_rate") or 0)})
            # top 3 ativos por estratégia
            # ── FILTRO DE ROBUSTEZ ──────────────────────────────────────────
            # Estratégias DIÁRIAS por natureza (leem o D1: Escalonada, Suporte&Resistência
            # do dia anterior, Fechamento Ímã, Gap de abertura) são avaliadas SÓ no
            # timeframe diário — é onde elas operam de verdade. Avaliá-las no melhor TF
            # qualquer deixava resultados intraday (5m/15m) sem sentido dominarem o ranking
            # e empurrarem pra fora ativos que vão bem no diário (ex: BTC na Escalonada).
            # As demais estratégias continuam pelo MELHOR timeframe robusto.
            # Critérios (iguais p/ ambas): combo com trades suficientes, mín. de medições,
            # sharpe acima do piso. Sem ativos robustos -> top vazio -> fallback "mercados".
            _MIN_BACKTESTS_ATIVO = 2     # nº mínimo de medições por ativo
            _MIN_TRADES_COMBO    = 20    # trades mínimos no combo (mesma régua do estudo)
            _PISO_SHARPE_ATIVO   = 0.5   # melhor sharpe mínimo p/ ser sugerível
            # estratégias que LEEM o D1: avaliadas só no diário
            _TF_NATURAL = {
                "tendencia_diaria_piramide": "1d",   # Escalonada
                "sr_dia_anterior": "1d",             # Suporte & Resistência do dia anterior
                "fechamento_ima": "1d",              # Fechamento Anterior como Ímã
                "abertura_gap": "1d",                # Gap de Abertura
            }
            # ── CURADORIA DO DONO ───────────────────────────────────────────
            # Ativos fixados manualmente em cards específicos: entram SEMPRE na
            # frente da linha de ativos, independente do ranking automático.
            # Motivo: algumas estratégias (ex: a Escalonada, com escalonamento de
            # lote) não são bem capturadas pela métrica de backtest padrão — a
            # decisão de exibição é do dono, que fará a revisão completa da vitrine.
            _ATIVOS_FIXOS_VITRINE = {
                "tendencia_diaria_piramide": ["BTC/USD"],   # Escalonada — decisão do dono
            }
            top_ativos_por_est = {}
            _MELHOR_COMBO_EST = {}
            _ESCADA_EST = {}
            _APROV_EST = {}
            for eid, ativos in por_ativo.items():
                tf_natural = _TF_NATURAL.get(eid)   # None p/ estratégias multi-timeframe
                ranking = []
                melhor_combo_do_ativo = {}
                for ativo_nome, d in ativos.items():
                    combos = d["combos"]
                    if len(combos) < _MIN_BACKTESTS_ATIVO:
                        continue
                    if tf_natural:
                        # estratégia diária: só conta o combo do timeframe natural (D1)
                        robustos = [c for c in combos
                                    if c["tf"] == tf_natural and c["trades"] >= _MIN_TRADES_COMBO]
                    else:
                        # multi-timeframe: melhor combo entre os que têm trades suficientes
                        robustos = [c for c in combos if c["trades"] >= _MIN_TRADES_COMBO]
                    # v6.41: combo precisa ter dado RETORNO POSITIVO — a vitrine não
                    # pode destacar um ativo que, testado no clique, sai negativo.
                    robustos = [c for c in robustos if c["ret"] > 0]
                    if not robustos:
                        continue
                    melhor = max(robustos, key=lambda c: c["sh"])
                    if melhor["sh"] < _PISO_SHARPE_ATIVO:
                        continue
                    melhor_combo_do_ativo[ativo_nome] = melhor
                    ranking.append((ativo_nome, melhor["sh"], len(combos)))
                ranking.sort(key=lambda x: x[1], reverse=True)
                auto = [nome for (nome, _sh, _n) in ranking[:3]]
                # melhor combo do 1º ativo do card (fixo do dono tem prioridade se
                # tiver combo robusto; senão cai pro 1º do ranking automático)
                _prefer = (_ATIVOS_FIXOS_VITRINE.get(eid, []) + auto)
                for _nome in _prefer:
                    mc = melhor_combo_do_ativo.get(_nome)
                    if mc:
                        _wr_tf = [c["wr"] for c in ativos.get(_nome, {}).get("combos", [])
                                  if c.get("tf") == mc["tf"]]
                        _MELHOR_COMBO_EST[eid] = {"ativo": _nome, "periodo": mc["periodo"],
                                                  "timeframe": mc["tf"],
                                                  "retorno": round(mc["ret"], 2),
                                                  "win_rate": round(mc["wr"], 1),
                                                  "faixa_acerto": _vit_faixa(_wr_tf)}
                        break
                # ── ESCADA DE TIMEFRAMES por ativo do card (v7.14) ──
                # So dos ativos que o card MOSTRA (3 de 40) — a vitrine nunca
                # devolve a matriz inteira, nem pra quem chamar a API direto.
                _esc = {}
                for _nome in list(dict.fromkeys(_ATIVOS_FIXOS_VITRINE.get(eid, []) + auto))[:3]:
                    _d = ativos.get(_nome)
                    if not _d:
                        continue
                    _linhas = _vit_escada_tf(_d["combos"], _MIN_TRADES_COMBO)
                    if _linhas:
                        _esc[_nome] = _linhas
                if _esc:
                    _ESCADA_EST[eid] = _esc
                # v7.23 — CURADORIA: celulas aprovadas desta estrategia (todos
                # os ativos com combos suficientes, nao so os 3 do card)
                _cels = _vit_celulas_aprovadas(
                    {n: dd for n, dd in ativos.items() if len(dd.get("combos") or []) >= _MIN_BACKTESTS_ATIVO},
                    _MIN_TRADES_COMBO)
                if _cels:
                    _APROV_EST[eid] = _cels
                fixos = _ATIVOS_FIXOS_VITRINE.get(eid, [])
                if fixos:
                    # fixos na frente, sem duplicar, completa com o ranking até 3
                    top_ativos_por_est[eid] = list(dict.fromkeys(fixos + auto))[:3]
                else:
                    top_ativos_por_est[eid] = auto
            def _med(xs):
                xs = [x for x in xs if x is not None]
                return round(sum(xs) / len(xs), 2) if xs else None
            for eid, a in acc.items():
                medias[eid] = {
                    "sharpe_medio": _med(a["sh"]),
                    "pf_medio": _med(a["pf"]),
                    "retorno_medio": _med(a["ret"]),
                    "winrate_medio": _med(a["wr"]),
                    "combos": a["n"],
                    "forte_pct": round(100 * a["forte"] / a["n"]) if a["n"] else 0,
                    "top_ativos": top_ativos_por_est.get(eid, []),
                    "melhor_combo": _MELHOR_COMBO_EST.get(eid),
                    "escada_tf": _ESCADA_EST.get(eid, {}),
                    "celulas_aprovadas": _APROV_EST.get(eid, []),
                }
        except Exception as e:
            print(f"[vitrine] erro ao agregar: {e}")

    # v6.41: fallback "mercados" dos cards também sai sem ações
    _VITRINE_ACOES_OUT = set()
    for _cat in ("Magnificent 7", "Ações Pro", "B3 — Brasil"):
        for _a in CATALOGO_ATIVOS.get(_cat, []):
            _VITRINE_ACOES_OUT.add(_a.get("nome"))
    itens = []
    for est in ESTRATEGIAS_PRONTAS:
        eid = est["id"]
        m = medias.get(eid, {})
        itens.append({
            "id": eid,
            "nome": _estrat_loc(est, lang, "nome"),
            "desc": _estrat_loc(est, lang, "desc"),
            "emoji": est.get("emoji", "📈"),
            "tags": [_tag_loc(t, lang) for t in est.get("tags", [])],
            "categoria": _categoria_de(est.get("tags", [])),
            "nivel": _nivel_loc(est.get("nivel", ""), lang),
            "mercados": [x for x in est.get("mercados", []) if x not in _VITRINE_ACOES_OUT],
            "top_ativos": ((m.get("top_ativos")
                            or [x for x in est.get("mercados", []) if x not in _VITRINE_ACOES_OUT])[:3]),
            "melhor_combo": m.get("melhor_combo"),
            "escada_tf": m.get("escada_tf", {}),
            "celulas_aprovadas": [{k: v for k, v in c.items() if not k.startswith("_")}
                                  for c in (m.get("celulas_aprovadas") or [])],
            "aprovacao": ("aprovada" if m.get("celulas_aprovadas") else
                          ("observacao" if m.get("melhor_combo") else "em_medicao")),
            "medida": bool(m.get("melhor_combo")),
            "casa": bool(est.get("casa")),
            # v7.25b — card com cor propria (medido no MT5 real) chega ao front
            "cor_destaque": est.get("cor_destaque"),
            "codigo": est.get("codigo", ""),
            "sharpe_medio": m.get("sharpe_medio"),
            "pf_medio": m.get("pf_medio"),
            "retorno_medio": m.get("retorno_medio"),
            "winrate_medio": m.get("winrate_medio"),
            "combos": m.get("combos", 0),
            "forte_pct": m.get("forte_pct", 0),
        })
        # v7.25c — CELULA REAL: card medido FORA do Yahoo (ex.: CSV do MT5 da
        # corretora) fica PREGADO na celula aprovada. O agregado do banco Yahoo
        # continua visivel no verso (honestidade), mas nao tem autoridade pra
        # trocar o ativo/TF anunciado nem o destino do botao Testar — dado de
        # corretora real vence dado aproximado. (Licao de 28/jul: o esquenta
        # mediu o card no Yahoo e o rotulo virou GBP/USD D1, celula que ninguem
        # aprovou, enquanto XAU/USD M30 PF 1.44 sumia do anuncio.)
        _cr = est.get("celula_real")
        if _cr:
            # v7.27 — celula_real pode listar mais de um ativo medido
            itens[-1]["top_ativos"] = (_cr.get("ativos") or [_cr.get("ativo")])
            itens[-1]["melhor_combo"] = {"ativo": _cr.get("ativo"),
                                         "periodo": _cr.get("periodo", "6 meses"),
                                         "timeframe": _cr.get("timeframe"),
                                         "faixa_acerto": _cr.get("faixa_acerto")}
    # v6.43: estratégias MEDIDAS (com combo positivo) primeiro; as "em medição"
    # descem pro fim da grade — a vitrine lidera com o que pode provar.
    # v7.23 — CURADORIA: aprovadas primeiro, medidas depois, em medicao no fim
    # v7.25b — destaque (medido em dado REAL do MT5) lidera; depois a curadoria normal
    itens.sort(key=lambda x: -1 if x.get("cor_destaque") else (0 if x.get("celulas_aprovadas") else (1 if x.get("medida") else 2)))
    # melhores celulas do banco inteiro (ate 6) pro topo da Vitrine — 1 clique
    melhores = []
    for _it in itens:
        for _c in (medias.get(_it["id"], {}).get("celulas_aprovadas") or []):
            melhores.append({"estrategia_id": _it["id"], "nome": _it["nome"],
                             "emoji": _it.get("emoji", ""), "ativo": _c["ativo"],
                             "tf": _c["tf"], "estrelas": _c["estrelas"],
                             "faixa": _c["faixa"], "_sh": _c.get("_sh", 0)})
    melhores.sort(key=lambda x: (x["estrelas"], x["_sh"]), reverse=True)
    for _m in melhores:
        _m.pop("_sh", None)
    out = {"total": len(itens), "estrategias": itens, "melhores_celulas": melhores[:6]}
    _VITRINE_CACHE["t"] = _t.time()
    _VITRINE_CACHE["dados"] = out
    return _vitrine_com_card_teste(out, authorization)


