                    "//| do canal EMA20 oposto. Lados espelhados. InpStopLoss = teto.     |\n"
                    "//+------------------------------------------------------------------+\n"
                    "#include <Trade\\\\Trade.mqh>\n"
                    "input long   InpMagic      = 0;\n"
                    "input double InpLote       = 0.01;\n"
                    "input int    InpStopLoss   = 150;   // TETO de desastre em pontos de preco (0 = sem teto)\n"
                    "input int    InpTakeProfit = 0;     // sem alvo por desenho: a saida e estrutural\n"
                    "input int    InpLookback   = 12;    // barras do extremo (fundo/topo)\n"
                    "input int    InpValidade   = 4;     // barras de validade do gatilho armado\n"
