                    "     }\n"
                    "  }\n"
                    "\n"
                    "// BT_STOPE_V1 nativo: nesta estrategia o stop estrutural E a regra —\n"
                    "// nasce no extremo que definiu a entrada, com folga de 0.3xATR14.\n"
                    "double BTE2Atr14()\n"
                    "  {\n"
                    "   double atr=0.0; int n=14;\n"
                    "   for(int i=1;i<=n;i++)\n"
                    "     {\n"
                    "      double h=iHigh(_Symbol,_Period,i), l=iLow(_Symbol,_Period,i);\n"
                    "      double cp=iClose(_Symbol,_Period,i+1);\n"
                    "      double tr=MathMax(h-l,MathMax(MathAbs(h-cp),MathAbs(l-cp)));\n"
                    "      atr+=tr;\n"
                    "     }\n"
                    "   return(atr/n);\n"
                    "  }\n"
                    "\n"
                    "void BTE2EmaHL(double &eh, double &el)\n"
                    "  {\n"
                    "   int n=60; double k=2.0/21.0;\n"
                    "   eh=iHigh(_Symbol,_Period,n); el=iLow(_Symbol,_Period,n);\n"
                    "   for(int i=n-1;i>=1;i--)\n"
                    "     {\n"
                    "      eh=iHigh(_Symbol,_Period,i)*k+eh*(1.0-k);\n"
                    "      el=iLow(_Symbol,_Period,i)*k+el*(1.0-k);\n"
                    "     }\n"
                    "  }\n"
                    "\n"
                    "void OnTick()\n"
                    "  {\n"
                    "   // ── DISPARO NO TICK (rompimento intrabarra do gatilho armado) ──\n"
