                    "         if(slv>bid) trade.Sell(InpLote,_Symbol,0.0,slv,0.0,\"BT E2 topo rompido\");\n"
                    "         btE2Dir=0;\n"
                    "        }\n"
                    "     }\n"
                    "   // ── DECISOES DE BARRA FECHADA ──\n"
