                    "      bool temBuy=false, temSell=false;\n"
                    "      for(int i=PositionsTotal()-1;i>=0;i--)\n"
                    "        {\n"
                    "         ulong tk=PositionGetTicket(i);\n"
                    "         if(tk>0 && PositionGetString(POSITION_SYMBOL)==_Symbol\n"
                    "            && PositionGetInteger(POSITION_MAGIC)==InpMagic)\n"
                    "           {\n"
                    "            if((int)PositionGetInteger(POSITION_TYPE)==POSITION_TYPE_BUY) temBuy=true;\n"
                    "            else temSell=true;\n"
                    "           }\n"
                    "        }\n"
                    "      if(temBuy && c1<el)  BTE2FecharTudo();\n"
                    "      if(temSell && c1>eh) BTE2FecharTudo();\n"
                    "      return;   // com posicao nao arma gatilho novo\n"
                    "     }\n"
                    "   // validade do gatilho armado\n"
                    "   if(btE2Dir!=0)\n"
                    "     {\n"
                    "      btE2Val--;\n"
                    "      if(btE2Val<=0) btE2Dir=0;\n"
                    "     }\n"
                    "   // arma: a barra fechada [1] e o extremo das ultimas InpLookback?\n"
                    "   double atr=BTE2Atr14();\n"
