class MT5VeredictoReq(BaseModel):
    bot_token: str = ""
    job_id: str = ""
    aprovado: bool = False
    log: str = ""


# ── C27R10 — /mt5/veredito AUTENTICADO E IMUTAVEL ───────────────────────────
# Defeito (auditoria do dono sobre a C27R9): a rota nao tinha autenticacao e
# ignorava bot_token — conhecer um job_id bastava pra aprovar (ou reprovar) o
# job, reescrever um veredito final e marcar mq5_cache.aprovado, fazendo os
# proximos envios do MESMO codigo pularem o compile real (pre_validado).
# AGORA, antes de QUALQUER escrita:
#  (1) o conector se autentica pelo bot_token do CORPO; ausente, errado, de
#      outro bot ou job inexistente = MESMA resposta 403 {veredito_recusado,
#      BT-V01}, byte-identica (sem oraculo de existencia de job/token);
#  (2) o servidor confere que o token pertence ao bot DO job: mt5_jobs.
#      bot_token == token do corpo (hmac.compare_digest) E existe bot vivo
#      (nao excluido) em conector_bots com esse token;
#  (3) veredito FINAL e imutavel: UPDATE condicional atomico
#      (job_id + bot_token + status='validando'); 0 linhas afetadas = 409
#      veredito_final_imutavel (replay, reaprovacao ou tentativa de trocar
#      aprovado<->reprovado) — nada e reescrito;
#  (4) mq5_cache so e marcado aprovado pela chamada que VENCEU o update
#      condicional com aprovado=True. Recusa nunca toca mt5_jobs/mq5_cache.
_VEREDITO_RECUSADO = {"ok": False, "erro": "veredito_recusado", "codigo": "BT-V01"}


@app.post("/mt5/veredito")
def mt5_veredito(req: MT5VeredictoReq):
    tok = (req.bot_token or "").strip()
    jid = (req.job_id or "").strip()
    if not tok or not jid:
        return JSONResponse(status_code=403, content=dict(_VEREDITO_RECUSADO))
    j = _mt5_job_buscar(jid)   # v6.65: Supabase — o veredito pode cair
    #                            em OUTRO worker que nao criou o job
    try:
        dono_ok = bool(j) and _hmac.compare_digest(str(j.get("bot_token") or ""), tok)
    except Exception:
        dono_ok = False
    sb = _sb_admin() if dono_ok else None
    if dono_ok and sb is None:
        return JSONResponse(status_code=503, content={"ok": False, "erro": "supabase_indisponivel"})
    if dono_ok:
        try:
            _bv = (sb.table("conector_bots").select("bot_token,excluido")
                   .eq("bot_token", tok).limit(2).execute().data or [])
            dono_ok = any(_hmac.compare_digest(str(b.get("bot_token") or ""), tok)
                          and not b.get("excluido") for b in _bv)
        except Exception:
            dono_ok = False
    if not dono_ok:
        return JSONResponse(status_code=403, content=dict(_VEREDITO_RECUSADO))
    try:
        r = (sb.table("mt5_jobs").update({
                "status": "aprovado" if req.aprovado else "reprovado",
                "aprovado": bool(req.aprovado),
                "log": (req.log or "")[:4000],
                "atualizado_em": _dt.now(_tz.utc).isoformat(),
            }).eq("job_id", jid).eq("bot_token", tok).eq("status", "validando")
            .execute())
        venceu = len(r.data or []) == 1
    except Exception as _e:
        try: print(f"[mt5-jobs] veredito update falhou: {_e}")
        except Exception: pass
        return JSONResponse(status_code=503, content={"ok": False, "erro": "update_falhou"})
    if not venceu:
        return JSONResponse(status_code=409, content={
            "ok": False, "erro": "veredito_final_imutavel", "codigo": "BT-V02"})
    # v6.38: aprovou no MT5 real -> marca o cache; próximos envios do MESMO
    # código pulam a IA E o compile (pré-validado, veredito na hora).
    # C27R10: so a chamada vencedora do update condicional chega aqui.
    try:
        if req.aprovado and j.get("gen_hash"):
            _mq5_cache_aprovar(j["gen_hash"])
    except Exception:
        pass
    return {"ok": True}


@app.get("/mt5/status")
def mt5_status(job_id: str = "", authorization: str = Header(default="")):
    """R2 P2 — status do job SO pro dono provado pela sessao. A URL carrega
    apenas job_id (nenhum segredo em query string); a propriedade e provada
    pela cadeia mt5_jobs.bot_token -> conector_bots.bot_token -> user_id da
    sessao. Job inexistente e job de outro usuario respondem IDENTICO."""
    uid = _sessao_user_id(authorization)   # 401 sem sessao valida
    j = _mt5_job_buscar(job_id)   # v6.65: Supabase — o modal do front pode
    if not j or not _mt5_job_do_usuario(j, uid):   # cair em qualquer worker
        return {"status": "desconhecido"}
    out = {"status": j.get("status"), "aprovado": j.get("aprovado"),
           "log": j.get("log") or ""}
    # v6.83 — CÓDIGO DO MOTIVO: reprovação sai com BT-xx + resumo do erro
    if j.get("status") == "reprovado":
        out.update(_classificar_reprovacao(j.get("log") or ""))
    return out


# ── AQUECIMENTO DE FÁBRICA (v6.39) ─────────────────────────────────────────
# Gera o .mq5 de TODAS as estratégias prontas UMA vez (sl/tp padrão 60/120) e
# guarda no cache persistente. Depois do aquecimento + 1 rodada de aprovação
# no MT5 (o admin envia cada uma 1x), NENHUM usuário paga a IA nem o compile:
# a vitrine inteira valida em ~5-10s pra sempre. Admin-only, roda em background
# (14 estratégias x ~20-40s de IA = alguns minutos; o status mostra o progresso).
_MQ5_AQUECER = {"rodando": False, "feitas": 0, "total": 0, "erros": [], "inicio": 0.0}


def _mq5_aquecer_worker():
    try:
        alvos = [e for e in ESTRATEGIAS_PRONTAS if (e.get("codigo") or "").strip()]
        _MQ5_AQUECER.update(rodando=True, feitas=0, total=len(alvos),
                            erros=[], inicio=_time_mt5.time())
        for est in alvos:
            cod = est["codigo"]
            h = _mq5_hash_geracao(cod, 60, 120)
            hit = _mq5_cache_buscar(h)
            if hit and hit.get("mq5"):
                # v6.95 — AQUECEDOR CIENTE DO UPGRADE DE FROTA: entrada sem o
                # marcador BT_EVT_V2 seria DESCARTADA pelo /mt5/enviar no HIT
                # (v6.89); pular aqui deixaria o espelho FALSAMENTE quente.
                # Mesmo tratamento do envio: apaga e regenera com o template
                # atual — o aquecedor sempre entrega cache que o envio aceita.
                if "BT_EVT_V2" in (hit.get("mq5") or "") and "BT_DISCIPLINA_V3" in (hit.get("mq5") or ""):
                    _MQ5_AQUECER["feitas"] += 1
                    print(f"[mq5-aquecer] {est.get('id')} já no cache ({h[:10]})")
                    continue
                _mq5_cache_apagar(h)
                print(f"[mq5-aquecer] {est.get('id')} pré-BT_EVT_V2/BT_DISCIPLINA_V3 no cache — regenerando")
            mq5 = _gerar_mq5_de_codigo(cod, {"ativo": "", "stop_loss": 60,
                                             "take_profit": 120, "magic": 0})
            if not mq5:
                _MQ5_AQUECER["erros"].append(est.get("id") or "?")
                print(f"[mq5-aquecer] FALHOU {est.get('id')}")
            else:
                # v6.95 — SANIDADE NO AQUECEDOR: geração reprovada na sentinela
                # não pode ficar "quente" (viraria BT-G01 pro primeiro usuário).
                _ok_aq, _ln_aq, _tr_aq = _mq5_sanidade(mq5)
                if not _ok_aq:
                    _mq5_cache_apagar(h)
                    _MQ5_AQUECER["erros"].append(f"{est.get('id')} (sentinela linha {_ln_aq})")
                    print(f"[mq5-aquecer] SENTINELA reprovou {est.get('id')} linha {_ln_aq} — cache limpo")
                else:
                    print(f"[mq5-aquecer] gerado {est.get('id')} ({h[:10]})")
            _MQ5_AQUECER["feitas"] += 1
    except Exception as _e:
        try: _MQ5_AQUECER["erros"].append(f"worker: {_e}")
        except Exception: pass
    finally:
        _MQ5_AQUECER["rodando"] = False


@app.delete("/admin/mq5/invalidar")
def admin_mq5_invalidar(estrategia_id: str = "", authorization: str = Header(default="")):
    """v6.54 — INVALIDAR CACHE DE UMA ESTRATÉGIA. Remove o .mq5 cacheado
    (memória + Supabase) da estratégia indicada; o próximo envio dela regenera
    do zero com o PROMPT ATUAL, herdando os campos ricos do snapshot (zonas,
    regime, offmind, lucro, tfop). Admin-only. Uso pro loop de fechamento:
    identificamos que os EAs atuais no MT5 emitem snapshot esqueleto — cache
    foi feito antes da v6.36. Invalidar + reenviar 1 bot = teste do loop.

    B10-A: sessão do admin (Authorization: Bearer) — o token de query morreu.
    curl -X DELETE -H 'Authorization: Bearer <access_token_da_sessao_admin>' 'https://.../admin/mq5/invalidar?estrategia_id=tripla_media_9_21_50'
    """
    _sessao_admin_uid(authorization)
    eid = (estrategia_id or "").strip()
    if not eid:
        raise HTTPException(status_code=400, detail="estrategia_id obrigatório")
    est = next((e for e in ESTRATEGIAS_PRONTAS if e.get("id") == eid), None)
    if est is None:
        raise HTTPException(status_code=404, detail=f"estratégia '{eid}' não existe")
    codigo = (est.get("codigo") or "").strip()
    if not codigo:
        raise HTTPException(status_code=400, detail="estratégia sem código")
    gen_hash = _mq5_hash_geracao(codigo)
    # v6.65: só existe UMA camada (Supabase). DELETE aqui = cache morto de
    # verdade, em todos os workers, sem restart — fim do ritual DELETE+RESTART.
    removidos = {"supabase": False}
    try:
        sb = _sb_admin()
        if sb is not None:
            r = sb.table("mq5_cache").delete().eq("gen_hash", gen_hash).execute()
            removidos["supabase"] = bool(r.data)
    except Exception as e:
        return {"ok": True, "estrategia_id": eid, "hash": gen_hash[:10],
                "removidos": removidos, "aviso": f"supabase: {e}"}
    return {"ok": True, "estrategia_id": eid, "hash": gen_hash[:10],
            "removidos": removidos,
            "proximo_passo": "reenvie um bot com esta estratégia — a IA regenera com o prompt novo"}


@app.post("/admin/mq5/aquecer")
def admin_mq5_aquecer(authorization: str = Header(default="")):
    """Dispara o aquecimento em background. Chame 1x após o deploy; acompanhe
    em GET /admin/mq5/cache. Idempotente: estratégia já cacheada é pulada.
    B10-A: sessão do admin — o token de query morreu."""
    _sessao_admin_uid(authorization)
    if _MQ5_AQUECER["rodando"]:
        return {"ok": False, "erro": "ja_rodando", **{k: _MQ5_AQUECER[k] for k in ("feitas", "total")}}
    import threading as _th
    _th.Thread(target=_mq5_aquecer_worker, daemon=True).start()
    return {"ok": True, "msg": "aquecimento iniciado em background",
            "estrategias": len([e for e in ESTRATEGIAS_PRONTAS if (e.get("codigo") or "").strip()])}


@app.get("/admin/mq5/cache")
def admin_mq5_cache(authorization: str = Header(default="")):
    """Estado do cache de geração: progresso do aquecimento + contagem no
    Supabase (única camada desde a v6.65). B10-A: sessão do admin — o token
    de query morreu."""
    _sessao_admin_uid(authorization)
    db = {"total": None, "aprovados": None}
    try:
        sb = _sb_admin()
        if sb is not None:
            r = sb.table("mq5_cache").select("gen_hash,aprovado").execute()
            rows = r.data or []
            db = {"total": len(rows),
                  "aprovados": sum(1 for x in rows if x.get("aprovado"))}
    except Exception as _e:
        db = {"erro": str(_e)[:120]}
    # mapa estratégia -> hash/estado (pra conferir a vitrine de relance)
    vitrine = []
    for est in ESTRATEGIAS_PRONTAS:
        cod = (est.get("codigo") or "").strip()
        if not cod:
            continue
        h = _mq5_hash_geracao(cod, 60, 120)
        e = _mq5_cache_buscar(h)
        vitrine.append({"id": est.get("id"), "hash": h[:10],
                        "cacheado": bool(e), "aprovado": bool(e and e.get("aprovado"))})
    return {"aquecimento": dict(_MQ5_AQUECER),
            "memoria": "removida na v6.65 — Supabase é a única camada",
            "supabase": db, "vitrine": vitrine}


