_CLM_FONTE_SCAN = "servidor · _scanner_multitf (últimas 5 velas do snapshot, INCLUI a barra em formação)"


def _clm_tok(t):
    t = str(t or "").strip()
    if not t:
        return None, ""
    return t[0], t[1:]


def _clm_cvmap(det):
    out = {}
    for chave, ordem in (("cv1", _CLM_CV1), ("cv2", _CLM_CV2)):
        partes = str((det or {}).get(chave) or "").split(".")
        if len(partes) == len(ordem):
            for tf, p in zip(ordem, partes):
                out[tf] = p
    return out


def _clm_int(v):
    try:
        return int(str(v).strip())
    except (TypeError, ValueError):
        return None


def _clm_relogio(det):
    """Horários da corretora → UTC com o fuso ATUAL da corretora (tsrv − tgmt,
    arredondado ao minuto). Devolve {fech, form, off, tgmt}: abertura (UTC) da
    barra fechada (shift 1) e da barra em formação (shift 0, EA ≥ 7.81)."""
    det = det or {}
    tsrv, tgmt = _clm_int(det.get("tsrv")), _clm_int(det.get("tgmt"))
    off = (tsrv - tgmt) if (tsrv and tgmt) else None
    if off is not None:
        off = int(round(off / 60.0)) * 60
    def _ler(chave):
        out = {}
        partes = str(det.get(chave) or "").split(".")
        if len(partes) == len(_CLM_CVT_ORDEM) and off is not None:
            for tf, p in zip(_CLM_CVT_ORDEM, partes):
                v = _clm_int(p)
                out[tf] = (v - off) if (v and v > 0) else None
        return out
    return {"fech": _ler("cvt"), "form": _ler("cvt0"), "off": off, "tgmt": tgmt}


def _clm_iso(epoch):
    if epoch is None:
        return None
    return _dt.fromtimestamp(int(epoch), _tz.utc).isoformat()


def _clm_fim_barra(tf, abertura_utc, off):
    """Instante (UTC) em que a barra que abriu em abertura_utc FECHA. MN1 usa o
    calendário da corretora (1º dia do mês seguinte, 00:00 na hora dela)."""
    if abertura_utc is None:
        return None
    seg = _CLM_SEG.get(tf)
    if seg:
        return abertura_utc + seg
    if tf == "MN1" and off is not None:
        b = _dt.fromtimestamp(abertura_utc + off, _tz.utc)
        prox = b.replace(year=b.year + (1 if b.month == 12 else 0),
                         month=1 if b.month == 12 else b.month + 1, day=1,
                         hour=0, minute=0, second=0, microsecond=0)
        return int(prox.timestamp()) - off
    return None


def _clm_rotulo_corretora(tf, abertura_utc, off):
    if abertura_utc is None or off is None or tf not in ("D1", "W1", "MN1"):
        return None
    b = _dt.fromtimestamp(abertura_utc + off, _tz.utc)
    fz = f"UTC{'+' if off >= 0 else '−'}{abs(off) // 3600}"
    if tf == "D1":
        return f"dia {b:%d/%m/%Y} da corretora ({fz})"
    if tf == "W1":
        return f"semana iniciada {b:%d/%m/%Y} na corretora ({fz})"
    return f"mês {b:%m/%Y} da corretora ({fz})"


def _clm_fechadas(cs):
    return cs[:-1] if len(cs) > 1 else []          # última vela do snapshot = barra em formação


def _clm_range_medio(cs):
    ult = _clm_fechadas(cs)[-14:]
    if len(ult) < 5:
        return None
    return sum(v["h"] - v["l"] for v in ult) / len(ult)


def _clm_forca(cs):
    """Contrato EXISTENTE _sinal_forca (camada top-down): direção + intensidade
    0..1 das últimas 10 barras FECHADAS (corpo ≥ 55% do range). Sem 11 barras
    fechadas = não calculado (nunca zero inventado)."""
    fech = _clm_fechadas(cs)
    if len(fech) < 11:
        return None
    try:
        import pandas as _pd_clm
        df = _pd_clm.DataFrame([{"Open": v["o"], "High": v["h"], "Low": v["l"], "Close": v["c"]} for v in fech])
        d, f = _sinal_forca(df)
        return {"direcao": d, "valor": round(float(f), 2),
                "fonte": "contrato _sinal_forca: barras de corpo ≥ 55% nas 10 fechadas"}
    except Exception:
        return None


def _clm_niveis_candles(cs):
    fech = _clm_fechadas(cs)
    if len(fech) < 7:
        return []
    try:
        topos, fundos = _detectar_topos_fundos(fech)
    except Exception:
        return []
    out = []
    for tipo, lst in (("topo", topos), ("fundo", fundos)):
        if lst:                                   # lista vem do mais recente p/ o mais antigo
            out.append({"tipo": tipo, "nivel": lst[0].get("preco"), "velas_atras": lst[0].get("velas_atras"),
                        "fonte": "_detectar_topos_fundos (velas fechadas do snapshot)"})
    return out


def _clm_m15_hist(det, off):
    """Aberturas (UTC) das últimas barras M15 FECHADAS que a corretora TEVE."""
    raw = str((det or {}).get("m15h") or "")
    if not raw or off is None:
        return None
    partes = raw.split(",")
    t = _clm_int(partes[0])
    if not t:
        return None
    out = [t - off]
    for d in partes[1:]:
        k = _clm_int(d)
        if not k or k <= 0:
            break
        t -= k * 900
        out.append(t - off)
    return out


def _clm_leituras(det, agora_ts, scanner=None):
    """Monta a leitura por TF SÓ com o que existe. Nada ausente vira zero."""
    det = det or {}
    cv = _clm_cvmap(det)
    rel = _clm_relogio(det)
    fechs, forms, off, tgmt = rel["fech"], rel["form"], rel["off"], rel["tgmt"]
    scan = {}
    for it in (scanner if scanner is not None else (_scanner_multitf(det) or [])):
        scan[str(it.get("tf"))] = it
    om = det.get("offmind") or {}
    niveis_om = {}
    for n in (om.get("estrutura") or []):
        niveis_om.setdefault(str(n.get("tf") or "").lower(), []).append(
            {"tipo": n.get("tipo"), "nivel": n.get("nivel"), "toques": n.get("toques"),
             "testando": n.get("testando"), "fonte": "OffMind (servidor)"})
    idade_snap = (agora_ts - tgmt) if tgmt else None
    try:
        preco = float(det.get("preco")) if det.get("preco") not in (None, "") else None
    except (TypeError, ValueError):
        preco = None
    spread_pts, ponto = _clm_int(det.get("spr")), None
    try:
        ponto = float(det.get("pt")) if det.get("pt") not in (None, "") else None
    except (TypeError, ValueError):
        ponto = None
    linhas = []
    for tf in _CLM_ORDEM:
        ciclo, papel = _CLM_PAPEL[tf]
        tok = cv.get(tf)
        letra, flags = _clm_tok(tok)
        ab = fechs.get(tf)
        fim = _clm_fim_barra(tf, ab, off)
        form = forms.get(tf)
        if letra is None:
            res, regra, razao = "indisponivel", "COLETA.ausente", "leitura não coletada neste snapshot"
        else:
            res, regra, razao = _CLM_REGRA.get(letra, ("indisponivel", "BTCVTF.desconhecido",
                                                       f"símbolo de leitura desconhecido ({letra})"))
        estrutura = None
        if letra is not None and letra != "?":
            estrutura = {"rompimento": "!" in flags, "rompimento_iminente": "^" in flags,
                         "exaustao": "x" in flags,
                         "compressao": None, "pullback": None, "reversao": None, "canal_ott": None}
            extras = []
            if estrutura["rompimento"]:
                extras.append("rompeu o extremo das 20 barras fechadas (BTCVTF.!)")
            if estrutura["rompimento_iminente"]:
                extras.append("rompimento iminente, preço ≤ 0,3×ATR14 do extremo (BTCVTF.^, usa a barra em formação)")
            if estrutura["exaustao"]:
                extras.append("barra de exaustão: range ≥ 2× a média de 10, corpo ≤ 35% (BTCVTF.x)")
            if extras:
                razao = razao + "; " + "; ".join(extras)
        idade_fech = (agora_ts - fim) if fim is not None else None
        em_form = (agora_ts - form) if form is not None else None
        if letra is None:
            estado = "ausente"
        elif letra == "?":
            estado = "indisponivel"
        elif ab is None:
            estado = "sem_carimbo"
        elif (idade_snap is not None and idade_snap > 90):
            estado = "atrasado"
        elif form is not None and fim is not None and form < fim - 60:
            estado = "inconsistente"          # barra em formação abriu antes de a fechada terminar
        else:
            estado = "atual"
        zk = _CLM_ZONA.get(tf)
        zona = str(det.get(zk)).strip().lower() if (zk and det.get(zk) not in (None, "")) else None
        if zona == "?":
            zona = None
        sc = scan.get(_CLM_SCAN.get(tf, "_"))
        ck = _CLM_CAND.get(tf)
        cs = _parse_candles_para_lista(det.get(ck)) if ck else []
        vol = _clm_range_medio(cs) if cs else None
        niv = niveis_om.get(_CLM_SCAN.get(tf, "_").lower(), []) or (_clm_niveis_candles(cs) if cs else [])
        linha = {
            "tf": tf, "ciclo": ciclo, "papel": papel,
            "barra_fechada_abertura_utc": _clm_iso(ab),
            "barra_fechada_fim_utc": _clm_iso(fim),
            "barra_formacao_abertura_utc": _clm_iso(form),
            "barra_corretora": _clm_rotulo_corretora(tf, ab, off),
            "leitura_utc": _clm_iso(tgmt),
            "idade_snapshot_s": idade_snap,
            "idade_barra_fechada_s": idade_fech,
            "tempo_em_formacao_s": em_form,
            # compat. clm-1
            "barra_fechada_utc": _clm_iso(ab), "barra_formacao_desde_utc": _clm_iso(form or fim),
            "idade_dado_s": idade_snap,
            "direcao": _CLM_DIR.get(letra, "indefinida") if letra else "indefinida",
            "direcao_fonte": _CLM_FONTE_EA if letra else None,
            "tendencia": (sc or {}).get("comportamento"),
            "tendencia_fonte": _CLM_FONTE_SCAN if sc else None,
            "forca": _clm_forca(cs) if cs else None,
            "ranking": None,                     # nenhum contrato do motor define ranking por TF
            "estrutura": estrutura,
            "canal_ema20": zona,
            "posicao_preco": ({"acima": "acima do canal EMA20 H/L", "abaixo": "abaixo do canal EMA20 H/L",
                               "dentro": "dentro do canal EMA20 H/L"}.get(zona) if zona else None),
            "volatilidade_range_medio": (round(vol, 6) if vol is not None else None),
            "niveis": niv,
            "resultado": res, "regra": regra, "razao": razao,
            "estado_dado": estado,
            "fonte": (_CLM_FONTE_EA if letra else "não coletado"),
            "bruto": {"token": tok, "zona": det.get(zk) if zk else None,
                      "abertura_fechada_corretora": (ab + off) if (ab is not None and off is not None) else None,
                      "abertura_formacao_corretora": (form + off) if (form is not None and off is not None) else None,
                      "offset_corretora_s": off, "velas_snapshot": len(cs) if cs else 0,
                      "scanner": sc},
        }
        if tf == "M15":
            linha["referencia_decisao"] = True
        linhas.append(linha)
    m15_ab = fechs.get("M15")
    return {"linhas": linhas, "offset_corretora_s": off, "leitura_utc": _clm_iso(tgmt),
            "idade_snapshot_s": idade_snap, "idade_dado_s": idade_snap, "preco": preco,
            "spread": ({"pontos": spread_pts, "preco": round(spread_pts * ponto, 8)}
                       if (spread_pts is not None and ponto) else None),
            "eav": det.get("eav"), "tfop": det.get("tfop"),
            "nota_utc": (f"horários da corretora convertidos com o fuso atual dela (UTC{'+' if off >= 0 else '−'}{abs(off) // 3600}); "
                         "barras W1/MN1 abertas antes de uma troca de horário de verão podem diferir 1h"
                         if off is not None else "fuso da corretora não informado (EA < v7.80)"),
            "m15_hist_utc": _clm_m15_hist(det, off),
            # convenção da AUTORIDADE (atestado/ciclo_decisoes.ts_barra): o INSTANTE em que a
            # barra M15 de referência FECHOU
            "barra_m15_utc": _clm_iso(m15_ab + 900) if m15_ab else None}


def _clm_resumo_ciclos(leit):
    por = {l["tf"]: l for l in leit.get("linhas") or []}
    def _d(tf):
        tok = ((por.get(tf) or {}).get("bruto") or {}).get("token")
        l, _ = _clm_tok(tok)
        return l
    def _txt(tfs):
        return " · ".join(f"{tf} {_CLM_DIR.get(_d(tf), 'não coletado') if _d(tf) else 'não coletado'}" for tf in tfs)
    # Ciclo 1 — ascendente M1 → M5 → M15 (M30/H1 informativos)
    c1 = [(tf, _d(tf)) for tf in ("M1", "M5", "M15")]
    base = c1[0][1]
    calc1 = all(l in ("U", "D", "L") for _, l in c1)
    etapa = []
    if base in ("U", "D"):
        for tf, l in c1:
            if l == base:
                etapa.append(tf)
            else:
                break
    div1 = [f"{a} {_CLM_DIR[la]} × {b} {_CLM_DIR[lb]}" for (a, la), (b, lb) in zip(c1, c1[1:])
            if la in ("U", "D") and lb in ("U", "D") and la != lb]
    al1 = calc1 and all(l == base for _, l in c1) and base in ("U", "D")
    if not calc1:
        et1 = "não calculado: leitura ausente em " + ", ".join(tf for tf, l in c1 if l not in ("U", "D", "L"))
    elif not etapa:
        et1 = f"escada não começa: M1 {_CLM_DIR.get(base, '—')} (a subida exige M1 com direção)"
    else:
        et1 = " → ".join(etapa) + (" (completo)" if len(etapa) == 3 else f" (parou em {c1[len(etapa)][0]} {_CLM_DIR.get(c1[len(etapa)][1], '—')})")
    ciclo1 = {"ordem": "M1 → M5 → M15", "leituras": {tf: l for tf, l in c1},
              "leituras_txt": _txt(("M1", "M5", "M15")),
              "extras": {"M30": _d("M30"), "H1": _d("H1")},
              "calculado": calc1, "etapa": et1,
              "alinhado": al1, "direcao": _CLM_DIR.get(base) if al1 else None,
              "divergencias": div1, "criterio": "mesma letra BTCVTF (U/D) do M1 até o M15, subindo",
              "fonte": "leitura do EA (BTvCicloTF) — descritiva, NÃO é autoridade"}
    # Ciclo 2 — descendente D1 → H4 (W1/MN1 informativos)
    d1, h4 = _d("D1"), _d("H4")
    calc2 = d1 in ("U", "D", "L") and h4 in ("U", "D", "L")
    al2 = calc2 and d1 in ("U", "D") and d1 == h4
    div2 = [f"D1 {_CLM_DIR[d1]} × H4 {_CLM_DIR[h4]}"] if (d1 in ("U", "D") and h4 in ("U", "D") and d1 != h4) else []
    if not calc2:
        et2 = "não calculado: leitura ausente em " + ", ".join(tf for tf, l in (("D1", d1), ("H4", h4)) if l not in ("U", "D", "L"))
    elif al2:
        et2 = f"D1 → H4 alinhados em {_CLM_DIR[d1]}"
    elif div2:
        et2 = f"D1 → H4 divergentes ({div2[0]})"
    elif d1 == "L" and h4 == "L":
        et2 = "D1 lateral · H4 lateral — sem direção de referência"
    else:
        et2 = f"D1 {_CLM_DIR.get(d1)} · H4 {_CLM_DIR.get(h4)} — referência incompleta (um dos dois lateral)"
    ciclo2 = {"ordem": "D1 → H4", "leituras": {"D1": d1, "H4": h4},
              "leituras_txt": _txt(("D1", "H4")),
              "extras": {"MN1": _d("MN1"), "W1": _d("W1")},
              "calculado": calc2, "etapa": et2,
              "alinhado": al2, "direcao": _CLM_DIR.get(d1) if al2 else None,
              "divergencias": div2, "criterio": "D1 e H4 com a mesma letra BTCVTF (U/D)",
              "fonte": "leitura do EA (BTvCicloTF) — descritiva, NÃO é autoridade"}
    faltam = [tf for tf in _CLM_OBRIGATORIOS if (por.get(tf) or {}).get("estado_dado") in
              ("ausente", "indisponivel", None)]
    if not leit.get("barra_m15_utc"):
        faltam.append("carimbo da barra M15 (EA < v7.80)")
    return ciclo1, ciclo2, faltam


_CLM_MOTOR_ELOS = (
    ("1. processo do motor (leitor no PC)", ("nao_configurado", "processo_parado", "motor_com_erro")),
    ("2. espelho · barra lida pelo motor", ("espelho_ausente", "espelho_atrasado", "espelho_adiantado",
                                            "barra_indisponivel", "leitura_antiga")),
    ("3. identidade (conta · símbolo · instalação · OHLC)", ("identidade_divergente", "snapshot_invalido")),
    ("4. fuso corretora→UTC (EA × motor)", ("fuso_indisponivel", "fuso_divergente")),
    ("5. assinatura no conector (BT_CV_SEGREDO do PC)", ("segredo_ausente", "token_ausente",
                                                        "assinatura_recusada")),
)


def _clm_motor_compacto(det):
    m = (det or {}).get("cv_motor")
    if not isinstance(m, dict):
        return None
    return {k: v for k, v in m.items() if k != "candidatos"}   # C27R19: candidatos ficam em selecao_avaliacoes


def _clm_elos(det, info, leit):
    """Cada elo da cadeia motor → espelho → identidade → fuso → assinatura →
    segredo da API → verificação → barra UTC, avaliado SEPARADAMENTE: a tela diz
    qual elo falhou (processo parado, espelho atrasado, atestado ausente…)."""
    det = det or {}
    at_raw = det.get("cv_atestado") if isinstance(det.get("cv_atestado"), dict) else None
    falha_con = det.get("cv_atestado_falha")
    con = str(det.get("conector_versao") or "")
    mot = _clm_motor_compacto(det)
    elos = []
    if mot is None:
        motivo = (f"ponte antiga do conector: {falha_con}" if falha_con else
                  f"conector sem ponte do motor ({con or 'versão não informada'}) — não envia saúde do motor nem cv_atestado")
        if at_raw:
            elos.append({"elo": _CLM_MOTOR_ELOS[0][0], "estado": "sem_dado",
                         "motivo": "atestado anexado por conector sem telemetria do motor"})
        else:
            elos.append({"elo": _CLM_MOTOR_ELOS[0][0], "estado": "falha", "motivo": motivo})
        for nome, _ in _CLM_MOTOR_ELOS[1:]:
            elos.append({"elo": nome, "estado": "nao_avaliado", "motivo": "sem telemetria do motor"})
    else:
        est = mot.get("estado")
        idx = next((k for k, (_n, ests) in enumerate(_CLM_MOTOR_ELOS) if est in ests), None)
        if est == "ok":
            idx = len(_CLM_MOTOR_ELOS)
        elif idx is None:
            idx = 0
        detalhes = [
            f"pid {mot.get('pid')} · batimento há {mot.get('heartbeat_idade_s')}s · leitor {mot.get('leitor')}",
            f"barra do motor {mot.get('barra_motor_corretora')} (corretora) · publicada há {mot.get('publicado_idade_s')}s",
            f"conta {mot.get('login')} {'DEMO' if mot.get('conta_demo') else 'NÃO-DEMO'} = EA {mot.get('conta_ea')} · "
            f"instalação {'confere' if mot.get('instalacao_confere') else ('não conferida' if mot.get('instalacao_confere') is None else 'DIVERGE')} · "
            f"OHLC {'confere' if mot.get('ohlc_confere') else ('não conferido' if mot.get('ohlc_confere') is None else 'DIVERGE')}",
            f"EA {mot.get('off_ea_s')}s · motor {mot.get('off_motor_s')}s ({mot.get('off_motor_fonte')})",
            "atestado assinado nesta barra" + (" (cache)" if mot.get("cache") else ""),
        ]
        for k, (nome, _e) in enumerate(_CLM_MOTOR_ELOS):
            if k < idx:
                elos.append({"elo": nome, "estado": "ok", "motivo": detalhes[k]})
            elif k == idx:
                elos.append({"elo": nome, "estado": "falha", "motivo": f"{est}: {mot.get('motivo')}"})
            else:
                elos.append({"elo": nome, "estado": "nao_avaliado", "motivo": "elo anterior falhou"})
    seg = bool(os.environ.get("BT_CV_SEGREDO"))
    elos.append({"elo": "6. segredo na API (BT_CV_SEGREDO)", "estado": "ok" if seg else "falha",
                 "motivo": "configurado" if seg else "ausente no servidor — nenhum atestado pode ser verificado"})
    if at_raw or info.get("estado") == "verificado":
        ver = {"estado": "ok" if info.get("estado") == "verificado" else "falha",
               "motivo": info.get("motivo") or "verificado (HMAC, bot, símbolo, magic, barra fechada, validade 900s)"}
    else:
        ver = {"estado": "nao_avaliado" if mot and mot.get("estado") != "ok" else "falha",
               "motivo": info.get("motivo") or "sem atestado"}
    elos.append({"elo": "7. verificação na API (HMAC · bot · símbolo · magic · validade)", **ver})
    utc = {"estado": "sem_dado", "motivo": "sem atestado para comparar"}
    if at_raw and leit.get("barra_m15_utc"):
        try:
            a = _dt.fromisoformat(str(at_raw.get("ts_barra_m15")).replace("Z", "+00:00"))
            if a.tzinfo is None:
                a = a.replace(tzinfo=_tz.utc)
            b = _dt.fromisoformat(leit["barra_m15_utc"])
            dif = int((a - b).total_seconds())
            utc = {"estado": "ok" if dif == 0 else "falha",
                   "motivo": ("barra do atestado (fechamento) == barra M15 fechada do EA, em UTC" if dif == 0 else
                              f"barra do atestado difere {dif:+d}s da barra do EA (conversão corretora↔UTC)"),
                   "atestado": a.isoformat(), "ea": b.isoformat()}
        except Exception as _e:
            utc = {"estado": "falha", "motivo": f"ts_barra_m15 do atestado ilegível ({_e})"}
    elos.append({"elo": "8. barra do atestado × barra do EA (UTC)", **utc})
    return elos


def _clm_autoridade(sb, bot):
    """A MESMA verificação do emissor R-CICLO-01, read-only. Nunca expõe o
    segredo nem a assinatura inteira."""
    at, ts, falha = _r01_ler_ciclos_servidor(sb, bot)
    info = {"estado": "verificado" if at else "recusado", "motivo": falha,
            "bot_id": bot.get("id"), "simbolo": bot.get("simbolo")}
    if at:
        from datetime import timedelta as _tdclm
        info.update({
            "magic": at.get("magic"), "ts_barra_m15": ts.isoformat() if ts else None,
            "valido_ate": (ts + _tdclm(seconds=_R01_DEC_TTL_S)).isoformat() if ts else None,
            "versao_motor": at.get("versao_motor"),
            "cv1": {"veredito": (at.get("cv1") or {}).get("veredito"),
                    "janela": (at.get("cv1") or {}).get("janela"),
                    "motivo": (at.get("cv1") or {}).get("motivo")},
            "cv2": {"dirs": (at.get("cv2") or {}).get("dirs")},
            "assinatura": (str(at.get("assinatura") or "")[:8] + "…") if at.get("assinatura") else None,
        })
    return at, ts, info


_CLM_CLASSE_VETO = {
    "CLM.leitura_obrigatoria": "leitura incompleta (EA)",
    "R-CICLO-01.atestado": "integração (atestado ausente ou recusado)",
    "R-CICLO-01.cv1_bloqueada": "veto do motor (D1 ou H4 contra o M15 — contrato r01v4 da autoridade)",
    "R-CICLO-01.cv1_desconhecido": "integração (veredito desconhecido)",
    "R-CICLO-01.incoerente": "integração (atestado incoerente com a regra do motor)",
    "R-CICLO-01.divergencia_motor_api": "divergência motor × API (regra adicional da API)",
}


def _clm_decisao(sb, bot, faltam, at, info):
    """(decisao, estado, regra, motivo). Backend, nunca cor de tela. A MESMA
    ordem do emissor R-CICLO-01 (_r01_emitir_decisao), com a divergência
    motor × API separada de falha de integração:
      · motor 'autorizada' ⇔ D1 = H4 = M15 (bt_ciclo_v1 l.391-415, assinado em
        cv1.veredito + cv2.dirs + cv1.janela.M15);
      · a API exige ALÉM disso M1 e M5 no mesmo lado (cv1.janela.M1/M5) — se o
        motor autorizou e só M1/M5 não acompanham, é DIVERGÊNCIA (regra da API),
        não integração quebrada;
      · 'autorizada' com D1/H4/M15 fora do lado o motor NUNCA produz → incoerente
        (integração)."""
    if faltam:
        return ("bloquear", "INCOMPLETO/BLOQUEADO", "CLM.leitura_obrigatoria",
                "leitura obrigatória ausente: " + ", ".join(faltam))
    if not at:
        m = info.get("motivo") or "atestado_indisponivel"
        if str(m).startswith("atestado_ausente"):
            m += " — o motor de Ciclos que assina a leitura (bt_ciclo_v1) não entregou atestado neste ambiente"
        return ("bloquear", "INCOMPLETO/BLOQUEADO", "R-CICLO-01.atestado", m)
    cv1 = at.get("cv1") or {}
    ver = cv1.get("veredito")
    if ver == "bloqueada":
        return ("bloquear", "VETADA (motor)", "R-CICLO-01.cv1_bloqueada",
                f"ciclo1_veto(bloqueada)[{cv1.get('motivo') or 'motor'}]")
    if ver == "neutra":
        return ("observar", "OBSERVAR (motor neutro)", "R-CICLO-01.cv1_neutra", "ciclo1_neutro_nao_autoriza")
    if ver != "autorizada":
        return ("bloquear", "BLOQUEADO", "R-CICLO-01.cv1_desconhecido",
                "ciclo1_veredito_desconhecido(fail_closed)")
    jan = cv1.get("janela") or {}
    dirs = (at.get("cv2") or {}).get("dirs") or {}
    lado = jan.get("M15")
    if lado not in (1, -1) or dirs.get("D1") != lado or dirs.get("H4") != lado:
        return ("bloquear", "BLOQUEADO", "R-CICLO-01.incoerente",
                f"atestado_incoerente(autorizada com D1={dirs.get('D1')} H4={dirs.get('H4')} M15={lado} — "
                "o motor só autoriza com os três no mesmo lado)")
    fora = [k for k in ("M1", "M5") if jan.get(k) != lado]
    nome = "compra" if lado == 1 else "venda"
    if fora:
        return ("bloquear", "VETADA (divergência motor × API)", "R-CICLO-01.divergencia_motor_api",
                f"motor autorizou {nome} (D1, H4 e M15 a favor); a API exige também M1 e M5 no lado e "
                + ", ".join(f"{k}={jan.get(k)}" for k in fora)
                + " — regra adicional da API, não falha de integração")
    return ("comprar" if lado == 1 else "vender", "AUTORIZADA", "R-CICLO-01.autorizada",
            "motor autorizada (D1, H4, M15) + API: M1/M5 no lado")


def _clm_origem_criterios(at, info, mot):
    """De onde vem CADA critério que pode autorizar uma abertura, e qual campo
    ASSINADO o representa nesta barra. Nada aqui decide: é a explicação do
    que a verificação e o emissor R-CICLO-01 usam."""
    cv1 = (at or {}).get("cv1") or {}
    jan = cv1.get("janela") or {}
    dirs = ((at or {}).get("cv2") or {}).get("dirs") or {}
    lt = ((mot or {}).get("leitura") or {})
    return [
        {"grupo": "Motor · Ciclo 2 (referência D1×H4 contra a direção do M15)",
         "fonte": "bt_ciclo_v1.avaliar l.391-415 → 12_veredito.topdown",
         "assinado": True,
         "campos": {"cv1.veredito": cv1.get("veredito"), "cv1.motivo": cv1.get("motivo"),
                    "cv2.dirs.D1": dirs.get("D1"), "cv2.dirs.H4": dirs.get("H4"),
                    "cv1.janela.M15": jan.get("M15")},
         "nota": "o campo chama-se cv1.veredito por legado do contrato c27r3, mas carrega o topdown "
                 "do motor, que é o critério do Ciclo 2 (D1 = H4 = M15 → autorizada; D1 ou H4 contra → bloqueada)"},
        {"grupo": "Motor · Ciclo 1 original (escada M1→M5→M15, janela 10→15, fases)",
         "fonte": "bt_ciclo_v1.avaliar l.361-388 + fases_propagacao",
         "assinado": False,
         "campos": {"estado_unico": lt.get("estado_unico"), "janela_10_15": lt.get("janela_10_15"),
                    "fase": (lt.get("fase") or {}).get("rotulo")},
         "nota": "NÃO entra no atestado nem na autorização: só telemetria (cv_motor). O motor usa a janela 10→15 "
                 "apenas para corte de posição aberta."},
        {"grupo": "API · checagens adicionais (R-CICLO-01)",
         "fonte": "_r01_ler_ciclos_servidor + _r01_emitir_decisao + r01_claim_e_comando",
         "assinado": None,
         "campos": {"cv1.janela.M1": jan.get("M1"), "cv1.janela.M5": jan.get("M5"),
                    "verificacao": info.get("estado"), "motivo": info.get("motivo")},
         "nota": "(1) HMAC + hash do token do bot + símbolo + magic + barra M15 fechada + validade 900 s; "
                 "(2) M1 e M5 no mesmo lado que M15 (direção do canal EMA20 assinada pelo motor) — regra da API, "
                 "a origem da divergência motor × API; (3) lado do comando = lado da decisão; "
                 "(4) decisão idempotente por (bot, barra, lado) e consumo único na RPC."},
    ]


def _clm_modo(bot):
    try:
        cfg = _bot_config_get(bot.get("id")) or {}
    except Exception:
        cfg = {}
    return str(cfg.get("modo_operacional") or "observar")


def _clm_avaliar(sb, bot, det, agora_ts=None):
    import time as _time_clm
    agora_ts = int(agora_ts or _time_clm.time())
    leit = _clm_leituras(det, agora_ts)
    leit["motor"] = _clm_motor_compacto(det)        # leitura ORIGINAL do motor (telemetria, não autoridade)
    c1, c2, faltam = _clm_resumo_ciclos(leit)
    at, ts, info = _clm_autoridade(sb, bot)
    dec, estado, regra, motivo = _clm_decisao(sb, bot, faltam, at, info)
    modo = _clm_modo(bot)
    execucao = ("modo observar: nenhuma decisão vira comando" if modo == "observar"
                else f"modo {modo}")
    elos = _clm_elos(det, info, leit)
    estagios = {
        "leitura_coletada": not [f for f in faltam if not f.startswith("carimbo")] and bool(leit.get("leitura_utc")),
        "ciclo_calculado": {"c1": c1["calculado"], "c2": c2["calculado"]},
        "ciclo_alinhado": {"c1": c1["alinhado"], "c2": c2["alinhado"]},
        "atestado_valido": info.get("estado") == "verificado",
        "decisao_vetada": dec == "bloquear",
        "classe_veto": _CLM_CLASSE_VETO.get(regra) if dec == "bloquear" else None,
        "decisao_autorizada": dec in ("comprar", "vender") and estado == "AUTORIZADA",
    }
    return leit, {"ciclo1": c1, "ciclo2": c2, "elos": elos, "estagios": estagios,
                  "consolidada": {"decisao": dec, "estado": estado, "regra": regra,
                                  "motivo": motivo, "modo_operacional": modo,
                                  "classe_veto": _CLM_CLASSE_VETO.get(regra) if dec == "bloquear" else None,
                                  "execucao": execucao,
                                  "fonte": "backend R-CICLO-01 (mesma verificação do emissor)"},
                  "atestado": info, "faltam": faltam,
                  "origem_criterios": _clm_origem_criterios(at, info, leit.get("motor")),
                  "barra_m15_utc": leit.get("barra_m15_utc"),
                  "versao_regras": CLM_VERSAO_REGRAS}


def _clm_trilha(sb, bot, etapa, estado, origem, motivo=None, barra=None,
                correlacao=None, ref=None):
    try:
        sb.table("ciclo_trilha").insert({
            "bot_id": (bot or {}).get("id"), "user_id": (bot or {}).get("user_id"),
            "simbolo": (bot or {}).get("simbolo"),
            "magic": _magic_do_token((bot or {}).get("bot_token") or "") if (bot or {}).get("bot_token") else None,
            "barra_m15": barra, "etapa": etapa, "estado": estado, "origem": origem,
            "motivo": (str(motivo)[:500] if motivo is not None else None),
            "correlacao": correlacao or (f"{(bot or {}).get('id')}-{barra}" if barra else None),
            "ref": ref or {},
        }).execute()
    except Exception as _e:
        try:
            print(f"[clm trilha] {_e}")
        except Exception:
            pass


def _clm_uma_vez(bot_id, chave, barra):
    st = _CLM_ESTADO_MEM.setdefault(bot_id, {"tgmt": None, "div": {}})
    if st["div"].get(chave) == barra:
        return False
    st["div"][chave] = barra
    return True


def _clm_divergencia_magic(sb, bot, magic_rec):
    import time as _t2
    barra = _dt.fromtimestamp((int(_t2.time()) // 900) * 900, _tz.utc).isoformat()
    if _clm_uma_vez(bot.get("id"), "magic", barra):
        _clm_trilha(sb, bot, "divergencia", "recusado", "api",
                    f"snapshot com magic {magic_rec} ≠ magic do bot — ignorado (não grava leitura)",
                    barra=barra, ref={"magic_recebido": magic_rec})


def _clm_agora_s():
    import time as _t
    return _t.time()


def _clm_ingerir(sb, bot, snap, det, snapshot_id=None):
    """Chamado pelo /conector/snapshot DEPOIS de gravar o snapshot. Best-effort:
    falha aqui nunca derruba o snapshot, mas fica registrada."""
    agora_ts = int(_clm_agora_s())
    bid = bot.get("id")
    try:
        st = _CLM_ESTADO_MEM.setdefault(bid, {"tgmt": None, "div": {}})
        dup = False
        tg = str((det or {}).get("tgmt") or "")
        if tg and st.get("tgmt") == tg:
            dup = True
        st["tgmt"] = tg or st.get("tgmt")
        leit, ciclos = _clm_avaliar(sb, bot, det, agora_ts)
        barra = leit.get("barra_m15_utc")
        estimada = False
        if not barra:
            estimada = True
            barra = _dt.fromtimestamp((agora_ts // 900) * 900, _tz.utc).isoformat()
        cons = ciclos["consolidada"]
        falhas = {}
        if estimada:
            falhas["barra_estimada"] = "EA sem carimbo de barra (cvt) — versão < v7.80"
        if dup:
            falhas["snapshot_duplicado"] = True
        ex = (sb.table("ciclo_leituras").select("id,n_snapshots,falhas")
              .eq("bot_id", bid).eq("barra_m15", barra).limit(1).execute().data or [])
        completa = not ciclos["faltam"]
        at = ciclos["atestado"]
        _mot = leit.get("motor") or {}
        est_at = {"estado": at.get("estado"), "motivo": at.get("motivo")}
        est_mot = _mot.get("estado") or "sem_telemetria"
        _elo_f = next((e for e in ciclos.get("elos") or [] if e.get("estado") == "falha"), None)
        corr = f"{bid}-{barra}"
        if ex:
            f0 = ex[0].get("falhas") or {}
            if dup:
                f0["duplicados"] = int(f0.get("duplicados") or 0) + 1
            upd = {"ultima_em": _dt.now(_tz.utc).isoformat(),
                   "n_snapshots": int(ex[0].get("n_snapshots") or 1) + 1,
                   "snapshot_id_ult": snapshot_id, "leituras_ult": leit}
            ref = {"snapshot_id": snapshot_id}
            # C27R15 — snapshot que chega DEPOIS do fim da validade da barra (virada: o EA ainda
            # carimba a barra anterior, ou o motor já publicou a seguinte): conta o snapshot e
            # registra UMA vez; nunca reescreve a decisão que valeu durante a barra.
            try:
                _fim_val = int(_dt.fromisoformat(str(barra)).timestamp()) + int(_R01_DEC_TTL_S)
            except Exception:
                _fim_val = None
            # C27R17 — corrida da virada (vista na plataforma em 02/out 19:30:00 UTC): a ingestão
            # começa milésimos ANTES do fim da validade e a verificação do atestado roda logo
            # DEPOIS; o relógio do início dizia "ainda na barra" e a decisão era reescrita com
            # leitura_vencida. O relógio é lido de novo aqui, depois da verificação, e um atestado
            # recusado por validade conta como pós-validade.
            _agora_fim = max(agora_ts, int(_clm_agora_s()))
            _vencida = str(est_at.get("motivo") or "").startswith("leitura_vencida")
            if _fim_val is not None and (_agora_fim >= _fim_val or _vencida) and not estimada:
                pv = f0.get("pos_validade") or {"desde": _dt.now(_tz.utc).isoformat(), "n": 0, "estados": []}
                pv["n"] = int(pv.get("n") or 0) + 1
                pv["ultimo_em"] = _dt.now(_tz.utc).isoformat()
                _chave_pv = f"{est_mot}|{est_at.get('estado')}"
                if _chave_pv not in (pv.get("estados") or []):
                    pv.setdefault("estados", []).append(_chave_pv)
                    # a decisão que valeu na barra fica; a situação ATUAL da integração é registrada
                    # à parte, uma vez por estado distinto — nada é escondido
                    _clm_trilha(sb, bot, "snapshot", "aviso", "conector",
                                f"snapshot após o fim da validade desta barra — integração AGORA: motor {est_mot}"
                                + (f" ({_mot.get('motivo')})" if est_mot != "ok" else "")
                                + f", atestado {est_at.get('estado')}"
                                + (f" ({est_at.get('motivo')})" if est_at.get("estado") != "verificado" else "")
                                + " · decisão da barra preservada",
                                barra=barra, correlacao=corr, ref=ref)
                f0["pos_validade"] = pv
                upd["falhas"] = f0 or None
                sb.table("ciclo_leituras").update(upd).eq("id", ex[0]["id"]).execute()
                return
            # transições DENTRO da barra: registradas uma única vez por mudança
            if f0.get("motor_ult") != est_mot:
                _clm_trilha(sb, bot, "motor", "ok" if est_mot == "ok" else "aviso", "conector",
                            f"motor: {f0.get('motor_ult') or '—'} → {est_mot}"
                            + (f" · {_mot.get('motivo')}" if est_mot != "ok" else
                               f" · barra {_mot.get('barra_motor_corretora')} (corretora)"),
                            barra=barra, correlacao=corr, ref=ref)
                f0["motor_ult"] = est_mot
            if (f0.get("atestado_ult") or {}).get("estado") != est_at["estado"]:
                _clm_trilha(sb, bot, "atestado", "ok" if est_at["estado"] == "verificado" else "recusado", "api",
                            (f"verificado nesta barra · motor {at.get('versao_motor')} · válido até {at.get('valido_ate')}"
                             if est_at["estado"] == "verificado" else
                             f"{at.get('motivo')} · elo que falhou: {(_elo_f or {}).get('elo')} — {(_elo_f or {}).get('motivo')}"),
                            barra=barra, correlacao=corr, ref=ref)
                cons = ciclos["consolidada"]
                _clm_trilha(sb, bot, "decisao" if cons["decisao"] != "bloquear" else "veto",
                            "ok" if cons["decisao"] != "bloquear" else "recusado", "api",
                            (f"[{cons.get('classe_veto')}] " if cons.get("classe_veto") else "") +
                            f"{cons['estado']} · {cons['decisao']} · {cons['regra']} · {cons['motivo']} · {cons['execucao']}",
                            barra=barra, correlacao=corr, ref=ref)
                f0["atestado_ult"] = est_at
                upd.update({"ciclos": ciclos, "decisao": cons["decisao"], "regra": cons["regra"],
                            "motivo": cons["motivo"]})
            upd["falhas"] = f0 or None
            sb.table("ciclo_leituras").update(upd).eq("id", ex[0]["id"]).execute()
            return
        if est_at:
            falhas["atestado_ult"] = est_at
        falhas["motor_ult"] = est_mot
        try:
            ciclos["estudo_ref"] = _ref_compacta(_ref_historica(sb, bot, leit.get("motor")))
        except Exception as _e_ref:
            ciclos["estudo_ref"] = {"situacao": "indisponivel", "mensagem": f"referência não calculada ({_e_ref})"}
        sb.table("ciclo_leituras").insert({
            "bot_id": bid, "user_id": bot.get("user_id"), "simbolo": bot.get("simbolo"),
            "magic": _magic_do_token(bot.get("bot_token") or ""),
            "barra_m15": barra, "snapshot_id": snapshot_id, "snapshot_id_ult": snapshot_id,
            "leituras": leit, "leituras_ult": leit, "ciclos": ciclos,
            "completa": completa,
            "alinhado_c1": ciclos["ciclo1"]["alinhado"], "alinhado_c2": ciclos["ciclo2"]["alinhado"],
            "decisao": cons["decisao"], "regra": cons["regra"], "motivo": cons["motivo"],
            "versoes": {"ea": (det or {}).get("eav"), "conector": (det or {}).get("conector_versao"),
                        "api": API_VERSAO.split(" ")[0], "regras": CLM_VERSAO_REGRAS},
            "falhas": falhas or None,
        }).execute()
        ref = {"snapshot_id": snapshot_id}
        _clm_trilha(sb, bot, "snapshot", "ok", "conector",
                    f"1º snapshot da barra M15 (EA {(det or {}).get('eav') or 'sem versão'})",
                    barra=barra, correlacao=corr, ref=ref)
        if estimada:
            _clm_trilha(sb, bot, "falha_coleta", "aviso", "ea",
                        "barra M15 sem carimbo (EA < v7.80) — barra estimada pelo relógio do servidor",
                        barra=barra, correlacao=corr, ref=ref)
        est = {l["tf"]: l["estado_dado"] for l in leit["linhas"]}
        n_ok = sum(1 for v in est.values() if v == "atual")
        _clm_trilha(sb, bot, "leituras", "ok" if completa else "aviso", "ea",
                    f"{n_ok}/{len(est)} TFs atuais · " + ", ".join(f"{k}:{v}" for k, v in est.items()),
                    barra=barra, correlacao=corr, ref=ref)
        c1, c2 = ciclos["ciclo1"], ciclos["ciclo2"]
        _clm_trilha(sb, bot, "ciclos", "ok" if (c1["calculado"] and c2["calculado"]) else "aviso", "api",
                    f"CALCULADO (descritivo, não autoriza) · C1 {c1['leituras_txt']}: {c1['etapa']} · "
                    f"{'ALINHADO' if c1['alinhado'] else 'NÃO alinhado'} | C2 {c2['leituras_txt']}: {c2['etapa']} · "
                    f"{'ALINHADO' if c2['alinhado'] else 'NÃO alinhado'}",
                    barra=barra, correlacao=corr, ref=ref)
        _clm_trilha(sb, bot, "motor", "ok" if est_mot == "ok" else "aviso", "conector",
                    (f"leitor do motor ok · barra {_mot.get('barra_motor_corretora')} (corretora) · "
                     f"veredito do motor {(_mot.get('leitura') or {}).get('topdown')}" if est_mot == "ok" else
                     f"{est_mot}: {_mot.get('motivo') or 'conector sem telemetria do motor'}"),
                    barra=barra, correlacao=corr, ref=ref)
        _clm_trilha(sb, bot, "atestado", "ok" if at.get("estado") == "verificado" else "recusado", "api",
                    (f"verificado · motor {at.get('versao_motor')}" if at.get("estado") == "verificado" else
                     f"{at.get('motivo')} · elo que falhou: {(_elo_f or {}).get('elo')} — {(_elo_f or {}).get('motivo')}"),
                    barra=barra, correlacao=corr, ref=ref)
        _clm_trilha(sb, bot, "decisao" if cons["decisao"] != "bloquear" else "veto",
                    "ok" if cons["decisao"] != "bloquear" else "recusado", "api",
                    (f"[{cons.get('classe_veto')}] " if cons.get("classe_veto") else "") +
                            f"{cons['estado']} · {cons['decisao']} · {cons['regra']} · {cons['motivo']} · {cons['execucao']}",
                    barra=barra, correlacao=corr, ref=ref)
        # posição no MT5 sem evento de abertura: divergência, nunca operação confirmada
        try:
            pos = int(getattr(snap, "posicoes_abertas", 0) or 0)
        except Exception:
            pos = 0
        if pos > 0:
            ab = (sb.table("babymachine_operacoes").select("id").eq("bot_id", bid)
                  .eq("status", "aberta").limit(1).execute().data or [])
            if not ab:
                _clm_trilha(sb, bot, "divergencia", "aviso", "api",
                            f"MT5 informa {pos} posição(ões) deste magic e a BabyMachine não tem operação aberta "
                            "(evento de abertura ausente) — NÃO registrada como operação",
                            barra=barra, correlacao=corr, ref=ref)
    except Exception as _e:
        try:
            print(f"[clm ingerir] {_e}")
            _clm_trilha(sb, bot, "persistencia", "falha", "api", f"ingestão da leitura falhou: {_e}")
        except Exception:
            pass


# ── ganchos na autoridade (rebind: os chamadores resolvem o nome em tempo de execução) ──
_clm_emitir_base = _r01_emitir_decisao


def _r01_emitir_decisao(sb, bot, tipo):
    ok, r = _clm_emitir_base(sb, bot, tipo)
    try:
        if ok:
            _clm_trilha(sb, bot, "persistencia", "ok", "api",
                        f"decisão {tipo} persistida em ciclo_decisoes (status={r.get('status')})",
                        barra=r.get("ts_barra"), correlacao=r.get("uid"),
                        ref={"decisao_id": r.get("id"), "uid": r.get("uid"),
                             "expira_em": r.get("expira_em")})
        else:
            _cls = ("DIVERGÊNCIA MOTOR×API" if str(r).startswith("atestado_incoerente(autorizada_com_janela")
                    else "VETO DO MOTOR" if str(r).startswith(("ciclo1_veto", "ciclo1_neutro"))
                    else "INTEGRAÇÃO/ATESTADO")
            _clm_trilha(sb, bot, "veto", "recusado", "api",
                        f"emissão {tipo} recusada [{_cls}]: {r}", ref={"tipo": tipo, "classe": _cls})
    except Exception:
        pass
    return ok, r


_clm_abrir_base = _r01_abrir_via_rpc


def _r01_abrir_via_rpc(sb, bot, tipo, params, origem):
    dec_id = (params or {}).get("decisao_id") if isinstance(params, dict) else None
    ok, r = _clm_abrir_base(sb, bot, tipo, params, origem)
    try:
        if ok:
            uid = ((r.get("params") or {}).get("uid")) if isinstance(r, dict) else None
            barra = (((r.get("params") or {}).get("decisao") or {}).get("ts_barra")) if isinstance(r, dict) else None
            _clm_trilha(sb, bot, "rpc", "ok", "rpc",
                        f"r01_claim_e_comando: decisão consumida uma única vez ({origem})",
                        barra=barra, correlacao=uid,
                        ref={"decisao_id": dec_id, "uid": uid, "comando_id": r.get("id")})
            _clm_trilha(sb, bot, "comando", "pendente", "rpc",
                        f"comando {tipo} criado em mt5_comandos", barra=barra, correlacao=uid,
                        ref={"comando_id": r.get("id"), "uid": uid})
        else:
            _clm_trilha(sb, bot, "rpc", "recusado", "rpc", f"abertura recusada: {r}",
                        ref={"decisao_id": dec_id, "origem": origem})
    except Exception:
        pass
    return ok, r


def _clm_comando_evento(sb, cmd, etapa, estado, motivo):
    try:
        if not cmd or cmd.get("tipo") not in ("buy", "sell"):
            return
        bot = None
        if cmd.get("bot_id"):
            rows = (sb.table("conector_bots").select("id,user_id,simbolo,bot_token")
                    .eq("id", cmd.get("bot_id")).limit(1).execute().data or [])
            bot = rows[0] if rows else None
        p = cmd.get("params") or {}
        _clm_trilha(sb, bot, etapa, estado, "mt5" if etapa == "resposta_mt5" else "conector", motivo,
                    barra=(p.get("decisao") or {}).get("ts_barra"), correlacao=p.get("uid"),
                    ref={"comando_id": cmd.get("id"), "uid": p.get("uid")})
    except Exception:
        pass


def _clm_bot_do_usuario(sb, uid, bot_id):
    rows = (sb.table("conector_bots").select("id,user_id,nome,simbolo,bot_token,ultimo_ping,"
                                             "conector_visto_em,posicoes_abertas,excluido,config_operacional")
            .eq("id", int(bot_id)).limit(1).execute().data or [])
    if not rows or str(rows[0].get("user_id")) != str(uid):
        raise HTTPException(status_code=404, detail="bot nao encontrado")
    return rows[0]


class ClmAoVivoIn(BaseModel):
    bot_id: int
    dias: int = 1


class ClmTrilhaIn(BaseModel):
    bot_id: int
    simbolo: Optional[str] = None
    desde: Optional[str] = None
    ate: Optional[str] = None
    barra_m15: Optional[str] = None
    etapa: Optional[str] = None
    limite: int = 300


@app.post("/learning/ciclos/ao-vivo")
def clm_ao_vivo(req: ClmAoVivoIn, authorization: str = Header(default="")):
    """Painel da Learning Machine: leitura por TF + resumo dos Ciclos +
    decisão consolidada (backend) + autoridade + contadores + saúde."""
    uid = _sessao_user_id(authorization)
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponível")
    bot = _clm_bot_do_usuario(sb, uid, req.bot_id)
    import time as _time_clm
    agora_ts = int(_time_clm.time())
    snaps = (sb.table("conector_snapshots")
             .select("id,criado_em,magic_number,simbolo,posicoes_abertas,detalhe_json")
             .eq("bot_token", bot.get("bot_token")).order("id", desc=True).limit(1).execute().data or [])
    snap = snaps[0] if snaps else None
    det = (snap or {}).get("detalhe_json") or {}
    leit, ciclos = _clm_avaliar(sb, bot, det, agora_ts)
    dias = max(1, min(30, int(req.dias or 1)))
    desde = _dt.fromtimestamp(agora_ts - dias * 86400, _tz.utc).isoformat()
    lrows = (sb.table("ciclo_leituras")
             .select("barra_m15,completa,alinhado_c1,alinhado_c2,decisao,regra,motivo,n_snapshots,falhas,"
                     "m15h:leituras_ult->m15_hist_utc")
             .eq("bot_id", bot["id"]).gte("barra_m15", desde).order("barra_m15", desc=True)
             .limit(3000).execute().data or [])
    vetos = {}
    for r in lrows:
        if r.get("decisao") == "bloquear":
            k = str(r.get("regra") or "?")
            vetos[k] = vetos.get(k, 0) + 1
    dec_rows = (sb.table("ciclo_decisoes").select("id,uid,lado,ts_barra,status,ts_emissao,ts_consumo,expira_em,veredito")
                .eq("bot_id", bot["id"]).order("ts_emissao", desc=True).limit(20).execute().data or [])
    cmd_rows = (sb.table("mt5_comandos")
                .select("id,tipo,status,origem,criado_em,entregue_em,confirmado_em,resultado,params")
                .eq("bot_id", bot["id"]).in_("tipo", ["buy", "sell"])
                .order("criado_em", desc=True).limit(20).execute().data or [])
    trilha_rpc = (sb.table("ciclo_trilha").select("ts,etapa,estado,motivo,ref")
                  .eq("bot_id", bot["id"]).in_("etapa", ["rpc", "falha_coleta", "divergencia", "persistencia"])
                  .gte("ts", desde).order("ts", desc=True).limit(200).execute().data or [])
    falhas_coleta = sum(1 for t in trilha_rpc if t.get("etapa") == "falha_coleta")
    # lacunas de barras M15 entre leituras consecutivas registradas, classificadas
    # pela lista de barras que a CORRETORA teve (EA v7.81, m15h): barra que existiu
    # e não foi registrada = ausência de COLETA; barra que não existiu = MERCADO FECHADO.
    por_barra = {}
    for r in lrows:
        try:
            por_barra[int(_dt.fromisoformat(str(r["barra_m15"]).replace("Z", "+00:00")).timestamp())] = r
        except Exception:
            pass
    ts_ord = sorted(por_barra)
    lacunas = []
    n_coleta = n_fechado = n_indet = 0
    for a, b in zip(ts_ord, ts_ord[1:]):
        falt = [x for x in range(a + 900, b, 900)]
        if not falt:
            continue
        hist = por_barra[b].get("m15h")
        tidas = set((int(x) + 900) for x in hist) if isinstance(hist, list) else None
        col = [x for x in falt if tidas is not None and x in tidas]
        fec = [x for x in falt if tidas is not None and x not in tidas and x > min(tidas or [b])]
        ind = [x for x in falt if x not in col and x not in fec]
        n_coleta += len(col); n_fechado += len(fec); n_indet += len(ind)
        lacunas.append({"depois_de": _clm_iso(a), "antes_de": _clm_iso(b),
                        "barras_faltando": len(falt), "ausencia_de_coleta": len(col),
                        "mercado_fechado": len(fec), "indeterminado": len(ind)})
    lacunas.sort(key=lambda x: x["antes_de"], reverse=True)
    dups = sum(int(((r.get("falhas") or {}).get("duplicados") or 0)) for r in lrows)
    bm_ab = (sb.table("babymachine_operacoes").select("id").eq("bot_id", bot["id"])
             .eq("status", "aberta").limit(50).execute().data or [])
    pos_mt5 = (snap or {}).get("posicoes_abertas")
    snap_idade = None
    if snap and snap.get("criado_em"):
        try:
            snap_idade = int(agora_ts - _dt.fromisoformat(str(snap["criado_em"]).replace("Z", "+00:00")).timestamp())
        except Exception:
            snap_idade = None
    magic_bot = _magic_do_token(bot.get("bot_token") or "")
    saude = {
        "mt5": ("online" if (snap_idade is not None and snap_idade <= 60) else
                ("atrasado" if snap_idade is not None else "sem snapshot")),
        "ultimo_snapshot_utc": (snap or {}).get("criado_em"), "idade_snapshot_s": snap_idade,
        "conector_visto_em": bot.get("conector_visto_em"), "ultimo_ping": bot.get("ultimo_ping"),
        "versoes": {"api": API_VERSAO.split(" ")[0], "build": BUILD_TAG,
                    "ea": det.get("eav") or "não informado (EA < v7.80)",
                    "conector": det.get("conector_versao") or "não informado pelo conector"},
        "atraso_por_tf": {l["tf"]: {"estado": l["estado_dado"], "idade_dado_s": l["idade_dado_s"]}
                          for l in leit["linhas"]},
        "lacunas_m15": lacunas[:20], "n_lacunas": len(lacunas),
        "lacunas_barras": {"ausencia_de_coleta": n_coleta, "mercado_fechado": n_fechado,
                           "indeterminado_ea_antigo": n_indet},
        "duplicados": dups,
        "divergencia_simbolo": (bool(snap) and str(snap.get("simbolo") or "") != str(bot.get("simbolo") or "")),
        "divergencia_magic": (bool(snap) and snap.get("magic_number") not in (None, magic_bot)),
        "falhas_persistencia": sum(1 for t in trilha_rpc if t.get("etapa") == "persistencia" and t.get("estado") == "falha"),
        "posicoes_mt5": pos_mt5, "operacoes_abertas_bm": len(bm_ab),
        "divergencia_posicao": (pos_mt5 is not None and int(pos_mt5 or 0) != len(bm_ab)),
    }
    _dec_por_barra = {}
    for d in dec_rows:
        _dec_por_barra[(str(d.get("ts_barra")), d.get("lado"))] = _dec_por_barra.get((str(d.get("ts_barra")), d.get("lado")), 0) + 1
    contadores = {
        "barras_analisadas": len(lrows),
        "snapshots_recebidos": sum(int(r.get("n_snapshots") or 0) for r in lrows),
        "registros_por_barra_max": 1 if lrows else 0,     # UNIQUE(bot_id, barra_m15)
        "decisoes_duplicadas": sum(1 for v in _dec_por_barra.values() if v > 1),
        "leituras_completas": sum(1 for r in lrows if r.get("completa")),
        "alinhamentos_c1": sum(1 for r in lrows if r.get("alinhado_c1")),
        "alinhamentos_c2": sum(1 for r in lrows if r.get("alinhado_c2")),
        "vetos_por_motivo": vetos,
        "decisoes_autorizadas": sum(1 for d in dec_rows if d.get("ts_emissao") and str(d["ts_emissao"]) >= desde),
        "comandos": sum(1 for c in cmd_rows if c.get("criado_em") and str(c["criado_em"]) >= desde),
        "falhas_coleta": falhas_coleta,
        "periodo_dias": dias,
    }
    autoridade = {
        "atestado": ciclos["atestado"],
        "decisoes": [{"id": (str(d.get("id") or "")[:12] + "…"), "uid": d.get("uid"),
                      "lado": d.get("lado"), "ts_barra": d.get("ts_barra"), "status": d.get("status"),
                      "ts_emissao": d.get("ts_emissao"), "ts_consumo": d.get("ts_consumo"),
                      "expira_em": d.get("expira_em"),
                      "cv1_veredito": (d.get("veredito") or {}).get("cv1_veredito"),
                      "consumo_unico": d.get("status") == "consumida"} for d in dec_rows],
        "comandos": [{"id": c.get("id"), "tipo": c.get("tipo"), "status": c.get("status"),
                      "origem": c.get("origem"), "uid": (c.get("params") or {}).get("uid"),
                      "ts_barra": (((c.get("params") or {}).get("decisao") or {}).get("ts_barra")),
                      "criado_em": c.get("criado_em"), "entregue_em": c.get("entregue_em"),
                      "confirmado_em": c.get("confirmado_em"),
                      "executada": c.get("status") == "executado",
                      "ticket": (c.get("resultado") or {}).get("ticket"),
                      "erro": (c.get("resultado") or {}).get("erro")} for c in cmd_rows],
        "recusas_rpc": [t for t in trilha_rpc if t.get("etapa") == "rpc" and t.get("estado") == "recusado"][:20],
    }
    return {"bot": {"id": bot["id"], "nome": bot.get("nome"), "simbolo": bot.get("simbolo"),
                    "magic": magic_bot},
            "gerado_utc": _dt.fromtimestamp(agora_ts, _tz.utc).isoformat(),
            "snapshot_id": (snap or {}).get("id"),
            "leituras": leit, "ciclos": ciclos, "autoridade": autoridade,
            "contadores": contadores, "saude": saude,
            "barra_registrada": _clm_barra_registrada(sb, bot, leit, ciclos, agora_ts),
            "referencia_historica": _ref_painel(sb, bot, snap, det, leit, ciclos),
            "selecao": _sel_painel(sb, bot)}


@app.post("/learning/ciclos/trilha")
def clm_trilha(req: ClmTrilhaIn, authorization: str = Header(default="")):
    uid = _sessao_user_id(authorization)
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponível")
    bot = _clm_bot_do_usuario(sb, uid, req.bot_id)
    q = (sb.table("ciclo_trilha")
         .select("id,ts,barra_m15,etapa,estado,origem,motivo,correlacao,ref,simbolo,magic")
         .eq("bot_id", bot["id"]))
    if req.simbolo:
        q = q.eq("simbolo", req.simbolo)
    if req.barra_m15:
        q = q.eq("barra_m15", req.barra_m15)
    if req.desde:
        q = q.gte("ts", req.desde)
    if req.ate:
        q = q.lte("ts", req.ate)
    if req.etapa:
        q = q.eq("etapa", req.etapa)
    rows = q.order("ts", desc=True).limit(max(1, min(2000, int(req.limite or 300)))).execute().data or []
    return {"trilha": rows, "total": len(rows)}


@app.post("/learning/ciclos/exportar")
def clm_exportar(req: ClmTrilhaIn, authorization: str = Header(default="")):
    """Trilha completa de UM ciclo (bot × barra M15): leitura registrada, trilha,
    decisões e comandos daquela barra. Sem token, segredo ou assinatura inteira."""
    uid = _sessao_user_id(authorization)
    sb = _sb_admin()
    if sb is None:
        raise HTTPException(status_code=500, detail="Supabase indisponível")
    bot = _clm_bot_do_usuario(sb, uid, req.bot_id)
    if not req.barra_m15:
        raise HTTPException(status_code=422, detail="barra_m15 obrigatoria")
    leit = (sb.table("ciclo_leituras").select("*").eq("bot_id", bot["id"])
            .eq("barra_m15", req.barra_m15).limit(1).execute().data or [])
    tri = (sb.table("ciclo_trilha").select("ts,barra_m15,etapa,estado,origem,motivo,correlacao,ref")
           .eq("bot_id", bot["id"]).eq("barra_m15", req.barra_m15).order("ts").execute().data or [])
    decs = (sb.table("ciclo_decisoes").select("uid,lado,ts_barra,status,ts_emissao,ts_consumo,expira_em,veredito")
            .eq("bot_id", bot["id"]).eq("ts_barra", req.barra_m15).execute().data or [])
    uids = [d.get("uid") for d in decs if d.get("uid")]
    cmds = []
    if uids:
        todos = (sb.table("mt5_comandos").select("id,tipo,status,origem,criado_em,entregue_em,confirmado_em,resultado,params")
                 .eq("bot_id", bot["id"]).in_("tipo", ["buy", "sell"]).limit(200).execute().data or [])
        cmds = [c for c in todos if (c.get("params") or {}).get("uid") in uids]
    for c in cmds:
        c["params"] = {"uid": (c.get("params") or {}).get("uid")}
    return {"bot": {"id": bot["id"], "nome": bot.get("nome"), "simbolo": bot.get("simbolo"),
                    "magic": _magic_do_token(bot.get("bot_token") or "")},
            "barra_m15": req.barra_m15, "leitura": leit[0] if leit else None,
            "trilha": tri, "decisoes": decs, "comandos": cmds,
            # C27R15: estudo usado como REFERÊNCIA nesta barra (id + versão) — o gravado na
            # barra e o vigente agora; nenhum dos dois participou da autorização.
            "estudo_referencia": {
                "na_barra": (((leit[0] if leit else {}) or {}).get("ciclos") or {}).get("estudo_ref"),
                "atual": _ref_compacta(_ref_historica(sb, bot))},
            # C27R19: avaliação da seleção M15/M30/H1 gravada para esta barra (modo observar)
            "selecao": ((sb.table("selecao_avaliacoes").select("barra_m15,criado_em,versao,avaliacao,acompanhamento")
                         .eq("bot_id", bot["id"]).eq("barra_m15", req.barra_m15).limit(1).execute().data or [None])[0]),
            "versao_regras": CLM_VERSAO_REGRAS, "api": API_VERSAO.split(" ")[0]}


# ╔═══════════════════════════════════════════════════════════════════════════╗
# ║  C27R19 — SELEÇÃO DE OPORTUNIDADES M15 / M30 / H1  (MODO OBSERVAR)         ║
# ║  Produtor dos sinais: os cards do Professor (professor_cards 2.0) e o      ║
# ║  resolver_entradas do Bloco 2, rodando no PC sobre o espelho do MT5 — o    ║
# ║  leitor 1.3 manda os candidatos em cv_motor.candidatos (telemetria NÃO     ║
# ║  assinada). Aqui: portões obrigatórios, ordenação e escolha, por dois      ║
# ║  contratos lado a lado:                                                    ║
# ║   · ATUAL  (referência): R-CICLO-01 r01v4 — motor "autorizada" e M1, M5,   ║
# ║     M15, D1, H4 no lado, sempre na barra M15;                              ║
# ║   · PROPOSTO (sel-1): cada candidato na escala do próprio card; D1/H4 e    ║
# ║     território viram CONTEXTO (a favor / contra / lateral), sem veto.      ║
# ║  Nada aqui emite decisão, comando ou ordem. O contrato proposto só vira    ║
# ║  autoridade depois de validado em observação e de o atestado assinar o TF. ║
# ╚═══════════════════════════════════════════════════════════════════════════╝
