_SEL_ESTUDOS_CACHE = {}
_SEL_ACOMP_MEM = {}


def _sel_estudos(sb, simbolo):
    """{(card, tf): linha} do banco de estudos do Professor (o mesmo do Admin). Cache de 10 min."""
    import time as _t
    c = _SEL_ESTUDOS_CACHE.get(simbolo)
    if c and _t.time() - c[0] < 600:
        return c[1]
    rows = (sb.table("estudo_biblioteca_v2").select(
        "id,ativo,periodo,timeframe,estrategia_id,estrategia_nome,retorno,profit_factor,win_rate,sharpe,trades,dd,"
        "wf_a_pf,wf_b_pf,origem,medido_em").eq("ativo", simbolo).execute().data or [])
    por = {}
    for r in rows:
        k = (r.get("estrategia_id"), r.get("timeframe"))
        if k not in por or str(r.get("periodo") or "") > str(por[k].get("periodo") or ""):
            por[k] = r
    _SEL_ESTUDOS_CACHE[simbolo] = (_t.time(), por)
    return por


def _sel_utc(txt_corretora, off_s, mais_s=0):
    try:
        t = _dt.strptime(str(txt_corretora)[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=_tz.utc)
        return (t + _td(seconds=int(mais_s) - int(off_s or 0))).isoformat()
    except Exception:
        return None


def _sel_num(v):
    try:
        f = float(v)
        return f if f == f else None
    except Exception:
        return None


def _sel_estudo_do_candidato(est, cand_cod):
    if not est:
        return {"existe": False, "mensagem": "célula sem estudo no banco para este ativo e timeframe"}
    tr, pf = est.get("trades") or 0, _sel_num(est.get("profit_factor")) or 0.0
    wa, wb = _sel_num(est.get("wf_a_pf")) or 0.0, _sel_num(est.get("wf_b_pf")) or 0.0
    selo = bool(tr >= 30 and pf > 1 and wa > 1 and wb > 1)
    prof = ((est.get("origem") or {}).get("professor_versao") or _REF_NR)
    return {"existe": True, "estudo_id": f"v2:{est.get('id')}", "periodo": est.get("periodo"),
            "trades": tr, "profit_factor": pf, "win_rate_pct": _sel_num(est.get("win_rate")),
            "sharpe": _sel_num(est.get("sharpe")), "retorno_pontos": _sel_num(est.get("retorno")),
            "drawdown_pontos": _sel_num(est.get("dd")), "pf_metade_1": wa, "pf_metade_2": wb,
            "selo_da_lista": selo,
            "regua_do_selo": "trades ≥ 30, PF > 1 e PF > 1 nas duas metades (régua da Lista do Seletor)",
            "equivalencia": {"nivel": "nao_comprovada",
                             "motivo": f"mesmo card e mesmo contrato de stop/saída, mas o estudo foi medido com "
                                       f"{prof} e o candidato é calculado com cards {cand_cod or _REF_NR}"},
            "limitacoes": ["comissão e slippage não registrados", "sem resultado por regime",
                           "sem avaliação fora da amostra (só estabilidade em duas metades)"],
            "nota": "métricas do período estudado; não são probabilidade desta operação"}


def _sel_velas(det, chave):
    try:
        v = _parse_candles_para_lista((det or {}).get(chave)) if (det or {}).get(chave) else []
        return v or []
    except Exception:
        return []


def _sel_vela_ohlc(v):
    try:
        if isinstance(v, dict):
            return {k: float(v.get(a) if v.get(a) is not None else v.get(b)) for k, a, b in
                    (("o", "o", "open"), ("h", "h", "high"), ("l", "l", "low"), ("c", "c", "close"))}
        return {"o": float(v[0]), "h": float(v[1]), "l": float(v[2]), "c": float(v[3])}
    except Exception:
        return None


def _sel_superiores(det, leit, por_tf, canais, off):
    """O que se sabe de cada tempo superior, com a base de cada informação:
    (a) direção do MOTOR = canal EMA20 na ÚLTIMA BARRA FECHADA (barra, OHLC, EMA20 das máximas e das
    mínimas e a condição, quando o leitor ≥ 1.4 envia); (b) conferência com o MT5 (leitor) e com a vela
    fechada do EA; (c) movimento da barra EM FORMAÇÃO (velas do EA), informado à parte."""
    chave_velas = {"D1": "cD", "H4": "c4h", "H1": "c60m", "M30": "c30m"}
    seg = {"D1": 86400, "H4": 14400, "H1": 3600, "M30": 1800}
    linhas = {l.get("tf"): l for l in ((leit or {}).get("linhas") or [])}
    out = {}
    for tf in ("M30", "H1", "H4", "D1"):
        m = (por_tf or {}).get(tf) or {}
        cn = (canais or {}).get(tf) if isinstance(canais, dict) else None
        cn = cn if isinstance(cn, dict) and not cn.get("erro") else None
        d = m.get("dir")
        bc = (cn or {}).get("barra_corretora") or m.get("barra_corretora")
        item = {"timeframe": tf, "direcao": (_SEL_ROT_DIR.get(int(d)) if d is not None else None),
                "base": "última barra FECHADA (o motor não lê barra em formação)",
                "barra_corretora": bc, "barra_abriu_utc": _sel_utc(bc, off), "barra_fechou_utc": _sel_utc(bc, off, seg[tf]),
                "regra": "alta = fechamento > EMA20 das máximas; baixa = fechamento < EMA20 das mínimas; senão lateral",
                "fonte": "motor dos Ciclos (bt_ciclo_v1.leitura_andar), sobre o espelho de barras fechadas do MT5"}
        if cn:
            item.update({"ohlc": {k: cn.get(k) for k in ("o", "h", "l", "c")},
                         "ema20_maximas": cn.get("ema20_maximas"), "ema20_minimas": cn.get("ema20_minimas"),
                         "condicao": cn.get("condicao"), "barras_no_espelho": cn.get("barras_no_espelho"),
                         "valores": "registrados pelo leitor"})
            if cn.get("dir") is not None and d is not None and int(cn["dir"]) != int(d):
                item["divergencia"] = f"canal recalculado pelo leitor dá {_SEL_ROT_DIR.get(int(cn['dir']))} e o motor informou {_SEL_ROT_DIR.get(int(d))}"
            mt = cn.get("mt5")
            item["conferencia_mt5"] = ({k: mt.get(k) for k in ("barras", "barra_corretora", "o", "h", "l", "c", "ema20_maximas",
                                                               "ema20_minimas", "mesma_barra", "ohlc_confere", "ema_confere", "nota", "erro")
                                        if k in mt} if isinstance(mt, dict) else {"situacao": "não conferido pelo leitor"})
        else:
            item["valores"] = "OHLC e EMA20 não registrados (leitor do motor anterior ao 1.4)"
            item["conferencia_mt5"] = {"situacao": "não conferido (leitor do motor anterior ao 1.4)"}
        # vela fechada do EA (dado do MT5 lido pelo EA) e barra em formação
        vs = _sel_velas(det, chave_velas[tf])
        if cn and isinstance(item.get("conferencia_mt5"), dict):
            item["conferencia_mt5"].update({k: (cn.get("mt5") or {}).get(k) for k in
                                            ("simbolo", "timeframe", "estado", "tolerancia_ohlc", "tolerancia_ema_relativa")
                                            if isinstance(cn.get("mt5"), dict) and k in cn["mt5"]})
            item["base_ema"] = cn.get("base_ema")
        if len(vs) >= 2:
            fe, fo = _sel_vela_ohlc(vs[-2]), _sel_vela_ohlc(vs[-1])
            if cn and fe:
                # antes do OHLC: mesmo símbolo e MESMA barra (carimbo cvt do EA = abertura da última fechada, hora da corretora)
                tol = max(abs(float(cn.get("c") or 0)) * 1e-6, 1e-6)
                ab_ea = None
                try:
                    ordem = ("MN1", "W1", "D1", "H4", "H1", "M30", "M15", "M5", "M1")
                    ab_ea = int(str((det or {}).get("cvt") or "").split(".")[ordem.index(tf)])
                except Exception:
                    ab_ea = None
                try:
                    ab_mot = int(_dt.strptime(str(bc)[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=_tz.utc).timestamp())
                except Exception:
                    ab_mot = None
                sim_ea = str((det or {}).get("simbolo") or "")
                ce = {"simbolo_do_ea": sim_ea or None, "timeframe": tf, "barra_do_ea_corretora": (_clm_iso(ab_ea)[:19].replace("T", " ") if ab_ea else None),
                      "barra_do_motor_corretora": bc, "tolerancia_ohlc": tol,
                      "nota": "penúltima vela do snapshot do EA (a última é a barra em formação)"}
                if cn.get("simbolo") and sim_ea and str(cn.get("simbolo")) != sim_ea:
                    ce.update({"estado": "símbolos diferentes", "confere": False})
                elif ab_ea is None or ab_mot is None:
                    ce.update({"estado": "não conferido (EA sem carimbo da barra)", "confere": None})
                elif ab_ea != ab_mot:
                    ce.update({"estado": "aguardando sincronização", "confere": None,
                               "detalhe": "motor e EA estão em barras diferentes (virada): OHLC não é comparado"})
                else:
                    okc = all(cn.get(k) is not None and abs(float(cn[k]) - fe[k]) <= tol for k in ("o", "h", "l", "c"))
                    ce.update({"estado": "confere" if okc else "diverge", "confere": okc, "ohlc_do_ea_na_ultima_fechada": fe})
                item["conferencia_ea"] = ce
            if fo:
                var = ((fo["c"] - fo["o"]) / fo["o"] * 100.0) if fo["o"] else None
                item["barra_atual"] = {"base": "barra EM FORMAÇÃO (velas do EA); não entra na direção do motor",
                                       "abriu": fo["o"], "maxima": fo["h"], "minima": fo["l"], "preco": fo["c"],
                                       "variacao_pct": (round(var, 2) if var is not None else None),
                                       "movimento": (None if var is None else ("subindo" if var > 0 else ("caindo" if var < 0 else "parada"))),
                                       "posicao_no_canal_segundo_o_ea": (linhas.get(tf) or {}).get("canal_ema20")}
        elif (linhas.get(tf) or {}).get("canal_ema20"):
            item["barra_atual"] = {"base": "preço atual frente ao canal, segundo o EA", "posicao_no_canal_segundo_o_ea": linhas[tf].get("canal_ema20")}
        out[tf] = item
    return out


def _sel_frase_superior(tf_sup, info, lado, tf_cand):
    """A frase que substitui o rótulo isolado ('D1 contra')."""
    quem = f"candidato: {'compra' if lado > 0 else 'venda'} em {tf_cand}"
    d = (info or {}).get("direcao")
    if d is None:
        return f"{tf_sup}: sem leitura do motor; {quem} — contexto indisponível, sem veto automático."
    if d == "lateral":
        return f"{tf_sup}: canal lateral na última barra fechada; {quem}; sem direção superior — contexto, sem veto automático."
    mesmo = (d == "alta") == (lado > 0)
    return (f"{tf_sup}: canal de {d} na última barra fechada; {quem}; "
            f"{'mesmo sentido' if mesmo else 'sentidos opostos'} — contexto, sem veto automático.")


def _sel_frase_atual(tf_sup, info):
    b = (info or {}).get("barra_atual") or {}
    if b.get("abriu") is None:
        return (f"{tf_sup} agora: preço {b['posicao_no_canal_segundo_o_ea']} do canal, segundo o EA." if b.get("posicao_no_canal_segundo_o_ea") else None)
    pos = b.get("posicao_no_canal_segundo_o_ea")
    return (f"{tf_sup} agora (barra em formação): abriu {b['abriu']}, preço {b['preco']}"
            + (f" ({b['variacao_pct']:+.2f}%, {b['movimento']})" if b.get("variacao_pct") is not None else "")
            + (f"; preço {pos} do canal, segundo o EA" if pos else "") + ".")


_SEL_VALIDADE_S = 1800      # 30 min a contar da confirmação (= IDADE_MAX de 1 barra M15 do executor congelado)
_SEL_COMPARABILIDADE = [
    {"item": "momento da confirmação", "medido": "o resolvedor do estudo só devolve a entrada depois que barras POSTERIORES fecham",
     "ao_vivo": "confirma com o que já fechou (conf-rt-1)", "efeito": "ao vivo o candidato aparece no instante da entrada; o estudo não muda"},
    {"item": "stop", "medido": "pivô e ATR14 do M15 lidos na PRÓPRIA barra da entrada (que ainda não fechou quando se entra)",
     "ao_vivo": "pivô e ATR14 da última M15 fechada antes da confirmação", "efeito": "stop ao vivo pode diferir do medido"},
    {"item": "gatilho em M30/H1", "medido": "posiciona a entrada na M15 que ABRE a barra de continuidade, ao preço do FECHAMENTO dela "
                                            "(preço até 15 min/45 min no futuro)",
     "ao_vivo": "confirma no fechamento da barra de continuidade, ao preço desse fechamento",
     "efeito": "o trade medido começa antes do preço existir; ao vivo começa depois — resultado não comparável barra a barra"},
    {"item": "corte do Ciclo e blindagens na entrada", "medido": "vetores do motor por barra M15",
     "ao_vivo": "mesmas regras, calculadas para a barra que abre agora; B5 (sexta) fica ligada a sexta inteira", "efeito": "pode bloquear mais às sextas"},
    {"item": "versão dos cards", "medido": "cards 1.9", "ao_vivo": "cards 2.0", "efeito": "sinais podem diferir"},
    {"item": "custos", "medido": "comissão e slippage não registrados", "ao_vivo": "spread do EA no portão 7", "efeito": "PF medido não inclui todos os custos"}]


def _sel_frescor(it, tf, off, agora_ts, barras_avaliadas=None):
    """Horários de cada candidato — sinal, confirmação, início e fim da validade — e o que já se sabia quando.
    Leitor ≥ 1.5 (cand-3): confirmação em tempo real. Leitor anterior: entrada do resolvedor retrospectivo."""
    seg = _SEL_TF_S.get(tf)
    s_ab = _rel_dt(_sel_utc(it.get("ts_sinal"), off)) if it.get("ts_sinal") else None
    rt = isinstance(it.get("confirmacao"), dict)
    out = {"contrato_da_confirmacao": (it.get("confirmacao") or {}).get("contrato") if rt else "resolvedor retrospectivo do estudo (leitor < 1.5)",
           "unidade": "tempo desde a confirmação (30 min = 2 barras M15), igual para qualquer timeframe do card",
           "origem_da_validade": "IDADE_MAX = 1 barra M15 do executor congelado (bt_vivo_sombra, Feito00185); não foi ampliada",
           "sinal_barra_abriu_utc": _rel_iso(s_ab), "sinal_barra_fechou_utc": _rel_iso(s_ab + _td(seconds=seg)) if s_ab and seg else None,
           "modo_do_sinal": it.get("modo"),
           "exibicao_na_fila": f"{it.get('validade_m15')} barras M15 (= 4 barras de {tf})"}
    e_ab = _rel_dt(_sel_utc(it.get("ts_confirmacao") or it.get("ts_entrada_m15"), off)) if (it.get("ts_confirmacao") or it.get("ts_entrada_m15")) else None
    if not e_ab:
        out.update({"confirmacao": "pendente: " + str(it.get("espera") or "entrada ainda não resolvida pelo contrato do card"),
                    "confirmado_utc": None, "vence_utc": None, "situacao": "aguardando confirmação"})
        return out
    agora = _dt.fromtimestamp(int(agora_ts), _tz.utc)
    if rt:
        vence = e_ab + _td(seconds=_SEL_VALIDADE_S)
        out.update({"confirmacao": (it.get("confirmacao") or {}).get("base"), "confirmado_utc": _rel_iso(e_ab),
                    "valida_desde_utc": _rel_iso(e_ab), "vence_utc": _rel_iso(vence),
                    "preco_de_referencia": it.get("preco_ref"), "preco_de_referencia_base": it.get("preco_ref_base"),
                    "stop_base": it.get("stop_base"),
                    "idade_s": max(0, int((agora - e_ab).total_seconds())), "restam_s": int((vence - agora).total_seconds()),
                    "alcancavel": True})
        if agora <= vence:
            out["situacao"] = "válida"
        else:
            # venceu. Foi avaliada enquanto valia? barras M15 (fechamento) com avaliação gravada dentro de [confirmação, vencimento]
            vistas = [b for b in (barras_avaliadas or []) if b is not None and e_ab <= b <= vence]
            out["avaliada_dentro_da_validade"] = bool(vistas)
            out["situacao"] = "vencida" if vistas else "entrada perdida"
            out["nota"] = ("a entrada valeu e não foi usada; o sinal não é reaproveitado" if vistas else
                           "a confirmação só foi vista depois do vencimento (não houve avaliação dentro da validade): "
                           "entrada perdida, sem reaproveitar o sinal")
        er = it.get("estudo_retro")
        out["estudo_retrospectivo"] = (dict(er, nota="entrada e stop que o resolvedor do ESTUDO devolveu depois, com barras posteriores; "
                                                     "referência histórica, não é preço disponível agora") if isinstance(er, dict) else
                                       {"situacao": "o resolvedor do estudo ainda não devolveu esta entrada (precisa de barras posteriores)"})
        return out
    # leitor antigo: regra por idade em barras M15, sobre a entrada do resolvedor retrospectivo
    vence = e_ab + _td(seconds=900 * (_SEL_IDADE_MAX_M15 + 1))
    cand_min = [e_ab + _td(seconds=1800)]
    if s_ab and seg and (str(it.get("modo") or "") == "fechamento" or (it.get("modo") is None and tf != "M15")):
        cand_min.append(s_ab + _td(seconds=2 * seg))
    visivel = max(cand_min)
    out.update({"confirmacao": "entrada resolvida pelo resolvedor retrospectivo", "confirmado_utc": _rel_iso(e_ab),
                "primeira_confirmacao_possivel_utc": _rel_iso(visivel), "vence_utc": _rel_iso(vence),
                "idade_m15_nesta_barra": it.get("idade_m15"), "alcancavel": bool(visivel <= vence),
                "situacao": "válida" if (it.get("idade_m15") is not None and int(it["idade_m15"]) <= _SEL_IDADE_MAX_M15) else "vencida"})
    if not out["alcancavel"]:
        out["aviso"] = (f"com o leitor antigo a confirmação só chega às {_rel_iso(visivel)} e a validade acaba às {_rel_iso(vence)}: "
                        f"um candidato de {tf} nunca é visto no prazo. O leitor 1.5 corrige o momento da confirmação")
    return out


def _sel_avaliar(sb, bot, det, leit, ciclos, agora_ts):
    """Avaliação da barra: candidatos por TF, portões, ordenação e escolha (ATUAL × PROPOSTO)."""
    det = det or {}
    mot = det.get("cv_motor") if isinstance(det.get("cv_motor"), dict) else {}
    cand = mot.get("candidatos") if isinstance(mot.get("candidatos"), dict) else None
    simbolo = str(bot.get("simbolo") or det.get("simbolo") or "")
    at = (ciclos or {}).get("atestado") or {}
    off = mot.get("off_ea_s")
    barra_m15 = (leit or {}).get("barra_m15_utc")
    por_tf = mot.get("por_tf") or {}
    lm = mot.get("leitura") or {}
    integ, motivos = True, []
    if not cand:
        integ = False; motivos.append("leitor sem candidatos (leitor < 1.3 ou barra sem cálculo)")
    elif cand.get("erro"):
        integ = False; motivos.append(f"cálculo dos candidatos falhou: {cand.get('erro')}")
    if mot.get("estado") != "ok":
        integ = False; motivos.append(f"motor {mot.get('estado') or 'sem telemetria'}: {mot.get('motivo') or ''}".strip())
    if at.get("estado") != "verificado":
        integ = False; motivos.append(f"atestado {at.get('estado') or 'ausente'}: {at.get('motivo') or ''}".strip())
    if cand and not cand.get("erro"):
        b_cand = _sel_utc(cand.get("barra_m15_corretora"), off, 900)
        try:
            mesma = bool(b_cand and barra_m15 and _dt.fromisoformat(b_cand) == _dt.fromisoformat(str(barra_m15)))
        except Exception:
            mesma = False
        if not mesma:
            integ = False; motivos.append(f"candidatos da barra {b_cand} ≠ barra M15 do EA {barra_m15}")
        if str(cand.get("ativo") or "") != simbolo:
            integ = False; motivos.append(f"candidatos de {cand.get('ativo')} e o bot é {simbolo}")
    preco, spr, pt = _sel_num(det.get("preco")), _sel_num(det.get("spr")), _sel_num(det.get("pt"))
    cv1 = at.get("cv1") or {}
    jan = cv1.get("janela") or {}
    d_sup = ((at.get("cv2") or {}).get("dirs") or {})
    estudos = _sel_estudos(sb, simbolo) if simbolo else {}
    cod = (cand or {}).get("codigo") or {}
    ja_escolhidos = set(); barras_avaliadas = []
    try:
        ant = (sb.table("selecao_avaliacoes").select("escolha_uid,barra_m15").eq("bot_id", bot["id"])
               .order("barra_m15", desc=True).limit(40).execute().data or [])
        ja_escolhidos = {a.get("escolha_uid") for a in ant
                         if a.get("escolha_uid") and str(a.get("barra_m15")) != str(barra_m15)}
        barras_avaliadas = [_rel_dt(a.get("barra_m15")) for a in ant if str(a.get("barra_m15")) != str(barra_m15)]
    except Exception:
        pass
    rot = {1: "alta", -1: "baixa", 0: "lateral"}
    canais = (cand or {}).get("canais") if isinstance((cand or {}).get("canais"), dict) else None
    superiores = _sel_superiores(det, leit, por_tf, canais, off)
    try:
        modo_bot = _clm_modo(bot)
    except Exception:
        modo_bot = "observar"
    grupos = {tf: {"timeframe": tf, "barra_corretora": ((cand or {}).get("tfs") or {}).get(tf, {}).get("barra_corretora"),
                   "barra_fechou_utc": _sel_utc(((cand or {}).get("tfs") or {}).get(tf, {}).get("barra_corretora"),
                                                off, _SEL_TF_S[tf]),
                   "leitura_do_ciclo": {k: (por_tf.get(tf) or {}).get(k) for k in
                                        ("dir", "estrutura", "regime", "caixa", "degrau", "gatilho_exaustao",
                                         "forca", "confianca", "volatilidade", "momentum", "eventos")},
                   "candidatos": []} for tf in SEL_TFS}
    grupos["M15"]["leitura_do_ciclo"].update({"fase": lm.get("fase"), "janela_10_15": lm.get("janela_10_15"),
                                              "classificacao": lm.get("classificacao"), "topdown": lm.get("topdown")})
    todos = []
    for it in ((cand or {}).get("itens") or []):
        tf = it.get("tf")
        if tf not in grupos:
            continue
        lado = int(it.get("lado") or 0)
        card = str(it.get("card") or "")
        est = _sel_estudo_do_candidato(estudos.get((card, tf)), cod.get("cards"))
        if est.get("existe"):
            est["comparabilidade"] = {
                "contrato_medido": "resolvedor retrospectivo do estudo (professor_bloco2.resolver_entradas, cards 1.9)",
                "contrato_ao_vivo": (it.get("confirmacao") or {}).get("contrato") or "resolvedor retrospectivo (leitor < 1.5)",
                "selo_valida_o_contrato_ao_vivo": False,
                "nota": "o selo foi medido com outro momento de confirmação e outro stop; aqui ele é só o filtro herdado do Seletor, "
                        "não é validação do contrato ao vivo",
                "diferencas": [d for d in _SEL_COMPARABILIDADE
                               if not (d["item"] == "gatilho em M30/H1" and (tf == "M15" or str(it.get("modo")) != "gatilho"))]}
        ent, stop = _sel_num(it.get("entrada")), _sel_num(it.get("stop"))
        risco = abs(ent - stop) if (ent is not None and stop is not None) else None
        dir_tf = (por_tf.get(tf) or {}).get("dir")
        P = []

        def portao(nome, ok, detalhe, proposto=False):
            P.append({"portao": nome, "ok": ok, "detalhe": detalhe, "origem": ("proposto (" + SEL_VERSAO + ")") if proposto else "existente"})

        portao("1. integridade dos dados", bool(integ), "motor ok, atestado verificado, candidatos da mesma barra"
               if integ else "; ".join(motivos)[:300])
        conf = it.get("estado") == "confirmado"
        portao("2. sinal confirmado (contrato do card)", conf,
               (("confirmado em tempo real (conf-rt-1): " + str((it.get("confirmacao") or {}).get("base") or "")) if isinstance(it.get("confirmacao"), dict)
                else "entrada resolvida pelo contrato do estudo") if conf else f"aguardando: {it.get('espera') or 'entrada não resolvida'}")
        frescor = _sel_frescor(it, tf, off, agora_ts, barras_avaliadas)
        if conf and isinstance(it.get("confirmacao"), dict):
            sit = frescor.get("situacao")
            portao("3. frescor do sinal", sit == "válida",
                   (f"confirmado às {frescor.get('confirmado_utc')}; vale até {frescor.get('vence_utc')} (restam {max(0, frescor.get('restam_s') or 0)} s)"
                    if sit == "válida" else
                    (f"ENTRADA PERDIDA: confirmado às {frescor.get('confirmado_utc')}, venceu às {frescor.get('vence_utc')} sem avaliação no prazo"
                     if sit == "entrada perdida" else
                     f"venceu às {frescor.get('vence_utc')} (confirmado às {frescor.get('confirmado_utc')})")))
        elif conf:
            idade = it.get("idade_m15")
            portao("3. frescor do sinal", idade is not None and int(idade) <= _SEL_IDADE_MAX_M15,
                   f"entrada há {idade} barra(s) M15; limite {_SEL_IDADE_MAX_M15}")
        else:
            portao("3. frescor do sinal", None, "só se avalia com o sinal confirmado")
        portao("4. corte do Ciclo contra o lado", not bool(it.get("corte_ciclo_contra_agora")),
               "sem corte do Ciclo contra o lado no M15" if not it.get("corte_ciclo_contra_agora")
               else "o Ciclo corta este lado no M15 agora")
        if est.get("existe"):
            portao("5. célula na Lista do Seletor (estudo com selo)", bool(est.get("selo_da_lista")),
                   f"PF {est['profit_factor']} · metades {est['pf_metade_1']}/{est['pf_metade_2']} · {est['trades']} trades")
        else:
            portao("5. célula na Lista do Seletor (estudo com selo)", None, est.get("mensagem"))
        if card in _SEL_REVERSAO:
            portao("6. Ciclo na escala do card", True,
                   f"card de reversão: canal do {tf} {rot.get(dir_tf, 'sem leitura')} é contexto, não veto", proposto=True)
        elif dir_tf is None:
            portao("6. Ciclo na escala do card", None, f"sem leitura do canal do {tf}", proposto=True)
        else:
            portao("6. Ciclo na escala do card", int(dir_tf) != -lado,
                   f"card de continuação {'compra' if lado > 0 else 'venda'}; canal EMA20 do {tf} {rot.get(int(dir_tf))}",
                   proposto=True)
        lim = _SEL_SPREAD_LIM.get(simbolo)
        if spr is None or pt is None or risco is None or risco <= 0:
            portao("7. custo (spread × risco)", None if conf else None,
                   "sem spread do EA ou sem stop para medir" if conf else "só se mede com entrada e stop resolvidos")
        else:
            frac = (spr * pt) / risco
            ok7 = (lim is None or spr <= lim) and frac <= _SEL_CUSTO_MAX
            portao("7. custo (spread × risco)", ok7,
                   f"spread {int(spr)} pts" + (f" (limite do ativo {lim})" if lim is not None else " (ativo sem limite cadastrado)")
                   + f" = {frac * 100:.0f}% do risco; limite {int(_SEL_CUSTO_MAX * 100)}%")
        dmax = _SEL_DESVIO_MAX.get(simbolo)
        if not conf or preco is None or ent is None or stop is None or pt is None:
            portao("8. preço atual × entrada e stop", None, "só se avalia com entrada resolvida e preço do EA")
        else:
            violado = (lado > 0 and preco <= stop) or (lado < 0 and preco >= stop)
            desvio = abs(preco - ent) / pt if pt else None
            ok8 = (not violado) and (dmax is None or (desvio is not None and desvio <= dmax))
            portao("8. preço atual × entrada e stop", ok8,
                   ("stop já violado pelo preço atual" if violado else
                    f"preço a {desvio:.0f} pts da entrada" + (f"; limite {dmax}" if dmax is not None else "; ativo sem limite cadastrado")))
        dup = it.get("uid") in ja_escolhidos
        portao("9. não repetir sinal já escolhido", not dup,
               "sinal ainda não escolhido em barra anterior" if not dup else "este mesmo sinal já foi escolhido em barra anterior",
               proposto=True)
        # contexto superior (PROPOSTO: informa; ATUAL: veta)
        ctx = {}
        frases, frases_agora = [], []
        for s in _SEL_SUPERIORES[tf]:
            d = (por_tf.get(s) or {}).get("dir")
            ctx[s] = ("sem leitura" if d is None else ("lateral" if int(d) == 0 else
                                                      ("mesmo sentido" if int(d) == lado else "sentidos opostos")))
            frases.append(_sel_frase_superior(s, superiores.get(s), lado, tf))
            fa = _sel_frase_atual(s, superiores.get(s))
            if fa:
                frases_agora.append(fa)
        ter = (cand or {}).get("territorio_h4_h1_m30")
        ctx["territorio_h4_h1_m30"] = ("neutro" if not ter else ("mesmo sentido" if int(ter) == lado else "sentidos opostos"))
        contra = [k for k in ("D1", "H4") if ctx.get(k) == "sentidos opostos"]
        ctx["resumo"] = (("sentido oposto ao de " + " e ".join(contra) + " (contexto)") if contra else
                         ("mesmo sentido de D1 e H4" if ctx.get("D1") == "mesmo sentido" and ctx.get("H4") == "mesmo sentido"
                          else "referência superior mista ou lateral"))
        ctx["frases"] = frases
        ctx["barra_atual"] = frases_agora
        ctx["papel"] = "contexto: informa e não fecha portão (contrato sel-3)"
        ctx["exigencia_do_card"] = _SEL_EXIGE_SUPERIOR.get(card) or "este card não exige alinhamento com tempos superiores"
        ctx["efeito_no_contrato_proposto"] = ("informa; não fecha portão. Reduzir risco em sentido oposto ao D1/H4 é regra do executor "
                                              "congelado (contratendência, hoje DESARMADA) e não faz parte deste contrato")
        # barreira contrária mais próxima em TFs ≥ o do card (informativo: o contrato não tem alvo fixo)
        barreira = None
        if ent is not None and risco:
            for s in (tf,) + _SEL_SUPERIORES[tf]:
                niv = _sel_num((por_tf.get(s) or {}).get("ultimo_topo" if lado > 0 else "ultimo_fundo"))
                if niv is None:
                    continue
                dist = (niv - ent) * lado
                if dist > 0 and (barreira is None or dist < barreira["dist"]):
                    barreira = {"tf": s, "nivel": niv, "dist": dist}
            if barreira:
                barreira = {"tf": barreira["tf"], "nivel": barreira["nivel"],
                            "distancia_em_R": round(barreira["dist"] / risco, 2),
                            "aviso": barreira["dist"] / risco < 1.0}
        obrig = [p for p in P]
        if any(p["ok"] is False for p in obrig if p["portao"][0] in "1"):
            estado = "sem_dados"
        elif not conf:
            estado = "aguardando" if not any(p["ok"] is False for p in obrig if p["portao"][0] in "4569") else "vetada"
        elif any(p["ok"] is None for p in obrig if p["portao"][0] in "5"):
            estado = "sem_dados"
        elif any(p["ok"] is False for p in obrig):
            estado = "vetada"
        elif any(p["ok"] is None for p in obrig):
            estado = "sem_dados"
        else:
            estado = "elegivel"
        # configuração ATUAL (referência): R-CICLO-01 r01v4 na barra M15
        dirs5 = {"M1": jan.get("M1"), "M5": jan.get("M5"), "M15": jan.get("M15"), "D1": d_sup.get("D1"), "H4": d_sup.get("H4")}
        fora = [k for k, v in dirs5.items() if v is None or int(v) != lado]
        atual_ok = bool(at.get("estado") == "verificado" and cv1.get("veredito") == "autorizada" and not fora)
        bloq_ref = bool(at.get("estado") == "verificado" and cv1.get("veredito") == "bloqueada")
        atual = {"contrato": "R-CICLO-01 r01v4 (barra M15)", "autorizaria": atual_ok,
                 "em_vigor": True, "bloqueio_por_d1_h4": bloq_ref,
                 "motivo": ("motor autorizada e M1, M5, M15, D1, H4 no lado" if atual_ok else
                            (f"atestado {at.get('estado') or 'ausente'}" if at.get("estado") != "verificado" else
                             (f"motor {cv1.get('veredito')} ({cv1.get('motivo')})" if cv1.get("veredito") != "autorizada"
                              else "fora do lado: " + ", ".join(fora))))}
        # C27R22 — motivos SEPARADOS: o que bloqueia e o que só informa, e em qual contrato
        mot_c = []
        for p_ in P:
            if p_["ok"] is True:
                continue
            n_ = p_["portao"][:1]
            if n_ == "3" and p_["ok"] is None:
                continue
            mot_c.append({"condicao": p_["portao"], "efeito": "bloqueia", "onde": "seleção (" + SEL_VERSAO + ")",
                            "situacao": "fechado" if p_["ok"] is False else "sem dado", "detalhe": p_["detalhe"],
                            "categoria": ("dados incompletos" if p_["ok"] is None else
                                          {"1": "falha de integração", "2": "sinal aguardando confirmação", "3": ("entrada perdida" if frescor.get("situacao") == "entrada perdida" else "sinal vencido"),
                                           "5": "estudo sem selo"}.get(n_, "veto operacional"))})
        for s_ in _SEL_SUPERIORES[tf]:
            if ctx.get(s_) == "sentidos opostos":
                mot_c.append({"condicao": f"{s_} em sentido oposto", "efeito": "informa", "onde": "seleção (" + SEL_VERSAO + ")",
                                "categoria": "contexto superior", "detalhe": _sel_frase_superior(s_, superiores.get(s_), lado, tf)})
        if not atual_ok:
            mot_c.append({"condicao": "autoridade em vigor não autorizaria este lado", "efeito": "bloqueia a execução",
                            "onde": "autoridade (R-CICLO-01 r01v4)",
                            "categoria": ("D1/H4 contra o M15 (veto do contrato em vigor)" if bloq_ref else "regra da autoridade"),
                            "detalhe": atual["motivo"]})
        if modo_bot == "observar":
            mot_c.append({"condicao": "bot em modo observar", "efeito": "bloqueia a execução", "onde": "modo operacional do bot",
                            "categoria": "modo observar", "detalhe": "nenhuma decisão vira comando; a avaliação é só registrada"})
        item = {"uid": it.get("uid"), "estrategia": {"card": card, "nome": it.get("nome"), "codigo": cod,
                                                     "familia": "reversão" if card in _SEL_REVERSAO else "continuação"},
                "ativo": simbolo, "timeframe": tf, "lado": "compra" if lado > 0 else "venda", "lado_num": lado,
                "sinal": {"estado": it.get("estado"), "barra_do_sinal_corretora": it.get("ts_sinal"),
                          "barra_do_sinal_utc": _sel_utc(it.get("ts_sinal"), off),
                          "entrada_m15_corretora": it.get("ts_entrada_m15"), "idade_m15": it.get("idade_m15"),
                          "modo": it.get("modo"), "nivel": it.get("nivel"), "espera": it.get("espera"),
                          "validade_na_fila_m15": it.get("validade_m15")},
                "niveis": {"entrada": ent, "stop": stop, "risco_pts": it.get("risco_pts"),
                           "entrada_base": (it.get("preco_ref_base") and ("preço de referência na confirmação: " + str(it.get("preco_ref_base"))))
                                           or "entrada do resolvedor retrospectivo do estudo (leitor < 1.5)",
                           "stop_base": it.get("stop_base") or "stop do resolvedor retrospectivo do estudo",
                           "stop_regra": "pivô do M15 ∓ 0,3×ATR14 do M15 (contrato do estudo)",
                           "saida_regra": "100% Ciclo, sem alvo fixo (contrato do estudo)"},
                "estudo": est, "contexto_superior": ctx, "barreira_contraria": barreira,
                "portoes": P, "elegibilidade": estado, "motivos": mot_c, "frescor": frescor,
                "primeiro_impedimento": (
                    next((p["portao"] + " — " + p["detalhe"] for p in P
                          if p["ok"] is False and not (estado == "vetada" and not conf and p["portao"][0] == "2")), None)
                    or next((p["portao"] + " — " + p["detalhe"] for p in P if p["ok"] is None), None)),
                "pontuacao": {"formula": "ordem da Lista do Seletor: maior PF do estudo; desempate pelo menor PF das duas "
                                         "metades, depois pela amostra. Não soma com portões: portão fechado não entra na ordem.",
                              "pf": est.get("profit_factor"),
                              "pf_metade_min": (min(est.get("pf_metade_1") or 0, est.get("pf_metade_2") or 0)
                                                if est.get("existe") else None),
                              "trades": est.get("trades")},
                "configuracao_atual": atual, "autoridade_em_vigor": atual, "escolha": None, "execucao": {"decisao": None, "comando": None, "ticket": None,
                                                                         "resultado": "modo observar: nada é executado"}}
        grupos[tf]["candidatos"].append(item); todos.append(item)

    def chave(c):
        p = c["pontuacao"]
        return (-(p.get("pf") or 0), -(p.get("pf_metade_min") or 0), -(p.get("trades") or 0), c["estrategia"]["card"], c["timeframe"])

    eleg = sorted([c for c in todos if c["elegibilidade"] == "elegivel"], key=chave)
    eleg_atual = [c for c in eleg if c["configuracao_atual"]["autorizaria"]]
    esc = eleg[0] if eleg else None
    esc_at = eleg_atual[0] if eleg_atual else None
    for c in todos:
        if esc is not None and c is esc:
            c["escolha"] = {"escolhido": True, "motivo": "maior PF do estudo entre os elegíveis"
                            + (f" (outros {len(eleg) - 1} elegíveis preteridos)" if len(eleg) > 1 else " (único elegível)")}
        elif c["elegibilidade"] == "elegivel":
            c["escolha"] = {"escolhido": False,
                            "motivo": f"preterido: PF {c['pontuacao'].get('pf')} < PF {esc['pontuacao'].get('pf')} de "
                                      f"{esc['estrategia']['nome']} {esc['timeframe']}"
                            if (c['pontuacao'].get('pf') or 0) < (esc['pontuacao'].get('pf') or 0)
                            else "preterido no desempate (metades, amostra, ordem do card)"}
        else:
            c["escolha"] = {"escolhido": False, "motivo": c.get("primeiro_impedimento") or c["elegibilidade"]}
    pos = int((bot or {}).get("posicoes_abertas") or 0)
    modo = _r01_modo_do_bot(bot) if "_r01_modo_do_bot" in globals() else str(((bot or {}).get("config_operacional") or {}).get("modo_operacional") or "observar")
    return {"versao": SEL_VERSAO, "modo": "observar", "ativo": simbolo, "barra_m15_utc": barra_m15,
            "avaliado_utc": _dt.fromtimestamp(agora_ts, _tz.utc).isoformat(),
            "contratos": {"selecao": SEL_CONTRATO, "autoridade": SEL_AUTORIDADE, "autoridade_nova": R05_CONTRATO,
                          "selecao_e_operacional": False, "r01v5_emite": False,
                          "confirmacao_em_tempo_real": bool(isinstance((cand or {}).get("confirmacao"), dict)),
                          "aviso": "a seleção (sel-3) só observa. Quem autoriza abertura hoje é a R-CICLO-01 r01v4, em que D1 ou H4 contra o M15 "
                                   "vetam. A r01v5 (D1/H4 = contexto, candidato assinado) está construída e desligada: registra apenas o que "
                                   "seria emitido",
                          "autoridade_nesta_barra": {"veredito_do_motor": cv1.get("veredito"), "motivo_do_motor": cv1.get("motivo"),
                                                     "vetou_por_d1_h4": bool(at.get("estado") == "verificado" and cv1.get("veredito") == "bloqueada")}},
            "contexto_superior": {"nota": "direção = canal EMA20 na última barra FECHADA de cada tempo; a barra em formação é informada à parte",
                                  "tempos": superiores},
            "produtor_dos_sinais": {"onde": "PC — leitor do motor", "leitor": (cand or {}).get("leitor"), "codigo": cod,
                                    "assinado": False,
                                    "nota": "candidatos são telemetria; só o atestado do motor é assinado"},
            "integridade": {"ok": bool(integ), "motivos": motivos},
            "preco_ea": preco, "spread_pts": spr, "ponto": pt,
            "contexto": {"D1": rot.get((por_tf.get("D1") or {}).get("dir")), "H4": rot.get((por_tf.get("H4") or {}).get("dir")),
                         "topdown_do_motor": cv1.get("veredito"), "motivo_do_motor": cv1.get("motivo"),
                         "territorio_h4_h1_m30": (cand or {}).get("territorio_h4_h1_m30"),
                         "blindagens_m15": (cand or {}).get("blindagens_m15")},
            "bot": {"modo_operacional": modo, "posicoes_abertas": pos,
                    "nota": ("há posição aberta: nenhuma entrada nova seria aceita" if pos else
                             "sem posição aberta")},
            "controle": {"reavaliacao": "uma vez por barra M15 fechada; a avaliação gravada não muda dentro da barra",
                         "limite_de_posicoes": "1 por bot neste ensaio (o Seletor original empilha até 5 protegidas)",
                         "duplicacao_entre_tfs": "cada célula card × TF é um candidato; só um é escolhido por barra e um "
                                                 "sinal já escolhido não é escolhido de novo",
                         "posicao_aberta": "a estratégia dona de uma posição não é trocada; a seleção só vale para entrada nova"},
            "grupos": grupos,
            "resumo": {"candidatos": len(todos), "elegiveis_proposto": len(eleg), "elegiveis_atual": len(eleg_atual),
                       "por_estado": {e: sum(1 for c in todos if c["elegibilidade"] == e)
                                      for e in ("elegivel", "aguardando", "vetada", "sem_dados")},
                       "conclusao": ("nenhuma oportunidade elegível" if not eleg else
                                     f"escolhido: {esc['estrategia']['nome']} · {esc['timeframe']} · {esc['lado']}"),
                       "conclusao_atual": ("configuração atual não autorizaria nenhum candidato" if not eleg_atual else
                                           f"configuração atual autorizaria: {esc_at['estrategia']['nome']} · {esc_at['timeframe']}"),
                       "frescor_inalcancavel": sum(1 for c in todos if (c.get("frescor") or {}).get("alcancavel") is False),
                       "entradas_perdidas": sum(1 for c in todos if (c.get("frescor") or {}).get("situacao") == "entrada perdida"),
                       "confirmados_validos": sum(1 for c in todos if (c.get("frescor") or {}).get("situacao") == "válida"),
                       "confirmacao": (cand or {}).get("confirmacao"),
                       "em_sentido_oposto_a_d1_ou_h4": sum(1 for c in todos if any((c["contexto_superior"].get(k) == "sentidos opostos") for k in ("D1", "H4"))),
                       "elegiveis_em_sentido_oposto_a_d1_ou_h4": sum(1 for c in eleg if any((c["contexto_superior"].get(k) == "sentidos opostos") for k in ("D1", "H4")))},
            "escolha": ({"uid": esc["uid"], "card": esc["estrategia"]["card"], "nome": esc["estrategia"]["nome"],
                         "timeframe": esc["timeframe"], "lado": esc["lado"], "entrada": esc["niveis"]["entrada"],
                         "stop": esc["niveis"]["stop"], "motivo": esc["escolha"]["motivo"]} if esc else None),
            "escolha_atual": ({"uid": esc_at["uid"], "card": esc_at["estrategia"]["card"],
                               "timeframe": esc_at["timeframe"], "lado": esc_at["lado"]} if esc_at else None)}


def _sel_ingerir(sb, bot, det):
    """Grava UMA avaliação por (bot, barra M15), no 1º snapshot que traz candidatos. Best-effort."""
    import time as _t
    det = det or {}
    mot = det.get("cv_motor") if isinstance(det.get("cv_motor"), dict) else None
    if not mot or not isinstance(mot.get("candidatos"), dict):
        return None
    agora_ts = int(_t.time())
    leit, ciclos = _clm_avaliar(sb, bot, det, agora_ts)
    barra = (leit or {}).get("barra_m15_utc")
    if not barra:
        return None
    ja = (sb.table("selecao_avaliacoes").select("id").eq("bot_id", bot["id"]).eq("barra_m15", barra)
          .limit(1).execute().data or [])
    if ja:
        return None
    av = _sel_avaliar(sb, bot, det, leit, ciclos, agora_ts)
    r = av["resumo"]
    try:
        av["autoridade_r01v5"] = _r05_sombra(sb, bot, det, av, agora_ts)
    except Exception as _e5:
        av["autoridade_r01v5"] = {"contrato": "R-CICLO-01 r01v5", "seria_emitida": False, "motivo": f"sombra não calculada ({str(_e5)[:120]})",
                                  "decisao_emitida": False, "comando_criado": False, "execucao_real": "nenhuma"}
    try:
        sb.table("selecao_avaliacoes").insert({
            "bot_id": bot["id"], "user_id": bot.get("user_id"), "simbolo": bot.get("simbolo") or "",
            "magic": _magic_do_token(bot.get("bot_token") or ""), "barra_m15": barra, "versao": SEL_VERSAO,
            "n_candidatos": r["candidatos"], "n_elegiveis": r["elegiveis_proposto"],
            "n_elegiveis_atual": r["elegiveis_atual"], "escolha_uid": (av.get("escolha") or {}).get("uid"),
            "escolha_atual_uid": (av.get("escolha_atual") or {}).get("uid"), "avaliacao": av}).execute()
    except Exception:
        return None                                   # corrida entre workers: a outra gravou (unique)
    _clm_trilha(sb, bot, "selecao", "ok" if av["integridade"]["ok"] else "aviso", "api",
                f"OBSERVAR · {r['candidatos']} candidato(s) em M15/M30/H1 · elegíveis: {r['elegiveis_proposto']} (proposto) / "
                f"{r['elegiveis_atual']} (autoridade r01v4) · {r['conclusao']} · contrato {SEL_VERSAO}: D1/H4 são contexto"
                + ("" if av["integridade"]["ok"] else " · integridade: " + "; ".join(av["integridade"]["motivos"])[:160]),
                barra=barra, ref={"versao": SEL_VERSAO, "escolha": (av.get("escolha") or {}).get("uid")})
    try:
        s5 = av.get("autoridade_r01v5") or {}
        if (av.get("escolha") or {}).get("uid"):
            _clm_trilha(sb, bot, "autoridade_r01v5", "ok" if s5.get("seria_emitida") else "recusado", "api",
                        ("SOMBRA · r01v5 SERIA emitida para " if s5.get("seria_emitida") else "SOMBRA · r01v5 NÃO seria emitida para ")
                        + str(av["escolha"].get("nome")) + " " + str(av["escolha"].get("timeframe")) + " " + str(av["escolha"].get("lado"))
                        + " · " + str(s5.get("motivo")) + " · " + str(s5.get("execucao_real")),
                        barra=barra, ref={"contrato": "r01v5", "candidato": av["escolha"].get("uid"),
                                          "emissao_habilitada": s5.get("emissao_habilitada")})
        if s5.get("seria_emitida") and s5.get("emissao_habilitada") and s5.get("modo_do_bot") == "automatico":
            s5 = _r05_executar_escolha(sb, bot, s5)
            sb.table("selecao_avaliacoes").update({"avaliacao": dict(av, autoridade_r01v5=s5)}).eq("bot_id", bot["id"]).eq("barra_m15", barra).execute()
    except Exception:
        pass
    return av


def _sel_acompanhar(sb, bot, det):
    """Registro PROSPECTIVO (observação, não operação): 8 barras M15 depois da avaliação, mede com as
    velas M15 do snapshot do EA quanto o preço andou a favor e contra cada candidato confirmado."""
    import time as _t
    det = det or {}
    bid = bot.get("id")
    agora = int(_t.time())
    if agora - _SEL_ACOMP_MEM.get(bid, 0) < 300:
        return
    _SEL_ACOMP_MEM[bid] = agora
    velas = _parse_candles_para_lista(det.get("c15m")) if det.get("c15m") else []
    cvt0 = str(det.get("cvt0") or "").split(".")
    try:
        ab_form = int(cvt0[6]); off = int(round((int(det.get("tsrv")) - int(det.get("tgmt"))) / 60.0)) * 60
    except Exception:
        return
    if len(velas) < 10:
        return
    n = len(velas)
    tempos = [ab_form - off - 900 * (n - 1 - k) for k in range(n)]          # abertura UTC de cada vela
    ini = _dt.fromtimestamp(agora - 17 * 900, _tz.utc).isoformat()
    fim = _dt.fromtimestamp(agora - 9 * 900, _tz.utc).isoformat()
    rows = (sb.table("selecao_avaliacoes").select("id,barra_m15,avaliacao").eq("bot_id", bid)
            .is_("acompanhamento", "null").gte("barra_m15", ini).lte("barra_m15", fim).limit(8).execute().data or [])
    for row in rows:
        try:
            t0 = int(_dt.fromisoformat(str(row["barra_m15"])).timestamp())
        except Exception:
            continue
        jan = [velas[k] for k in range(n) if t0 <= tempos[k] < t0 + 8 * 900]
        if len(jan) < 8:
            continue
        itens = {}
        for g in ((row.get("avaliacao") or {}).get("grupos") or {}).values():
            for c in g.get("candidatos") or []:
                ent, stop, lado = (c.get("niveis") or {}).get("entrada"), (c.get("niveis") or {}).get("stop"), c.get("lado_num")
                if ent is None or stop is None or not lado or abs(ent - stop) <= 0:
                    continue
                R = abs(ent - stop)
                mfe = max(((v["h"] - ent) if lado > 0 else (ent - v["l"])) for v in jan) / R
                mae = max(((ent - v["l"]) if lado > 0 else (v["h"] - ent)) for v in jan) / R
                itens[c.get("uid")] = {"elegibilidade": c.get("elegibilidade"),
                                       "escolhido": bool((c.get("escolha") or {}).get("escolhido")),
                                       "a_favor_max_R": round(mfe, 2), "contra_max_R": round(mae, 2),
                                       "tocou_o_stop": bool(mae >= 1.0),
                                       "fim_da_janela_R": round(((jan[-1]["c"] - ent) * lado) / R, 2)}
        sb.table("selecao_avaliacoes").update({"acompanhamento": {
            "janela": "8 barras M15 depois da barra avaliada", "fonte": "velas M15 do snapshot do EA",
            "medido_utc": _dt.fromtimestamp(agora, _tz.utc).isoformat(), "itens": itens,
            "nota": "observação do preço; NÃO é operação executada nem resultado de estratégia (a saída real é pelo Ciclo)"
        }}).eq("id", row["id"]).execute()


def _sel_painel(sb, bot):
    """Última avaliação gravada + histórico curto, para a BabyMachine."""
    rows = (sb.table("selecao_avaliacoes").select("barra_m15,criado_em,versao,n_candidatos,n_elegiveis,n_elegiveis_atual,"
                                                  "escolha_uid,escolha_atual_uid,avaliacao,acompanhamento")
            .eq("bot_id", bot["id"]).order("barra_m15", desc=True).limit(12).execute().data or [])
    if not rows:
        # C27R20: dizer ONDE a cadeia deste bot para, em vez de supor leitor antigo
        msg = "sem avaliação gravada: o leitor do motor precisa ser 1.3 ou superior (candidatos M15/M30/H1)"
        parou = None
        try:
            ul = (sb.table("ciclo_leituras").select("barra_m15,falhas").eq("bot_id", bot["id"])
                  .order("barra_m15", desc=True).limit(1).execute().data or [])
            fl = (ul[0].get("falhas") if ul else None) or {}
            mot = str(fl.get("motor_ult") or "")
            ate = str((fl.get("atestado_ult") or {}).get("estado") or "")
            if not ul:
                parou, msg = "snapshot", "sem avaliação gravada: nenhuma leitura deste bot chegou (cadeia para no snapshot)"
            elif mot and mot != "ok":
                parou = "motor"
                msg = ("sem avaliação gravada: a cadeia deste bot para no motor (" + mot + "). A seleção só avalia "
                       "barra com motor ok e atestado verificado" +
                       (" — o motor instalado neste PC lê outro ativo" if mot == "identidade_divergente" else ""))
            elif ate and ate != "verificado":
                parou, msg = "atestado", "sem avaliação gravada: a cadeia deste bot para no atestado (" + ate + ")"
        except Exception:
            pass
        return {"versao": SEL_VERSAO, "modo": "observar", "disponivel": False, "mensagem": msg, "parou_em": parou}
    u = rows[0]
    return {"versao": SEL_VERSAO, "modo": "observar", "disponivel": True, "gravada_em": u.get("criado_em"),
            "avaliacao": u.get("avaliacao"), "acompanhamento": u.get("acompanhamento"),
            "historico": [{"barra_m15": r.get("barra_m15"), "candidatos": r.get("n_candidatos"),
                           "elegiveis_proposto": r.get("n_elegiveis"), "elegiveis_atual": r.get("n_elegiveis_atual"),
                           "escolha": r.get("escolha_uid"), "escolha_atual": r.get("escolha_atual_uid"),
                           "acompanhado": bool(r.get("acompanhamento"))} for r in rows]}


