def _ref_v(x):
    return _REF_NR if x in (None, "", {}) else x


def _ref_pos_ranking(rows, alvo, min_trades):
    """Posição pelo MESMO critério do Admin: células com trades ≥ min e PF > 1,
    ordenadas por Sharpe (desc), dentro do mesmo ativo+período."""
    elegiveis = [r for r in rows if (r.get("trades") or 0) >= min_trades and (r.get("profit_factor") or 0) > 1]
    elegiveis.sort(key=lambda r: (r.get("sharpe") or 0), reverse=True)
    crit = f"trades ≥ {min_trades} e PF > 1, ordenado por Sharpe (desc) no mesmo ativo e período — critério da aba Estudo do Admin"
    for k, r in enumerate(elegiveis, 1):
        if r.get("estrategia_id") == alvo.get("estrategia_id") and r.get("timeframe") == alvo.get("timeframe"):
            return {"posicao": k, "de": len(elegiveis), "criterio": crit,
                    "no_top10_do_admin": k <= 10}
    return {"posicao": None, "de": len(elegiveis), "criterio": crit, "no_top10_do_admin": False,
            "motivo": "fora do ranking: não cumpre trades ≥ %d e PF > 1" % min_trades}


def _ref_estudo_v2(sb, simbolo, tf_envio, card_id):
    tf = _REF_TF_V2.get(str(tf_envio or "").lower())
    rows = (sb.table("estudo_biblioteca_v2").select("*").eq("ativo", simbolo).execute().data or [])
    if not rows:
        return None, f"banco v2 sem estudo para o ativo {simbolo}"
    meus = [r for r in rows if r.get("estrategia_id") == card_id]
    if not meus:
        return None, f"banco v2 sem o card {card_id} em {simbolo}"
    cel = next((r for r in meus if r.get("timeframe") == tf), None)
    if cel is None:
        return None, (f"banco v2 tem {card_id} em {simbolo} só nos TFs "
                      + ", ".join(sorted({r['timeframe'] for r in meus})) + f" (bot em {tf or tf_envio})")
    mesmos = [r for r in rows if r.get("periodo") == cel.get("periodo")]
    org = cel.get("origem") or {}
    car = cel.get("carimbo") or {}
    wa, wb = cel.get("wf_a_pf"), cel.get("wf_b_pf")
    return {
        "banco": "estudo_biblioteca_v2", "estudo_id": f"v2:{cel.get('id')}",
        "chave": f"{cel.get('ativo')}|{cel.get('periodo')}|{cel.get('timeframe')}|{cel.get('estrategia_id')}",
        "versao": {"professor": _ref_v(org.get("professor_versao")), "motor": _ref_v(org.get("motor_versao")),
                   "bloco1": _ref_v(org.get("bloco1_versao"))},
        "estrategia": {"id": cel.get("estrategia_id"), "nome": cel.get("estrategia_nome")},
        "ativo": cel.get("ativo"), "timeframe": cel.get("timeframe"),
        "periodo": _ref_v(cel.get("periodo")),
        "fonte_dados": _ref_v(" · ".join(x for x in (org.get("fonte"), org.get("corretora")) if x) or None),
        "parametros": {"stop": _ref_v(car.get("stop")), "saida": _ref_v(car.get("vida")),
                       "buffer_atr": _ref_v(car.get("buffer_atr"))},
        "metricas": {"trades": _ref_v(cel.get("trades")), "win_rate_pct": _ref_v(cel.get("win_rate")),
                     "profit_factor": _ref_v(cel.get("profit_factor")), "sharpe": _ref_v(cel.get("sharpe")),
                     "retorno": _ref_v(cel.get("retorno")), "retorno_unidade": "pontos",
                     "drawdown": _ref_v(cel.get("dd")), "drawdown_unidade": "pontos",
                     "pior_trade_pts": _ref_v(car.get("pior")), "mae_p95_pts": _ref_v(car.get("mae_p95")),
                     "captura_pct": _ref_v(cel.get("captura_pct"))},
        "custos": {"spread": _ref_v(org.get("spread")), "comissao": _REF_NR, "slippage": _REF_NR},
        "data_estudo": _ref_v(cel.get("medido_em")),
        # professor_cards.metricas(): meio = ponto médio do período; wf_a = PF dos trades antes,
        # wf_b = PF dos trades depois. Não há treino, otimização nem escolha de parâmetro numa
        # metade para testar na outra → é checagem de ESTABILIDADE, não fora da amostra.
        "fora_da_amostra": {"existe": False, "tipo": _REF_NR},
        "estabilidade_em_metades": {
            "existe": wa is not None and wb is not None, "tipo": _REF_ROTULO_METADES,
            "pf_metade_1": _ref_v(wa), "pf_metade_2": _ref_v(wb),
            "selo_admin": _estudo_v2_forca(cel),
            "rotulo_no_banco": "wf_a_pf / wf_b_pf (o Admin chama de walk-forward)"},
        "por_regime": None,
        "ranking": _ref_pos_ranking(mesmos, cel, 30),
    }, None


def _ref_estudo_v1(sb, ativo_envio, tf_envio, est_id):
    rows = (sb.table("estudo_biblioteca").select("*").eq("ativo", ativo_envio)
            .eq("estrategia_id", est_id).eq("timeframe", str(tf_envio or "")).execute().data or [])
    if not rows:
        return None, f"banco v1 sem {est_id} em {ativo_envio} {tf_envio}"
    rows.sort(key=lambda r: str(r.get("periodo") or ""))
    janelas = []
    for r in rows:
        p = r.get("parametros") or {}
        todos = (sb.table("estudo_biblioteca")
                 .select("estrategia_id,timeframe,trades,profit_factor,sharpe")
                 .eq("ativo", ativo_envio).eq("periodo", r.get("periodo")).execute().data or [])
        janelas.append({
            "estudo_id": f"v1:{r.get('id')}", "periodo": _ref_v(r.get("periodo")),
            "trades": _ref_v(r.get("trades")), "win_rate_pct": _ref_v(r.get("win_rate")),
            "profit_factor": _ref_v(r.get("profit_factor")), "sharpe": _ref_v(r.get("sharpe")),
            "retorno": _ref_v(r.get("retorno")), "retorno_unidade": "%",
            "drawdown": _REF_NR, "captura_pct": _ref_v(r.get("captura_pct")),
            "forca": _ref_v(r.get("forca")), "data_estudo": _ref_v(r.get("medido_em")),
            "parametros": {k: p.get(k) for k in ("stop_loss", "take_profit", "alvo_rr", "stop_min_atr",
                                                "ema_period", "max_ops", "capital") if k in p} or _REF_NR,
            "custos": {"comissao": _ref_v(p.get("comissao")), "spread": _REF_NR, "slippage": _REF_NR},
            "codigo_hash": _ref_v((r.get("codigo_hash") or "")[:16] or None),
            "regras_versao": _ref_v(r.get("regras_versao")),
            "ranking": _ref_pos_ranking(todos, r, 20)})
    return {"banco": "estudo_biblioteca", "estrategia": {"id": est_id, "nome": rows[0].get("estrategia_nome")},
            "ativo": ativo_envio, "timeframe": tf_envio,
            "fonte_dados": "yfinance (motor de backtest da plataforma) — não é a corretora",
            "versao": {"regras": _ref_v(rows[0].get("regras_versao"))},
            "fora_da_amostra": {"existe": False,
                                "tipo": "não há treino/teste; o período é cortado em 3 janelas consecutivas "
                                        "(1/3, 2/3, 3/3) e cada uma é medida em separado"},
            "por_regime": None, "janelas": janelas}, None


def _ref_regime(estudos, motor):
    tem = any((e or {}).get("por_regime") for e in estudos)
    if tem:
        return {"disponivel": True}
    if not estudos:
        return {"disponivel": False, "mensagem": "Sem estudo associado: não há desempenho histórico para comparar com o regime atual.",
                "leitura_atual_dos_ciclos": None}
    lt = (motor or {}).get("leitura") or {}
    m15 = ((motor or {}).get("por_tf") or {}).get("M15") or {}
    return {"disponivel": False,
            "mensagem": "O estudo contém desempenho agregado; não permite estimar desempenho neste regime.",
            "leitura_atual_dos_ciclos": ({"regime_m15": m15.get("regime"), "caixa_m15": m15.get("caixa"),
                                          "volatilidade_m15": m15.get("volatilidade"),
                                          "estado_unico": lt.get("estado_unico"),
                                          "classificacao": lt.get("classificacao")}
                                         if motor and motor.get("estado") == "ok" else
                                         "leitura do motor indisponível neste snapshot")}


